INSERT INTO news (posted, seq, css_class, title, body) VALUES
('2007-12-16', 0, 'news important', 'The Story', '<a name="16-12-2007" id="16-12-2007"></a>\n				<div class="news important">\n					<div class="header">The Story\n						<div>\n							16-12-2007\n						</div>\n					</div>\n					<div class="content">The following never happened.<br/>\n&nbsp;<br/>\nIn the most red-hot time of the Cold War in a secret research facility hidden deep beneath the Siberian soil, the USSR launched an unusually sly and diabolic experiment - codenamed TankTrouble.<br/>\n&nbsp;<br/>\nIn 1957 Russian scientists had developed the most devious tank simulator. Its sole purpose was to train and breed the most unscrupulous tank platoon ever to set tracks on the planet - operated by dogs! 42 dogs from the dreary and unforgiving streets of Moscow were captured and taken to the facility where training began. The dogs were relentlessly exposed to the simulator and played each other intensively. The simulator worked like a drug and they were soon more addicted to playing TankTrouble than to dog biscuits. But then it all went wrong.<br/>\n&nbsp;<br/>\nUnexpectedly, the scientists themselves got hooked. In a matter of days both scientists and dogs were stripped of all recognizable characteristics and behaviors and became violent machines. Raving mad and acting on something deeper than instincts, bloodshed was inevitable. It ended in a battle that redefined violence and there were more flying bodyparts in the air than confetti on new years eve. Knowing the Russian government would terminate the project, the lead scientist in his final breaths embedded the simulator in the dog tag of his favorite dog, Laika. He then launched Laika into space from the facility\'s rocket silo. Shortly after these events the USSR conducted a suspicious amount of nuclear tests in the Siberian tundra and the existence of the facility has never been substantiated. The USSR government confirms that they deny everything.<br/>\n&nbsp;<br/>\n<table cellpadding="0px" cellspacing="0px" style="text-align: center; margin: 10px auto 15px auto;">\n	<tr>\n		<td width="250px">\n			<img src="images/researchFacility.jpg" style="margin-bottom: 1px;" alt=""/><br/>\n		</td>\n		<td width="250px">\n			<img src="images/laika.jpg"  style="margin-bottom: 1px;" alt=""/><br/>\n		</td>\n	</tr>\n	<tr>\n		<td>\n			The top secret underground facility\n		</td>\n		<td>\n			The savage seconds before takeoff\n		</td>\n	</tr>\n</table>\nLaika and TankTrouble orbited earth 302.528 times during the past 50 years before they finally crashed at an unknown site. Thanks to sources that shall remain unknown, the TankTrouble simulator resurfaces after 50 years in orbit. Let the dogfight begin!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2007-12-24', 0, 'news standard', 'First Week Debriefing', '<a name="24-12-2007" id="24-12-2007"></a>\n				<div class="news standard">\n					<div class="header">First Week Debriefing\n						<div>\n							24-12-2007\n						</div>\n					</div>\n					<div class="content">The site is now one week old, and our most delightful fear is a reality. Judging by the number of demolished tanks in the scrapyard and the violent history of the TankTrouble simulator, we could be heading towards the beginning of the end of days.<br/>\nWe appreciate the feedback we have received and we take every suggestion and critique seriously - keep it coming! ...and by the way, our lab has a laser in the pipeline!<br/>\n&nbsp;<br/>\nTeam TankTrouble\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2007-12-25', 0, 'news attention', 'New Weapon', '<a name="25-12-2007" id="25-12-2007"></a>\n				<div class="news attention">\n					<div class="header">New Weapon\n						<div>\n							25-12-2007\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	No weapons of mass destruction in your stocking this morning? Cheer up! Just in time to save Christmas, our lab has finished a hazardous laser that\'ll vaporize your enemy in the blink of an eye. Watch out!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2007-12-27', 0, 'news standard', 'Laser Self Destruct Bug Fixed', '<a name="27-12-2007" id="27-12-2007"></a>\n				<div class="news standard">\n					<div class="header">Laser Self Destruct Bug Fixed\n						<div>\n							27-12-2007\n						</div>\n					</div>\n					<div class="content">Turned out there was a short circuit in the Laser that caused the tank to self destruct occasionally. It has now been rewired.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-01-09', 0, 'news standard', '1 Million Tanks Demolished', '<a name="09-01-2008" id="09-01-2008"></a>\n				<div class="news standard">\n					<div class="header">1 Million Tanks Demolished\n						<div>\n							09-01-2008\n						</div>\n					</div>\n					<div class="content">At 0700 hours Siberian main time the scrapyard reached one million demolished tanks. But do not worry - we have plenty in stock, so keep up the destruction! ...also our lab has a little something in the pipeline that will make the second million seem a lot closer.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-01-16', 0, 'news standard', 'Tell Some Friends About This Game', '<a name="16-01-2008" id="16-01-2008"></a>\n				<div class="news standard">\n					<div class="header">Tell Some Friends About This Game\n						<div>\n							16-01-2008\n						</div>\n					</div>\n					<div class="content">Email your loved ones and share the destruction! Tell your colleagues and heat up the office! Invite your friends and make new enemies! What are you waiting for?\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-02-02', 0, 'news attention', 'Frag Frenzy', '<a name="02-02-2008" id="02-02-2008"></a>\n				<div class="news attention">\n					<div class="header">Frag Frenzy\n						<div>\n							02-02-2008\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	Couldn\'t hit a hangar if your tank was parked inside it? Then this is the weapon for you - you are guaranteed to destroy something!<br/>\n	Word of advise though, get out of the hangar before you detonate!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-02-21', 0, 'news standard', 'Rules of engagement Have Changed', '<a name="21-02-2008" id="21-02-2008"></a>\n				<div class="news standard">\n					<div class="header">Rules of engagement Have Changed\n						<div>\n							21-02-2008\n						</div>\n					</div>\n					<div class="content">Rules of engagement just changed. Rather than stealing and exchanging points, victories are now simply counted. The new rules are applied to better fit with a super secret login system that is currently under development.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-03-02', 0, 'news standard', 'Lazy Days in the Lab and Bug Fixing', '<a name="02-03-2008" id="02-03-2008"></a>\n				<div class="news standard">\n					<div class="header">Lazy Days in the Lab and Bug Fixing\n						<div>\n							02-03-2008\n						</div>\n					</div>\n					<div class="content">After having watched Dr. Strangelove the lab scientists felt inspired to fix a few minor bugs - so minor that they are hardly worth mentioning. "Ordnung muss sein!", as they say.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-03-05', 0, 'news standard', 'Hot Disclosure Yet to be Revealed', '<a name="05-03-2008" id="05-03-2008"></a>\n				<div class="news standard">\n					<div class="header">Hot Disclosure Yet to be Revealed\n						<div>\n							05-03-2008\n						</div>\n					</div>\n					<div class="content">Something devious is cooking in the lab!<br/>\nIt\'ll be fast - it\'ll be destructive - and best of all, it\'ll fit on top of your tank!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-03-14', 0, 'news attention', 'Duck \'n\' Cover', '<a name="14-03-2008" id="14-03-2008"></a>\n				<div class="news attention">\n					<div class="header">Duck \'n\' Cover\n						<div>\n							14-03-2008\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	Fresh out of the pipeline, our lab is delighted to unleash this shiny piece of destruction: The Gatling gun. This mean machine will get a nifty amount of lead airborne in a split second.<br/>\n	It\'s breathtaking ...literally!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-03-25', 0, 'news standard', 'Gatling Gun - Comprehensive Step by Step Operating Manual', '<a name="25-03-2008" id="25-03-2008"></a>\n				<div class="news standard">\n					<div class="header">Gatling Gun - Comprehensive Step by Step Operating Manual\n						<div>\n							25-03-2008\n						</div>\n					</div>\n					<div class="content"><div style="float: right; width: 100px; right: 100px; width: 120px; height: 80px; background-image: url(images/tankWithGatlingGun.jpg);"></div>\nDespite all the good intentions of destruction it has come to our lab\'s attention that some tank drivers have been unable to destroy anything with the new Gatling Gun. Hence this guide:<br/>\n1. Pick up a crate.<br/>\n2. Locate and point at something undesirable.<br/>\n3. Press and <b>HOLD</b> your fire button.<br/>\nThe clip offers an impressive 20 pieces of lead and while dispensing your tank can still move.<br/>\nEnjoy and destroy!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-04-16', 0, 'news standard', 'Keep it Coming...', '<a name="16-04-2008" id="16-04-2008"></a>\n				<div class="news standard">\n					<div class="header">Keep it Coming...\n						<div>\n							16-04-2008\n						</div>\n					</div>\n					<div class="content">The crooked smiles of the TankTrouble lab scientists grow with every feedback that ticks in - we read it all!<br/>\nThanks to all you loyal, evil and hardworking tank drivers out there for all the &uuml;ber cool ideas.<br/>\nHere are some of the most frequent requests we get:<br/>\n&nbsp;<br/>\n<span class="text quote">"We think you should make a login system. We would really like custom tank colours."</span><br/>\nAll our resources are currently focused on developing a login system. You\'ll be able to customize your tank, keep track of your scores and more...<br/>\n&nbsp;<br/>\n<span class="text quote">"A homing missile would be awesome!!!"</span><br/>\nWe cannot reveal what\'s cooking in the classified areas but we\'ll not deny that it\'s something heatseeking that should warm up your hearts!<br/>\n&nbsp;<br/>\n<span class="text quote">"Can you make it so you can play against the computer?"</span><br/>\nFrom an unofficial russian crash site we retrieved some long lost DNA. No matter how cryptic that sounds it\'s all we can say.<br/>\n&nbsp;<br/>\n<span class="text quote">"sdsdsfedefdseefsesffessf"</span><br/>\nWe get some of these but we don\'t quite understand. Please be a bit more specific.<br/>\n&nbsp;<br/>\n<span class="text quote">"This game is awesome ;-) Could you please make more weapons?"</span><br/>\nThanks! And yes! More devious ideas have left the drawing board for prototyping...<br/>\n&nbsp;<br/>\nThank you feedbackers. Keep it coming...\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-04-30', 0, 'news standard', '10.000.000', '<a name="30-04-2008" id="30-04-2008"></a>\n				<div class="news standard">\n					<div class="header">10.000.000\n						<div>\n							30-04-2008\n						</div>\n					</div>\n					<div class="content">At 0513 hours Siberian main time the Scrapyard flipped for its tenth million time. That\'s an impressive display of destruction in the 136 days young life of the site.<br/>\nSo what did we achieve? Lots of games played, lots of destruction, 3 new weapons (too few according to some, but we are working on that), and many other, smaller updates. The lab has gained lots of experience, and armed with awesome ideas (from the feedback from you guys) our dedicated scientists are ready to embrace a more bright and violent future.<br/>\n&nbsp;<br/>\nThanks to all of you for helping us destroy all these tanks - we couldn\'t have done it without you,<br/>\nTeam TankTrouble\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-05-10', 0, 'news standard', 'Garage Open', '<a name="10-05-2008" id="10-05-2008"></a>\n				<div class="news standard">\n					<div class="header">Garage Open\n						<div>\n							10-05-2008\n						</div>\n					</div>\n					<div class="content">After many long hours of hard work, sweat is still dripping from the foreheads of our scientists as we proudly open The Garage.<br/>\nThe Garage is where you get your own personal tank. Besides bragging about owning a tank, signing up also lets you keep track of your victories,\n<img style="position: absolute;" src="images/skull.jpg"/><div style="display: inline; padding-right: 17px;"></div>kills,\n<img style="position: absolute;" src="images/cross.jpg"/><div style="display: inline; padding-right: 15px;"></div>deaths, customize your tank colours and more...<br/>\n&nbsp;<br/>\n...additional features are already on the drawing board for The Garage. So keep an eye on this newsfeed - we\'ll keep you posted. Claim your tank now - sign up in <a href="?garage" style="text-decoration: underline">The Garage</a><br/>\n&nbsp;<br/>\n<table cellpadding="0" cellspacing="0" class="text red">\n	<tr>\n		<td style="padding-right: 10px;">\n			<img src="images/attentionSign.jpg" style="width: 28px; height: 26px;">\n		</td>\n		<td>\n			The login system is still in beta. During the next month or so you may experience changes and downtime. Before moving to the final version we might reset or delete all accounts. Please <a href="mailto:laboratory@tanktrouble.com?subject=Bug Report&amp;body=Please describe the bug in detail.">report bugs</a>.\n		</td>\n	</tr>\n</table>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-05-18', 0, 'news standard', 'Recapping First Week of the Garage', '<a name="18-05-2008" id="18-05-2008"></a>\n				<div class="news standard">\n					<div class="header">Recapping First Week of the Garage\n						<div>\n							18-05-2008\n						</div>\n					</div>\n					<div class="content">About one week old, the Garage quarters 4000+ tanks and counting. Awesome!<br/>\nWe get lots of good feedback from happy tank owners. The most frequent requests are:<br/>\n&nbsp;<br/>\n<span class="text normal">1. Re-painting facility.</span> No doubt we need this. We are working hard on this one!<br/>\n<span class="text normal">2. Rankings!</span> YES! Of course. Coming soon...<br/>\n<span class="text normal">3. Upgrades and customization shop.</span> It\'s on the lab\'s to-do list...<br/>\n&nbsp;<br/>\nAs some might have noticed we have moved from version 2.0 to 2.01. This update addresses server communication issues and should have made the login system more stable.<br/>\n&nbsp;<br/>\n<table cellpadding="0" cellspacing="0" class="text red">\n	<tr>\n		<td style="padding-right: 10px;">\n			<img src="images/attentionSign.jpg" style="width: 28px; height: 26px;">\n		</td>\n		<td>\n			The login system is still in beta. During the next month or so you may experience changes and downtime. Before moving to the final version we might reset or delete all accounts. Please <a href="mailto:laboratory@tanktrouble.com?subject=Bug Report&amp;body=Please describe the bug in detail.">report bugs</a>.\n		</td>\n	</tr>\n</table>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-06-05', 0, 'news standard', 'Garage Status', '<a name="05-06-2008" id="05-06-2008"></a>\n				<div class="news standard">\n					<div class="header">Garage Status\n						<div>\n							05-06-2008\n						</div>\n					</div>\n					<div class="content">25 days old and 9000+ tank owners already!<br/>\nSo what\'s happening? While appearance hasn\'t changed, our lab has been doing numerous changes under the hood to improve performance and stability. We think we are getting there but YOU have to help us test! Please report any weird and faulty behaviors.<br/>\n&nbsp;<br/>\nAlso, the lab is working on a re-paint facility. This will make it possible to change the colour of your tank. The lab is polishing off that one as we speak.<br/>\n&nbsp;<br/>\nAnd, of course many tank owners ask for an online version saying it will spread the destruction beyond control. No doubt that\'s an awesome idea!!! The lab has begun a preliminary reconnaissance. It\'s a tough one - not likely to happen in the nearby future but we\'ll keep you posted.<br/>\n&nbsp;<br/>\nHowever, we will have rankings soonish where you will be able to compare yourself and your destructive capabilities to your friends\' and other tank owners across the planet. When is soonish you ask? Given that our scientists\' brains are close to a meltdown due to some hot test results from a top secret chili-turret-experiment, all we can promise is soonish!<br/>\n&nbsp;<br/>\n<table cellpadding="0" cellspacing="0" class="tex red">\n	<tr>\n		<td style="padding-right: 10px;">\n			<img src="images/attentionSign.jpg" style="width: 28px; height: 26px;">\n		</td>\n		<td>\n			The login system is still in beta. During the next month or so you may experience changes and downtime. Before moving to the final version we might reset or delete all accounts. Please <a href="mailto:laboratory@tanktrouble.com?subject=Bug Report&amp;body=Please describe the bug in detail.">report bugs</a>.\n		</td>\n	</tr>\n</table>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-06-10', 0, 'news standard', 'TANK POLL', '<a name="10-06-2008" id="10-06-2008"></a>\n				<div class="news standard">\n					<div class="header">TANK POLL\n						<div>\n							10-06-2008\n						</div>\n					</div>\n					<div class="content"><div id="poll-1-content" class="middle text small">The Lab gets tons of feedback on the mouse controls. Some like it. Some don\'t. Our scientists have squeezed the liquids from their brains trying to find a solution. They think this calls for a poll:<br/>&nbsp;<br/><div id="poll-1-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-1-closedSign" src="images/thisPollIsClosed.png"/></div>What do you think? The mouse control is...<br/><br/></div></div><table id="poll-1-results" style="height: 1px; margin: auto;"><tr><td><img src="images/mouseControl.jpg"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Too good - it\'s superior <span class="text tiny">(678 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Equally good <span class="text tiny">(239 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 123.37758112094px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Bad! I avoid it <span class="text tiny">(671 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 346.38643067847px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-06-18', 0, 'news standard', 'Repaint Facility Opens', '<a name="18-06-2008" id="18-06-2008"></a>\n				<div class="news standard">\n					<div class="header">Repaint Facility Opens\n						<div>\n							18-06-2008\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 131px; height: 71px; top: -24px; right: 20px;">\n	<img id="newsRepaintFacilityOpensSprayCans" src="images/sprayCans.png"/>\n</div>\n<div style="width: 580px;">\n	Finally it\'s here! The much requested repaint facility allows you to change the colours of your tank over and over! There are 10 funky colours to choose from but there will be more...<br/>\n	Go to the garage now and shake those cans!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-07-07', 0, 'news important', 'Lab Meltdown', '<a name="07-07-2008" id="07-07-2008"></a>\n				<div class="news important">\n					<div class="header">Lab Meltdown\n						<div>\n							07-07-2008\n						</div>\n					</div>\n					<div class="content">Yesterday at 0200 hours, a database crashed. The login systems are malfunctioning and the site needs a medic!<br/>\nOur scientists are themselves in the dark about it but are putting a relentless effort into solving it.<br/>\nWe\'ll keep you posted!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-07-08', 0, 'news standard', 'Forum Opens', '<a name="08-07-2008" id="08-07-2008"></a>\n				<div class="news standard">\n					<div class="header">Forum Opens\n						<div>\n							08-07-2008\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 110px; height: 90px; top: -35px; right: -8px;">\n	<img id="newsRepaintFacilityOpensSprayCans" src="images/bubble.png"/>\n</div>\n<div style="width: 560px;">\n	On high demand from oodles of TankTrouble regulars, the lab has cooked up a <a href="?forum">forum</a>.<br/>\n	Go there to discuss: What\'s good? What\'s bad? Share maneuvering tricks and dodging techniques. Probe destructive ideas, and get a finger on the pulse of the latest tank fashion.<br/>\n	The lab will be eavesdropping!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-07-08', 1, 'news important', 'Lab Meltdown - Damage Report', '<a name="08-07-2008" id="08-07-2008"></a>\n				<div class="news important">\n					<div class="header">Lab Meltdown - Damage Report\n						<div>\n							08-07-2008\n						</div>\n					</div>\n					<div class="content">The site is back online!<br/>\nDamages have been assessed after yesterday\'s devastating meltdown. The gory damage report discloses lab rats scattered all over the walls - no survivors! But far more severe: A database with all tank registrations has been irreversibly lost. You will have to sign up again. All other systems have been repaired. The site is back online and seems to be running stable. This is why we are still in beta.<br/>\n&nbsp;<br/>\n<table cellpadding="0" cellspacing="0" class="text red">\n	<tr>\n		<td style="padding-right: 10px;">\n			<img src="images/attentionSign.jpg" style="width: 28px; height: 26px;">\n		</td>\n		<td>\n			The login system is still in beta. During the next month or so you may experience changes and downtime. Before moving to the final version we might reset or delete all accounts. Please <a href="mailto:laboratory@tanktrouble.com?subject=Bug Report&amp;body=Please describe the bug in detail.">report bugs</a>.\n		</td>\n	</tr>\n</table>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-07-26', 0, 'news important', 'Lab Meltdown', '<a name="26-07-2008" id="26-07-2008"></a>\n				<div class="news important">\n					<div class="header">Lab Meltdown\n						<div>\n							26-07-2008\n						</div>\n					</div>\n					<div class="content">These last days TankTrouble have encountered yet more crashes. The cause is some dodgy, cheap servers that has turned out rather unreliable. We will move to another more dependable host ASAP! Meanwhile we\'ll keep the site running the best we can.<br/>\nKeep faith high. We do!<br/>\nThe Lab\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-08-18', 0, 'news standard', 'A Split Second of Truth', '<a name="18-08-2008" id="18-08-2008"></a>\n				<div class="news standard">\n					<div class="header">A Split Second of Truth\n						<div>\n							18-08-2008\n						</div>\n					</div>\n					<div class="content">Feedback keeps ticking in.. Lots of awesome ideas, words of acknowledgment and admission. Thanks, it\'s what keeps us going. Also there\'s some dissatisfaction with progress speed. The lab understands and thinks some explaining might help, like: <b>Who is the lab really?</b><br/>\n&nbsp;<br/>\nBeing a top-secret, super classified project, the naked truth is an unfamiliar term for us but we\'ve weaved in a little here ...maybe:<br/>\nThe lab is the collaborative brains of two <span style="text-decoration: line-through">guys</span> scientists. In <span style="text-decoration: line-through">their private residences</span> a bunker deep beneath Siberian soil these two devious minds conduct their shady experiments to develop TankTrouble. It\'s a non-profit project. The primary objective is to <span style="text-decoration: line-through">take over the world</span> have fun! <span style="text-decoration: line-through">All the underhanded governmental fundings go to prototyping, so the two scientists feed on lab rats and condensed water off the walls</span>  So to put bread on the table, the two <span style="text-decoration: line-through">guys</span> scientists are both engaged in full-time jobs in the real world.<br/>\n&nbsp;<br/>\nLong story short: We are short on time and not grey matter. We don\'t lack ideas, will and dedication. The sketch board is piled up and updates are in the pipeline!<br/>\n&nbsp;<br/>\nAgain, thanks for all your feedback and thanks for your commitment.<br/>\n&nbsp;<br/>\nThe Lab\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-08-18', 1, 'news important', 'Lab Meltdown', '<a name="18-08-2008" id="18-08-2008"></a>\n				<div class="news important">\n					<div class="header">Lab Meltdown\n						<div>\n							18-08-2008\n						</div>\n					</div>\n					<div class="content">For way too long the database has been down. Now, finally it\'s operational again. All user data was lost! ...so we start from scratch. Our backup-responsible scientist has punished himself by locking himself up with the lab rats for a week. He says "Sorry guys".\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-08-21', 0, 'news attention', 'This One Will Hit Close to Home', '<a name="21-08-2008" id="21-08-2008"></a>\n				<div class="news attention">\n					<div class="header">This One Will Hit Close to Home\n						<div>\n							21-08-2008\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	The days of hiding in the nooks and crannies of the maze are over. You are no longer safe anywhere! The new homing missile knows its way around corners so you better brush off your dodging techniques ...and fast!<br/>\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-08-23', 0, 'news standard', 'TANK POLL', '<a name="23-08-2008" id="23-08-2008"></a>\n				<div class="news standard">\n					<div class="header">TANK POLL\n						<div>\n							23-08-2008\n						</div>\n					</div>\n					<div class="content"><div id="poll-2-content" class="middle text small">With the newest weapon still hot off the assembly line, the Lab thought it would be a great time for a poll on your weapon of choice:<br/>&nbsp;<br/><div id="poll-2-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-2-closedSign" src="images/thisPollIsClosed.png"/></div>What\'s the most deadly weapon?<br/><br/></div></div><table id="poll-2-results" style="height: 1px; margin: auto;"><tr><td><img src="images/fourCrates.jpg"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Laser <span class="text tiny">(248 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 116.35388739946px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Frag Bomb <span class="text tiny">(181 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 84.919571045576px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Gatling Gun <span class="text tiny">(108 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 50.670241286863px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Homing Missile <span class="text tiny">(746 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-11-06', 0, 'news standard', 'Another Split Second of Truth', '<a name="06-11-2008" id="06-11-2008"></a>\n				<div class="news standard">\n					<div class="header">Another Split Second of Truth\n						<div>\n							06-11-2008\n						</div>\n					</div>\n					<div class="content">As you have probably noticed, updates have been scarce during the last few months. Rest assured, <span style="text-decoration: line-through">we</span> the scientists have not given up, but have been busy <span style="text-decoration: line-through">attending to our daytime jobs, which for the moment are in</span> doing research in Fiji and Los Angeles. Having spent the better part of a year working hard in <span style="text-decoration: line-through">our homes</span> the underground TankTrouble lab, <span style="text-decoration: line-through">we thus had to temporarily leave our country</span> the scientists were starting to grow mad and decided they needed a change of scenery before someone ended up impaled on one of the missiles in the silo or "accidentally" trapped in the vacuum chamber.<br/>\n&nbsp;<br/>\nThe problem is that <span style="text-decoration: line-through">we need to split the workload between us since we have differing skills</span> one needs both scientists\' keys to access the lab\'s mainframe, so it has been hard to launch new features without <span style="text-decoration: line-through">being able to meet up</span> full control over the system.<br/>\n&nbsp;<br/>\nAll has not been quiet internally, however, and we actually have two new weapons almost ready, a computer player just in need of some final tuning, plus a settings panel which allows you to customize your battles. Finally, we have cooked up a maze editor which should be ready in a couple of weeks, so all in all it\'s going to be a bloody good Christmas this year!<br/>\n&nbsp;<br/>\nAs always, thanks for your ongoing support and sorry for the holdup.<br/>\n&nbsp;<br/>\nThe Lab\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-12-16', 0, 'news standard', 'Customize Your Battles', '<a name="16-12-2008" id="16-12-2008"></a>\n				<div class="news standard">\n					<div class="header">Customize Your Battles\n						<div>\n							16-12-2008\n						</div>\n					</div>\n					<div class="content">Tired of constantly being sniped by your little brother who always happens to be at the right spot to pick up the laser? Sick of the usual, random mazes you\'ve been playing for a year now? Well, now you can customize your way out of these headaches! Through the new settings menu, you can select which weapons you want in your battles and what kind of mazes you want to play. We\'ve even thrown in a new, more fair (although harder to learn) mouse control.<br/>\n&nbsp; <br/>\nTo access the settings menu, just click the gear when playing the game. It will start spinning and once the current battle is over, the menu will pop up.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-12-16', 1, 'news standard', 'Maze Creator Launches', '<a name="16-12-2008" id="16-12-2008"></a>\n				<div class="news standard">\n					<div class="header">Maze Creator Launches\n						<div>\n							16-12-2008\n						</div>\n					</div>\n					<div class="content">Now, everybody can create their own mazes! You can save up to 3 mazes simultaneously and once your maze has been saved in the Maze Creator, you can start playing it with your friends. If your maze is approved by one of our unfair and extremely picky moderator monkeys, it will become available for everyone else to play as well.<br/>\n&nbsp;<br/>\nThe scientists want you to know that this is only the first version of the tool, so stay tuned for updates such as various traps and hazards, a maze ranking system and more. Also, they ask you to please forgive the poor graphics. The scientist with the artistic skills is still MIA - he was last seen in a mine field in Vietnam.<br/>\n&nbsp;<br/>\nNow, get to work in the <a href="?garage">Maze Creator</a>!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2008-12-18', 0, 'news important', 'Temporary Shutdown', '<a name="18-12-2008" id="18-12-2008"></a>\n				<div class="news important">\n					<div class="header">Temporary Shutdown\n						<div>\n							18-12-2008\n						</div>\n					</div>\n					<div class="content">Unfortunately, our hosting company has shut us down because we\'re starting to generate too much traffic. We are currently looking for a new hosting company and will hopefully be back in full force before you know it.<br/>\n&nbsp; <br/>\nThanks a lot for your support. It is because of you that we have achieved this shutdown :) We could not have dreamed of having so many users only one year after we opened the site.<br/>\n&nbsp;<br/>\nSee you soon. Merry Xmas and a scrappy new year!<br/>\nTeam TankTrouble\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-01-13', 0, 'news important', 'What\'s Going on?', '<a name="13-01-2009" id="13-01-2009"></a>\n				<div class="news important">\n					<div class="header">What\'s Going on?\n						<div>\n							13-01-2009\n						</div>\n					</div>\n					<div class="content">Good news from the Siberian underground. Our scientists have located a brave (or possibly just oblivious) server to host some destruction. Yihaa! It took too long, we know! Our scientists went all in during Christmas yodeling carols and munching away ginger bread. If we weren\'t short on scientists there would be severe consequences!<br/>\n&nbsp;<br/>\nHang in there, we are close!<br/>\nTeam TankTrouble\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-01-16', 0, 'news important', 'TankTrouble is Back in Business', '<a name="16-01-2009" id="16-01-2009"></a>\n				<div class="news important">\n					<div class="header">TankTrouble is Back in Business\n						<div>\n							16-01-2009\n						</div>\n					</div>\n					<div class="content">Been feeling miserable, depressed and blue? Thought all hopes were lost? Well, they were not! Forget the gloomy thoughts, squint your eyes and put your evil smile of destruction back on - TankTrouble is back!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-01-20', 0, 'news standard', 'Reviewing the Dreadful Downtime', '<a name="20-01-2009" id="20-01-2009"></a>\n				<div class="news standard">\n					<div class="header">Reviewing the Dreadful Downtime\n						<div>\n							20-01-2009\n						</div>\n					</div>\n					<div class="content">December the 18th destruction came to a standstill as TankTrouble servers crashed from massive traffic overload. Scientists, busy with cookie dough and Christmas carols, failed to fix this in their silly Christmas-nonsense. There was no excuse!<br/>\n&nbsp;<br/>\nDisheartened, crestfallen and demoralized tank owners made our mailbox overflow with frustrated words, Facebook groups were established demanding TankTrouble back, and brave server owners offered hosting. In blistering cold Siberia, in the depths of our underground lab, the scientists rediscovered a long-forgotten phenomenon called <span class="text quote">emotions</span> and with bleeding hearts and no champagne they entered 2009:<br/>\n&nbsp;<br/>\n"<span class="text quote">Since TankTrouble shut down, my life has become aimless couch cruising. Please bring TankTrouble back!</span>"<br/>\nThe laboratory atmosphere was very gloomy too.<br/>\n&nbsp;<br/>\n"<span class="text quote">Load this game up now, or I will hire assassins to tempt you!</span>"<br/>\nWe understand (but save your money, the Russian government sends \'em plenty).<br/>\n&nbsp;<br/>\nIn January the scientists finally snapped out of their jolly holiday haze and began initializing new servers. On January 16th all systems were back online and TankTrouble was unleashed again!<br/>\nTankTrouble now rests on faster, relentlessly reliable servers. Recommence destruction:<br/>\n&nbsp;<br/>\n"<span class="text quote">Thank you for bringing TankTrouble back. It makes my life worth living!!! IM A HUGE FAN!!!! LUV YA!!!</span>"<br/>\nThanks for hanging in there.<br/>\n&nbsp;<br/>\n"<span class="text quote">I think there is a special place in heaven for you. TankTrouble rocks!!!</span>"<br/>\nThanks, but we had a vote and all the scientists would rather go downstairs. See you there!<br/>\n&nbsp;<br/>\nAs for future plans, we have retrieved some doomed DNA and the lab is about to awaken something that\'s probably better left undisturbed (that\'s of course not going to stop us). So keep your eyes peeled, it will hit you soon - too soon! That\'s all we can say for now...<br/>\n&nbsp;<br/>\nThank you all for your dedicated patience and for hanging in there. We depend on you!<br/>\nCheck out TankTrouble on <a href="http://www.facebook.com/s.php?ref=search&init=q&q=tank+trouble" target="_blank">Facebook</a> or how about some crazy, enthusiastic fan footage on <a href="http://www.youtube.com/results?search_type=&search_query=%22tank+trouble%22&aq=-1" target="_blank">YouTube</a>?<br/>\n&nbsp;<br/>\nTeam TankTrouble\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-01-22', 0, 'news lab', 'Opening the Lab ...WHOOPS &#35;&#36;&#37;&#191;&#167;&#165;!!!', '<a name="22-01-2009" id="22-01-2009"></a>\n				<div class="news lab">\n					<div class="header">Opening the Lab ...WHOOPS &#35;&#36;&#37;&#191;&#167;&#165;!!!\n						<div>\n							22-01-2009\n						</div>\n					</div>\n					<div class="content"><div style="padding-left: 49px; background-image: url(\'images/testTubeSmall.jpg\'); background-repeat: no-repeat;">\n	Yesterday one of our rookie scientists, having been bitten by our latest experiment and hence in a temporary (or possibly permanent) subhuman state, happened to overwrite some files and thereby opening <span class="text qoute">The Lab</span>. It was originally meant never to see the light of day, but we decided to let it be. We will use it for all the odd experiments, and make you the guinea pig.<br/>\n	&nbsp;<br/>\n	The Lab\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-01-24', 0, 'news lab', 'Bring Destruction to Your Own Website or Blog!', '<a name="24-01-2009" id="24-01-2009"></a>\n				<div class="news lab">\n					<div class="header">Bring Destruction to Your Own Website or Blog!\n						<div>\n							24-01-2009\n						</div>\n					</div>\n					<div class="content"><div style="padding-left: 49px; background-image: url(\'images/testTubeSmall.jpg\'); background-repeat: no-repeat;">\n	The Lab often gets requests from webmasters wanting Tanktrouble on their site. Wahoo, it\'s now possible! Just follow the instructions in <a href="?lab">The Lab</a> and watch your traffic skyrocket!<br/>\n	&nbsp;<br/>\n	The Lab\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-01-26', 0, 'news standard', 'Grrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr.........', '<a name="26-01-2009" id="26-01-2009"></a>\n				<div class="news standard">\n					<div class="header">Grrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrrr.........\n						<div>\n							26-01-2009\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 108px;">\n	<div id="newsLaika" style="position: absolute; top: -60px; left: 5px; width: 140px; height: 250px;"></div>\n</div>\n<script type="text/javascript">\n	<!--\n	var sy = new SWFObject("includes/laika02.swf", "laika", "140", "250", "8", "#ffffff");\n	sy.addParam("allowScriptAccess", "sameDomain");\n	sy.addParam("menu", "false");\n	sy.addParam("quality", "best");\n	sy.addParam("wmode", "transparent");\n	sy.write("newsLaika");\n	// -->\n</script>\n<div style="padding-left: 150px;">\n	For years the Russian government has searched for the crash site of space dog Laika\'s satellite in order to forever destroy the last possible evidence of their disastrous Cold War project that went terribly wrong. They never found it. We did!<br/>\n	In the depths of the Pacific abyss, TankTrouble researchers located the satellite wreck and retrieved the clues and answers to some of the questions of this strictly confidential incident.<br/>\n	Now, after many dark hours of grim and dreadful experiments in the laboratory\'s deepest pits, behind armed pulse beam doors, TankTrouble scientists have awoken something they shouldn\'t have.<br/>\n	From the DNA recovered from the secret crash site, our scientists were able to grow 52&#37; of Russian space dog Laika\'s brain tissue. Then they wired it to a pneumatic-powered titanium body and the lead scientists engaged Laika\'s nuclear core - the last thing they ever did.<br/>\n	After a long and brutal battle, we have managed to contain this monster and have wired her brain to the TankTrouble simulator. There are still some short circuits and the brain is still only working based on the most basic instincts.<br/>\n	The space dog is back!<br/>\n	&nbsp;<br/>\n	<a href="#16-12-2007">Who is Laika? Read the story that never happened here...</a>\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-02-01', 0, 'news standard', 'Mouse Control Improved', '<a name="01-02-2009" id="01-02-2009"></a>\n				<div class="news standard">\n					<div class="header">Mouse Control Improved\n						<div>\n							01-02-2009\n						</div>\n					</div>\n					<div class="content">The days of cursing the mouse, as your tank got stuck in the top of the maze, are history! With the new, improved mouse control, your tank will follow the mouse cursor whether it\'s inside maze bounds or not - sweet!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-02-02', 0, 'news important', 'The Most Dangerous Pneumatic Titanium Dog in the World', '<a name="02-02-2009" id="02-02-2009"></a>\n				<div class="news important">\n					<div class="header">The Most Dangerous Pneumatic Titanium Dog in the World\n						<div>\n							02-02-2009\n						</div>\n					</div>\n					<div class="content">Though raving mad, Laika is in high demand - everybody wants to blow her up! Understandable. In her first days, she has already blown up 200.000+ of YOUR tanks and is without doubt the most dangerous pneumatic titanium dog to have ever barked! However, this fast paced, out-of-control killing frenzy is pushing servers to the max and has caused some core mechanisms to fail. As thrilled as we are for having unleashed this creature, we are equally frustrated about these breakdowns. Our most brainy scientists have put on their thickest eyeglasses and dug themselves deep down into the bits and bytes of the core scripts to resolve the problem. We will keep you posted...\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-02-04', 0, 'news important', 'Back Online?', '<a name="04-02-2009" id="04-02-2009"></a>\n				<div class="news important">\n					<div class="header">Back Online?\n						<div>\n							04-02-2009\n						</div>\n					</div>\n					<div class="content">Some core scripts keep failing. So far the bugs have outmaneuvered our Scientists but they are doing everything possible to smoke \'em out! In the heat of the battle we have disabled custom mazes temporarily.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-02-20', 0, 'news important', 'Dedicated German Kraftwerk', '<a name="20-02-2009" id="20-02-2009"></a>\n				<div class="news important">\n					<div class="header">Dedicated German Kraftwerk\n						<div>\n							20-02-2009\n						</div>\n					</div>\n					<div class="content">Server failures have put the whole lab in distress for weeks. Our scientists sweated blood adding a malodorous stench to the already uneasy atmosphere. They have squeezed their brains out trying to crack the meltdowns. Now, we have finally put them to rest. Let\'s go back in time...<br/>\n&nbsp;<br/>\n16th of December: The lab unleashes the devastating 52% Laika clone whom, before contained, munched a scientist or two. Laika destroys 200.000+ tanks and redefines destruction!<br/>\n&nbsp;<br/>\n18th of december: The killing frenzy is out of control and in the end it kills the server. TankTrouble is down! This dreadful day will forever remain a black hole in the history of TankTrouble.<br/>\n&nbsp;<br/>\n16th of January: A good deal of weeping, Christmas cookies and hard work later TankTrouble was moved to new servers and back online. Fans, ready to deem this a national holiday, wrote heart-rending feedback. The lab held hands and for a minute of silence the only sound was the soft impact between the concrete floor and the scientists\' tears of joy. But bliss was short...<br/>\n&nbsp;<br/>\n21st of January: A series of meltdowns started. Panic spreads in the Lab. All scientists are taken of their current projects to assist in locating the source. The next 29 days would be a bumpy ride with the server going up and down faster than a cow tit in the hands of a trained cowgirl. Apocalyptical frustration and doomsday-thoughts tormented the Russian underground.<br/>\n&nbsp;<br/>\n19th of February: The lab concludes there are no bugs eating up server resources. The problem is the server. It was all we could afford but we still blame it on our intern who picked up the ancient artifact at the local flee market. Him and the server have now left the complex through the rocket silo.<br/>\n&nbsp;<br/>\n20th of February, yesterday: Scientists cancelled their upcoming annual highlight; an excursion to the surface and rolls with jam. With the money saved and the coins from the vending machine, the lab to invested in a dedicated server.<br/>\n&nbsp;<br/>\nTankTrouble is now residing on a German kraftwerk. With this state-of-the-art monster in place, the lab believes that the time of the meltdowns is now merely a closed chapter of horror that will slowly, like the half-life of Uranium, fade in our memories.<br/>\n&nbsp;<br/>\nThe Lab\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-02-21', 0, 'news standard', 'Forum Improved', '<a name="21-02-2009" id="21-02-2009"></a>\n				<div class="news standard">\n					<div class="header">Forum Improved\n						<div>\n							21-02-2009\n						</div>\n					</div>\n					<div class="content">We handpicked some moderators to clean up our messy forum. The forum now has less crap, it\'s more fun, and provides a better soil for fruitful discussions. We think the moderators are doing a good job and decided to put their names under the discussions they moderate. With that and a bunch of other minor improvements, though mostly visible for the hardworking moderators, we hope to improve the forum even further.<br/>\nThough we rarely write, we read almost everything you write. And we listen! Engage yourself, articulate your ideas in the forum and impact TankTrouble development!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-02-24', 0, 'news standard', 'Winter Fashion', '<a name="24-02-2009" id="24-02-2009"></a>\n				<div class="news standard">\n					<div class="header">Winter Fashion\n						<div>\n							24-02-2009\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 131px; height: 71px; top: -34px; right: 10px;">\n	<img id="newsWinterFashion" src="images/sprayCansWinterFashion.png"/>\n</div>\n<div style="width: 520px;">\n	Repaint your tank in the cool and crisp winter fashion colors. Available for a limited time only! So hurry up to the <a href="?garage">garage</a> and take your tank for a stroll down the catwalk.\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-03-08', 0, 'news standard', 'Return of the Maze Creator', '<a name="08-03-2009" id="08-03-2009"></a>\n				<div class="news standard">\n					<div class="header">Return of the Maze Creator\n						<div>\n							08-03-2009\n						</div>\n					</div>\n					<div class="content"><div style="float: right; right: 100px; width: 49px; height: 44px; background-image: url(images/maze.jpg);"></div>\nThe lab is proud to announce: The maze creator is back!<br/>\nAnd we even improved it some! Log in, go to the <a href="?garage">Garage</a> and get started...<br/>\n&nbsp;<br/>\n(You can play other tank owner\'s mazes too! Click the gear button during the game to see how.)\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-03-10', 0, 'news standard', 'TANK POLL', '<a name="10-03-2009" id="10-03-2009"></a>\n				<div class="news standard">\n					<div class="header">TANK POLL\n						<div>\n							10-03-2009\n						</div>\n					</div>\n					<div class="content"><div id="poll-3-content" class="middle text small">In its fairly short life Laika has destroyed 2.000.000+ tanks. Have our scientists awakened the meanest pneumatic-powered titanium dog ever or is it just plain lucky? It\'s time for a poll:<br/>&nbsp;<br/><div id="poll-3-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-3-closedSign" src="images/thisPollIsClosed.png"/></div>How hard is Laika?<br/><br/></div></div><table id="poll-3-results" style="height: 1px; margin: auto;"><tr><td><img src="images/laikaSmall.jpg"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Too hard! A mean killing machine <span class="text tiny">(1421 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 238.42281879195px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Hard <span class="text tiny">(746 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 125.1677852349px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Medium <span class="text tiny">(1447 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 242.78523489933px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Easy <span class="text tiny">(1023 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 171.64429530201px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											It\'s rubbish. Put it out of its misery! <span class="text tiny">(2086 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-03-29', 0, 'news standard', 'Laika Does Not Take Critique Lightly', '<a name="29-03-2009" id="29-03-2009"></a>\n				<div class="news standard">\n					<div class="header">Laika Does Not Take Critique Lightly\n						<div>\n							29-03-2009\n						</div>\n					</div>\n					<div class="content">As a result of the latest poll, Laika is furious!<br/>\nConsequently, during and shortly after the poll she added another 1.000.000 tanks to her nonexistent conscience.<br/>\n&nbsp<br/>\nWe get much feedback requesting to make Laika easier or offer a difficulty setting. We can\'t! Laika is unapproachable, raving mad and locked up behind multiple pulse beam reinforced steel doors in the depths of our underground complex. Laika is beyond the scientists\' control!<br/>\n&nbsp;<br/>\n<span class="text tiny">...and besides, have you ever heard of a pneumatic dog on a killing frenzy with a difficulty setting? We haven\'t!</span>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-04-01', 0, 'news standard', 'Dimitri\'s Death Ray Revealed by Old, Dusty File Cabinet', '<a name="01-04-2009" id="01-04-2009"></a>\n				<div class="news standard">\n					<div class="header">Dimitri\'s Death Ray Revealed by Old, Dusty File Cabinet\n						<div>\n							01-04-2009\n						</div>\n					</div>\n					<div class="content"><table cellpadding="0" cellspacing="0" style="margin: 0px auto 0px auto;">\n	<tr>\n		<td>\n			<img src="images/dimitrisDeathRay.jpg" />\n		</td>\n		<td style="width: 170px; vertical-align: top; padding-left: 10px;">\n			In 1919, according to legend, Russian scientist Doctor Dimitri is said to have conceived a machine able to produce the theoretically impossible frequency known as the Death Ray: A beam that will penetrate all matter - the ultimate weapon!<br/>\n			Existence of the Death Ray was never confirmed, Dimitri vanished and the weapon was thought of as no more than a myth.<br/>\n			Yesterday, during spring cleaning, in the darkest corner of our secret &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n		</td>\n		<td style="width: 170px; vertical-align: top; padding-left: 10px;">\n			underground complex, we found an old, dusty file cabinet. In a file labeled \'Strictly Confidential. Proper- ty of the Government of Russia,\' we found an old newspaper. It never reached the press as the bureau closed under mysterious circumstances.<br/>\n			The newspaper confirms Dimitri\'s Death Ray and gives clues to the impossible theory. With the paper in hand, our scientists hope to reproduce Dimitri\'s machine. Prepare for the Death Ray!\n		</td>\n	</tr>\n</table>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-04-03', 0, 'news standard', 'Death Ray Goes to Test Facility', '<a name="03-04-2009" id="03-04-2009"></a>\n				<div class="news standard">\n					<div class="header">Death Ray Goes to Test Facility\n						<div>\n							03-04-2009\n						</div>\n					</div>\n					<div class="content">This morning our scientists believed they had recreated Dimitri\'s machine able to produce the Death Ray. They rushed to investigate it in the lab\'s test facility. At 0600 hours safety-goggled scientists powered up the prototype, folded hands, said a small prayer and pressed the red button. The hall was illuminated with a radiant, burning white light. Crisp, electrified static - much like a tired pickup on an old vinyl record - echoed from the concrete walls. <br/>\n&nbsp;<br/>\nThe broad smiles quickly disappeared as the scientists un-goggled. All the lab rats had survived. A complete failure. Plenty of Ray but no Death! Crestfallen, the scientists left the test facility with one question on their minds: Is this ingenious, ultimate weapon theoretically impossible or just plain impossible? Will the project be shelved?\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-04-05', 0, 'news standard', 'Death Ray Breakthrough', '<a name="05-04-2009" id="05-04-2009"></a>\n				<div class="news standard">\n					<div class="header">Death Ray Breakthrough\n						<div>\n							05-04-2009\n						</div>\n					</div>\n					<div class="content">After 48 hours of intensive brain squeezing and numerous failed attempts to crack the mystery of the Death Ray, prototyping came to a standstill. So we ordered some takeaway sushi. Too exhausted to provide a proper chopstick-grip, a scientist dropped his wasabi into the prototype. An &uuml;ber-white flash exploded from the prototype as it discharged a wasabi-green beam through 27 reinforced concrete walls, seven blast doors, and five california rolls.<br/>\nLunch had gone from raw to charcoal and destructive smiles slowly widened on the blinded scientists\' faces. There was no doubt. This was the Death Ray.<br/>\n&nbsp;<br/>\nPut on your safety goggles and prepare! The Death Ray is coming to a tank near you - pray it\'s your own.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-04-07', 0, 'news attention', 'A Matter of Light and Death', '<a name="07-04-2009" id="07-04-2009"></a>\n				<div class="news attention">\n					<div class="header">A Matter of Light and Death\n						<div>\n							07-04-2009\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	Many lab rats and raw fish have been sacrificed in the process, but now the Death Ray has finally been released. Traveling at three times the speed of light, this weapon pulverizes anything in its path, so get ready to fry your opponent instantly in a scorching, white-hot Ray of Death!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-04-14', 0, 'news standard', 'TankTrouble Essentials Available Now', '<a name="14-04-2009" id="14-04-2009"></a>\n				<div class="news standard">\n					<div class="header">TankTrouble Essentials Available Now\n						<div>\n							14-04-2009\n						</div>\n					</div>\n					<div class="content"><div style="margin: 0 auto 0 auto; width: 620px;">\n	The Lab is proud to present a destructive collection of hot T-shirts straight from the cold Siberian underground. Whether you want a hoodie for the hood, a fierce pneumatic titanium dog on a tank, or a chaotic TankTrouble battleground for your mouse, TankTrouble Essentials\' got it. Check it out!\n</div>\n<div style="margin: 0 auto 0 auto; width: 620px;">\n	<img src="../images/shopCollection00.jpg" onclick="openShop()" style="cursor: pointer;"/>\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-04-24', 0, 'news standard', 'Shop Problems?', '<a name="24-04-2009" id="24-04-2009"></a>\n				<div class="news standard">\n					<div class="header">Shop Problems?\n						<div>\n							24-04-2009\n						</div>\n					</div>\n					<div class="content">Some users are experiencing problems opening our new TankTrouble T-shirt shop. We would like to get more feedback so we can resolve the issues ...that is, if there are any! Also tell us what you think of the T-shirts and the other stuff in the shop.<br/>\nWrite your feedback in the feedback box or send an email to <a href="mailto:laboratory@tanktrouble.com">laboratory@tanktrouble.com</a>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-07-22', 0, 'news important', 'Lab Rats Escape', '<a name="22-07-2009" id="22-07-2009"></a>\n				<div class="news important">\n					<div class="header">Lab Rats Escape\n						<div>\n							22-07-2009\n						</div>\n					</div>\n					<div class="content">Just as we were finally ready to deploy a new feature, our lab rat cage-control-computer had a short circuit and opened all cages. After two hours of rat chaos and 114 casualties (all lab rats) things were back under control<br/>\n...we thought. But, in the heat of the battle the rats had nibbled away on some important cables and some core systems crashed - lab rats are smart!<br/>\nThe damages are being assessed.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-07-25', 0, 'news important', 'New Experience System Separates the Sheep from the Wolves', '<a name="25-07-2009" id="25-07-2009"></a>\n				<div class="news important">\n					<div class="header">New Experience System Separates the Sheep from the Wolves\n						<div>\n							25-07-2009\n						</div>\n					</div>\n					<div class="content">Highscores are in high demand! So, our mathematical super brain, senior-&uuml;ber-scientist Dr. Yakowski, has come up with a secret formula that calculates just how skillful YOU TankTrouble tank drivers really are. Here\'s how it works:<br/>\n&nbsp;<br/>\n- Defeat tank owners with the same experience to gain 10 experience points.<br/>\n- Defeat tank owners with more experience and gain more.<br/>\n- Defeat tank owners with less experience and gain less.<br/>\n&nbsp;<br/>\nLet the separation of the sheep from the wolves begin!<br/>\n<span class="text red">For a fair start, all Scores, Deaths and Kills were reset.</span><br/>\n&nbsp;<br/>\n<span class="text tiny">\n	FAQ<br/>\n	Q: Is the formula really secret?<br/>\n	A: No, it just sounded more cool that way. If you insist, here it is:<br/>\n	winnerExperience += round(min(20, max(1, 10 + (loosersExperience - winnerExperience) / 100)))\n</span>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-07-25', 1, 'news important', 'Damages repaired After Great Lab Rat Escape', '<a name="25-07-2009" id="25-07-2009"></a>\n				<div class="news important">\n					<div class="header">Damages repaired After Great Lab Rat Escape\n						<div>\n							25-07-2009\n						</div>\n					</div>\n					<div class="content">We have replaced 247 meters of cable and we are back online.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2009-08-02', 0, 'news facebook', 'What Was the +facebook and Where Did It Go?', '<a name="02-08-2009" id="02-08-2009"></a>\n				<div class="news facebook">\n					<div class="header">What Was the +facebook and Where Did It Go?\n						<div>\n							02-08-2009\n						</div>\n					</div>\n					<div class="content">+facebook linked to the Lab\'s TankTrouble facebook app ...or at least it was supposed to. Unfortunately cooking up a facebook app wasn\'t as painless as the Lab assumed; It needs to go through a formal facebook approval process and is doing so currently ...then +facebook will be back!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-02-22', 0, 'news standard', 'Laika Goes to Laser Training Camp', '<a name="22-02-2010" id="22-02-2010"></a>\n				<div class="news standard">\n					<div class="header">Laika Goes to Laser Training Camp\n						<div>\n							22-02-2010\n						</div>\n					</div>\n					<div class="content">The lab gets lots of requests that Laika should be given weapons. Scientists have been reluctant to do this, as Laika is already far beyond control. Now we gave her the laser. YOU asked for it!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-04-06', 0, 'news standard', 'The Lab is Back!', '<a name="06-04-2010" id="06-04-2010"></a>\n				<div class="news standard">\n					<div class="header">The Lab is Back!\n						<div>\n							06-04-2010\n						</div>\n					</div>\n					<div class="content">In August 2009 the Russian government intensified their efforts to locate and obliterate the secret underground TankTrouble research facility. We decided to immediately halt the development and shut down the facility. We flipped the lever to the main power generator; we set the lab rats free; we dumped our entire stock of canned dog food (13.783 cans) in the elevator shaft to the prohibited Level G-4 where Laika roams, hoping this would keep her alive until we\'d return. As the deafening noise of the cans scrambling down the elevator shaft faded to silence, the scientists made their way to the surface. They then dispersed to different places around the globe to lay low through a life in exile. One scientist went to Europe and studied a Ph.D. while another went deep into the Rocky Mountains to work on a classified project. They were all just waiting for the day to return to the Siberian underground.<br/>\n&nbsp;<br/>\nNo sign of life has escaped the Siberian underground for the longest time in the history of TankTrouble. While we regret this, the Russian government is convinced that TankTrouble is no longer nothing but a myth.<br/>\nWe are back!<br/>\n&nbsp;<br/>\nP.S. We are pleased to hear occasional, distant screams of lab rats emerging from the elevator shaft to Level G-4. Our favorite titanium killing machine, Laika, is alive! We know she kept you busy in our absence.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-04-06', 1, 'news standard', 'The Lab is Back!', '<a name="06-04-2010" id="06-04-2010"></a>\n				<div class="news standard">\n					<div class="header">The Lab is Back!\n						<div>\n							06-04-2010\n						</div>\n					</div>\n					<div class="content">In August 2009 the Russian government intensified their efforts to locate and obliterate the secret underground TankTrouble research facility. We decided to immediately halt the development and shut down the facility. We flipped the lever to the main power generator; we set the lab rats free; we dumped our entire stock of canned dog food (13.783 cans) in the elevator shaft to the prohibited Level G-4 where Laika roams, hoping this would keep her alive until we\'d return. As the deafening noise of the cans scrambling down the elevator shaft faded to silence, the scientists made their way to the surface. They then dispersed to different places around the globe to lay low through a life in exile. One scientist went to Europe and studied a Ph.D. while another went deep into the Rocky Mountains to work on a classified project. They were all just waiting for the day to return to the Siberian underground.<br/>\n&nbsp;<br/>\nNo sign of life has escaped the Siberian underground for the longest time in the history of TankTrouble. While we regret this, the Russian government is convinced that TankTrouble is no longer nothing but a myth.<br/>\nWe are back!<br/>\n&nbsp;<br/>\nP.S. We are pleased to hear occasional, distant screams of lab rats emerging from the elevator shaft to Level G-4. Our favorite titanium killing machine, Laika, is alive! We know she kept you busy in our absence.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-04-21', 0, 'news standard', 'Tank Owners Have Spoken: Booby Traps Go Into Development', '<a name="21-04-2010" id="21-04-2010"></a>\n				<div class="news standard">\n					<div class="header">Tank Owners Have Spoken: Booby Traps Go Into Development\n						<div>\n							21-04-2010\n						</div>\n					</div>\n					<div class="content">When the weapon vote closed yesterday it was clear: Booby Traps! TankTrouble needs Booby Traps.<br/>\nThrilled and excited to bring this splendid, stealthy surprise-device into the mazes, the scientists skipped breakfast altogether and began development this morning at 0600 hours.<br/>\nBooby Traps are coming!<br/>\n&nbsp;<br/>\n...and Laika approves of the choice of weapon: "<span class="text quote">Two paws <img src="../images/twoPawsUp.jpg"/> up!</span>"\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-04-26', 0, 'news standard', 'Booby Traps Go to Testing - First Stage', '<a name="26-04-2010" id="26-04-2010"></a>\n				<div class="news standard">\n					<div class="header">Booby Traps Go to Testing - First Stage\n						<div>\n							26-04-2010\n						</div>\n					</div>\n					<div class="content">Yesterday, the scientists had a breakthrough in the development of the Booby Traps and the first prototypes reached a level of completion suitable for testing. Unfortunately, the test facility was blown up and became inaccessible (not to mention extremely hazardous) when testing of the Death Ray got slightly out of hand. The Booby Traps had to be tested on the surface.<br/>\nAccording to our intel there is a short time span just before dusk where no Russian satellites are watching, as they are all orbiting other skies. So, as the sun was setting, scientists emerged from the depths of our underground research facility.<br/>\nThe remaining sunlight was blinding and felt warm on our pale faces, and it was a strange sensation to breathe fresh, unfiltered, non-recycled air. But there was no time to linger and enjoy this rare opportunity. We rushed out on the barren Siberian wastelands and deployed the first prototype Booby Traps. When deployed, they automatically buried themselves under the top soil and, as per design, then activated. Then, time was up. The first Russian satellite would soon return to the Siberian sky and come in range to spot us. We hurried back to the underground.<br/>\nTomorrow at dusk we shall surface again to perform the final, most interesting part of the test: Blowing stuff up!<br/>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-04-27', 0, 'news standard', 'Booby Traps Go to Testing - Final Stage', '<a name="27-04-2010" id="27-04-2010"></a>\n				<div class="news standard">\n					<div class="header">Booby Traps Go to Testing - Final Stage\n						<div>\n							27-04-2010\n						</div>\n					</div>\n					<div class="content">Yesterday at dusk, we - the scientists - were once again back at the surface to complete the testing of the Booby Traps. The prototypes had been deployed the preceding day and all we had to do now, was to blow them up, but we soon learned an important lesson: When testing Booby Traps, remember where you lay them out ...which no one seemed to do. However, this was no major setback. Just a small bump in the road that called for the bomb squad (specially trained lab rats that sniff out explosives).<br/>\nThe rats spread out in random directions and the scientists waited in intense silence. For a moment, like a prelude to a grand symphony, a cold Siberian breeze swept the wastelands. Then a sharp click and a tiny squeak. Time paused for an instant, and like profound poetry a series of deafening explosions unfolded. Dirt and lab rats mixed in a mayhem of colours like kindergarten finger painting on steroids. Using the sky as a canvas, divine artwork was created that would make the most convinced atheist believe in the presence of a higher being. Then silence.<br/>\nWith satisfied, savage smiles and lab-rat-guts on their safety goggles, the scientists returned to the underground research facility.<br/>\nBooby Traps are coming to a maze near you!<br/>\n&nbsp;<br/>\n...and Laika approves of the level of destruction: "<span class="text quote">Two paws <img src="../images/twoPawsUp.jpg"/> up!</span>"\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-05-04', 0, 'news standard', 'Electrical Instability Results in Slower Death Ray Re-charge', '<a name="04-05-2010" id="04-05-2010"></a>\n				<div class="news standard">\n					<div class="header">Electrical Instability Results in Slower Death Ray Re-charge\n						<div>\n							04-05-2010\n						</div>\n					</div>\n					<div class="content">For some time the research facility have experienced severe instability in the electrical system. This has made development extremely difficult. Yesterday it peaked and caused several power generators to fail. We tracked the problem and found that the rapid charging of the Death Ray\'s high capacity cells instantly drained all juice from the research facility and, for a moment, left it as dry as a desert while the generators tried to catch up. To solve the problem the scientists have slowed down the recharging of the Death Ray.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-05-06', 0, 'news attention', 'Booby Traps Add Delightful Surprises to Maze Cruising', '<a name="06-05-2010" id="06-05-2010"></a>\n				<div class="news attention">\n					<div class="header">Booby Traps Add Delightful Surprises to Maze Cruising\n						<div>\n							06-05-2010\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	Watch where you drive - your enemies might have booby trapped the maze! There are 3 Booby Traps in a crate and you better remember where you deploy them or you might just booby trap yourself! ...and a tip from the scientists: If you step on one DON\'T MOVE!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-05-11', 0, 'news standard', 'TANK POLL', '<a name="11-05-2010" id="11-05-2010"></a>\n				<div class="news standard">\n					<div class="header">TANK POLL\n						<div>\n							11-05-2010\n						</div>\n					</div>\n					<div class="content"><div id="poll-5-content" class="middle text small">With the new Booby Traps spreading death and destruction in the mazes, and the Death Ray downgraded, the scientists are wondering:<br/>&nbsp;<br/><div id="poll-5-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-5-closedSign" src="images/thisPollIsClosed.png"/></div>What\'s the most destructive weapon?<br/><br/></div></div><table id="poll-5-results" style="height: 1px; margin: auto;"><tr><td><img src="images/sixCrates.jpg"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Laser <span class="text tiny">(1285 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 187.78705636743px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Frag Bomb <span class="text tiny">(456 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 66.638830897704px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Gatling Gun <span class="text tiny">(440 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 64.300626304802px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Homing Missile <span class="text tiny">(855 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 124.94780793319px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Death Ray <span class="text tiny">(2395 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Booby Traps <span class="text tiny">(1155 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 168.7891440501px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-09-04', 0, 'news standard', 'Login System No Longer in BETA', '<a name="04-09-2010" id="04-09-2010"></a>\n				<div class="news standard">\n					<div class="header">Login System No Longer in BETA\n						<div>\n							04-09-2010\n						</div>\n					</div>\n					<div class="content">The Lab did some final adjustments to the tank login system and it is no longer in beta.<br/>\nAll tanks that were not logged in during the last six months were terminated.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-09-04', 1, 'news attention', 'New Weapon for Couch Potatoes Hits the Maze', '<a name="04-09-2010" id="04-09-2010"></a>\n				<div class="news attention">\n					<div class="header">New Weapon for Couch Potatoes Hits the Maze\n						<div>\n							04-09-2010\n						</div>\n					</div>\n					<div class="content"><div style="width: 580px;">\n	Long time, no see! Scientists have been to Japan to research new, state of the art wireless, hi-tech fling-flong and have designed a special weapon for you lazy ass couch potatoes. Get yourself an RC Missile and chase down your enemies without moving a nozzle.\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-09-05', 0, 'news standard', 'New Features: Weekly Victories Highscore and Password Recovery', '<a name="05-09-2010" id="05-09-2010"></a>\n				<div class="news standard">\n					<div class="header">New Features: Weekly Victories Highscore and Password Recovery\n						<div>\n							05-09-2010\n						</div>\n					</div>\n					<div class="content">While all the scientists were busy creating dangerous, new, destructive weapons with cool Japanese, fling-flong hi-tech we had the intern do some boring jobs that we have put off ourselves for way too long:<br/>\n- Weekly Victories Highscore ...which by mistake replaced the all times top 10. Blame the intern!<br/>\n- Password and username recovery (accessed from the ? on the login box).<br/>\nEnjoy!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-09-12', 0, 'news facebook', 'Official facebook Page - Become a Fan!', '<a name="12-09-2010" id="12-09-2010"></a>\n				<div class="news facebook">\n					<div class="header">Official facebook Page - Become a Fan!\n						<div>\n							12-09-2010\n						</div>\n					</div>\n					<div class="content">Join the official TankTrouble facebook page and be the first to receive news! Discuss weapon tactics, share tips and tricks and more...<br/>\nVisit <a href=\'http://www.facebook.com/pages/TankTrouble/114035121952608\' target=\'_blank\'>http://www.facebook.com/pages/TankTrouble/114035121952608</a><br/>\n&nbsp;<br/>\nThe TankTrouble facebook page is managed by TankTrouble moderators.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2010-09-12', 1, 'news lab', 'What\'s Your Tank Rank?', '<a name="12-09-2010" id="12-09-2010"></a>\n				<div class="news lab">\n					<div class="header">What\'s Your Tank Rank?\n						<div>\n							12-09-2010\n						</div>\n					</div>\n					<div class="content"><div style="padding-left: 49px; background-image: url(\'images/testTubeSmall.jpg\'); background-repeat: no-repeat;">\n	Are you curious to know how you rank amongst other tank owners? Then check out this useful, little prototype made by our intern. Visit <a href="?lab">The Lab</a>.<br/>\n	&nbsp;<br/>\n	The Lab\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-03-30', 0, 'news standard', 'New features in the Garage', '<a name="30-03-2011" id="30-03-2011"></a>\n				<div class="news standard">\n					<div class="header">New features in the Garage\n						<div>\n							30-03-2011\n						</div>\n					</div>\n					<div class="content"><div style="padding-left: 54px; background-image: url(\'images/formV.jpg\'); background-repeat: no-repeat;">\n	We have received numerous requests from players that want to change their password or change their email. This is all possible now! Go to the <a href="?garage">Garage</a>, log in and click the document icon.<br/>\n	...and while you are there, sign up for the TankTrouble newsletter and be the first to know when new, explosive features hit the maze!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-04-06', 0, 'news standard', 'Traction Action', '<a name="06-04-2011" id="06-04-2011"></a>\n				<div class="news standard">\n					<div class="header">Traction Action\n						<div>\n							06-04-2011\n						</div>\n					</div>\n					<div class="content">Did your enemy ever get away or did you ever get nailed by a chasing bullet because you got stuck on a wall?<br/>\nIf so, this is for you:<br/>\nThe scientists have developed a new tank base with out-of-this-world, superlative traction belts. With these new babies equipped even the worst tank operator will never get stuck on walls again - the tank will simply pull itself free. These contraptions are standard equipment on all tanks. Hardcore tank operators can turn them off in the settings menu.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-05-10', 0, 'news standard', '300.000.000 Tanks Demolished', '<a name="10-05-2011" id="10-05-2011"></a>\n				<div class="news standard">\n					<div class="header">300.000.000 Tanks Demolished\n						<div>\n							10-05-2011\n						</div>\n					</div>\n					<div class="content">&nbsp;<br/>\n<div style="width: 100%; text-align: center;">\n	<img src="images/300000000.jpg"/>\n</div>\n&nbsp;<br/>\nSighs of awe echoed through our underground laboratories as the scrapyard flipped the last digit and counted 300.000.000 tanks demolished. The scientists could not help themselves and celebrated with a &#1058;&#1088;&#1077;&#1087;&#1072;&#1082;. Also they threw a bone down the shaft to the lower level where Laika roams. Contented growls were returned. It took blood, sweat and tears (and plenty of explosives) to reach this goal and we would never have made it without all of you destructive tank owners.<br/>\nThe lab is honored.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-05-11', 0, 'news standard', 'Fashion Forward Spring Colours Now Available', '<a name="11-05-2011" id="11-05-2011"></a>\n				<div class="news standard">\n					<div class="header">Fashion Forward Spring Colours Now Available\n						<div>\n							11-05-2011\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 112px; height: 76px; top: 7px; right: 10px;">\n	<img id="newsSpringFashion" src="images/sprayCansSpringFashion.png"/>\n</div>\n<div style="width: 530px;">\n	Even though the warming rays of sun, the blissful twitter from newly hatched birds, and the fresh, revitalizing scent of blooming flowers never reaches the dreary depths of our secret, underground research facility, we can see in our calendar that it is spring. We celebrate this with all new, fashionable spring colours, so head on to the <a href="?garage">Garage</a> and get a paint job.<br/>\n	Fashion forward spring colours will be available for a limited time only!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-07-09', 0, 'news standard', 'Flat Tires, Step Dancing and More...', '<a name="09-07-2011" id="09-07-2011"></a>\n				<div class="news standard">\n					<div class="header">Flat Tires, Step Dancing and More...\n						<div>\n							09-07-2011\n						</div>\n					</div>\n					<div class="content">In the underground of Siberia we noticed that the website was becoming increasingly slower.	The scientists long tried to locate the root cause of this problem but with no luck. Then one day the intern had a flat tire on his scooter (we use scooters to get around - it\'s faster in the long corridors) and headed for the server room - that\'s where we keep the spares. Long story short, he found the servers red-hot and over-exhausted from an inconceivable and relentless stream of destruction-information from all over the world. Tanks are popping 24-7, and faster than Fred Astaire step dancing on bubble wrap, and we record, log and catalog every single one!<br/>\nBut, with great destruction comes great responsibility! And the scientists are not late to get their hands dirty. Now the top secret, encrypted communication between you and the Siberian underground has been optimized and is 900% faster!<br/>\nThat\'s fast!<br/>\nAnd don\'t worry. We still record all the destruction.<br/>\n&nbsp;<br/>\nIn the highly unlikely event that you browse to another website remember to log out first. That way you make sure your victories are stored.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-07-10', 0, 'news standard', 'Hot Summer Fad - The Heat is On', '<a name="10-07-2011" id="10-07-2011"></a>\n				<div class="news standard">\n					<div class="header">Hot Summer Fad - The Heat is On\n						<div>\n							10-07-2011\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 112px; height: 76px; top: 7px; right: 10px;">\n	<img id="newsHotSummerFad" src="images/sprayCansHotSummerFad.png"/>\n</div>\n<div style="width: 530px;">\n	The lab recently conducted some top secret tests in the most desolate, inhospitable, godforsaken part of the vast Arizona desert. We, the Lab, cannot reveal what exactly was tested. In fact, we are not at liberty to reveal anything at all as this would compromise world peace. Our lips are sealed! However, though we are not yet ready to unleash the wrath of the <span style=\'text-decoration: line-through\'>weapon</span> thing we tested, we were inspired to create a new, burning hot, dusty palette for your tank. Go to the <a href="?garage">Garage</a> and get your tank into a sweat!<br/>\n	The hot summer fad is available for a limited time only!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-07-21', 0, 'news facebook', 'TankTrouble facebook Page Reaches 2000 Likes', '<a name="21-07-2011" id="21-07-2011"></a>\n				<div class="news facebook">\n					<div class="header">TankTrouble facebook Page Reaches 2000 Likes\n						<div>\n							21-07-2011\n						</div>\n					</div>\n					<div class="content"><div style="padding-left: 180px; background-image: url(\'images/facebookTankTroubleLogo.jpg\'); background-repeat: no-repeat;">\n	Thanks to all the 2000 fans - we could not have done it without you. Quite literally.<br/>\n	&nbsp;<br/>\n	Thanks to our moderators who update the facebook page and keep it nice and tidy.<br/>\n	&nbsp;<br/>\n	...and if YOU have not joined yet, do it NOW!<br/>\n	<a href=\'http://www.facebook.com/pages/TankTrouble/114035121952608\' target=\'_blank\'>http://www.facebook.com/pages/TankTrouble/114035121952608</a><br/>\n	&nbsp;<br/>\n	And as we like to say here in the lab: One can always destroy more! So when we reach the bar we just raise it higher. Let\'s shoot for 5000 likes! And we need your help. Tell your friends, foes and family about TankTrouble and make them join! (by force if necessary)<br/>\n	&nbsp;<br/>\n	THANK YOU!<br/>\n	&nbsp;<br/>\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-11-30', 0, 'news standard', 'Minor Hiccups', '<a name="30-11-2011" id="30-11-2011"></a>\n				<div class="news standard">\n					<div class="header">Minor Hiccups\n						<div>\n							30-11-2011\n						</div>\n					</div>\n					<div class="content">During the last few days the TankTrouble servers have experienced a few speed bumps and frustrated tank owners with little patience were defeated by long load times. This was caused by a database problem which is way too boring and impossible to explain within any reasonable length of text so instead we will blame it on a radioactive leak from one of the old, rusty barrels in the server room. The situation is now contained and the servers are back to normal.<br/>\n&nbsp;<br/>\nAlso some might have noticed that our intern was messing with the style sheets for the News section #@!&sect;*. He claims it\'s fixed and that the News are back in style. So to speak.<br/>\n&nbsp;<br/>\nThe more important question - the one on all tank owners\' minds - is of course: What\'s in the pipeline?<br/>\nWell, there\'s a reason we are a top secret laboratory inconveniently located deep in the Siberian underground. At this time we are not at liberty to reveal anything.<br/>\nMore information will follow soon. Stay tuned!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-12-01', 0, 'news christmas', 'Santa Endorses Giving Your Sleigh a Seasonal Paint Job', '<a name="01-12-2011" id="01-12-2011"></a>\n				<div class="news christmas">\n					<div class="header">Santa Endorses Giving Your <span class=\'text quote\'>Sleigh</span> a Seasonal Paint Job\n						<div>\n							01-12-2011\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 112px; height: 76px; top: -20px; right: 10px;">\n	<img id="newsSprayCansChristmas" src="images/sprayCansChristmas.png"/>\n</div>\n<div style="width: 530px;">\n	Santa himself has handpicked 10 Christmas colors and assured that they will get you and your tank safely through the wait. Here in the cold Siberian underground we really have no idea what he is talking about.<br/>\n	Anyways, go to the <a href="?garage">Garage</a> and embrace the spirit!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-12-10', 0, 'news standard', 'Rumors of Pocket-Sized Mass Destruction are Nothing but Tittle-Tattle', '<a name="10-12-2011" id="10-12-2011"></a>\n				<div class="news standard">\n					<div class="header">Rumors of Pocket-Sized Mass Destruction are Nothing but Tittle-Tattle\n						<div>\n							10-12-2011\n						</div>\n					</div>\n					<div class="content">It has come to our attention that the following rumor is spreading faster than shrapnel from a frag bomb:<br/>\n&nbsp;<br/>\n<b>"The TankTrouble Lab is in the final stages of testing a pocket-sized, mobile weapon of mass destruction that begins with an i"</b><br/>\n&nbsp;<br/>\nThe Lab can not confirm to dismiss that we affirm not to verify the possible validity of such a rumor.<br/>\nIn other words:<br/>\nThe Lab refuses to deny that there is no substance to the truth of this rumor.<br/>\nThis is nothing but tittle-tattle.<br/>\n&nbsp;<br/>\nThe Lab would also like to use this opportunity to deny all speculations that our press agent has not worked as a spin doctor for the Russian government.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-12-13', 0, 'news mobile', 'Celebrating the 4th Anniversary of TankTrouble', '<a name="13-12-2011" id="13-12-2011"></a>\n				<div class="news mobile">\n					<div class="header">Celebrating the 4th Anniversary of TankTrouble\n						<div>\n							13-12-2011\n						</div>\n					</div>\n					<div class="content">Next Friday, Friday the 16th of December, is an extraordinarily special day for TankTrouble and all aficionados of destruction. On that day, four years ago, the Scrapyard\'s digits flipped to count 1 as the very first TankTrouble tank was demolished. Next Friday, tanks have been in trouble for four years. It is the 4th anniversary of TankTrouble.<br/>\n&nbsp;<br/>\nTo celebrate the anniversary in the appropriate, destructive fashion, the TankTrouble laboratory has been building something very special for you: A pocket-sized weapon of mass destruction. After countless hours of grueling development and numerous lab rats sacrificed, it is ready to be unleashed. We are delighted to announce the release of the TankTrouble iPhone/iPod app:<br/>\n&nbsp;<br/>\n<div style="width: 100%; text-align: center;">\n	<span class=\'text medium\'>The TankTrouble app will be unleashed in the iTunes store on Friday - December the 16th.</span>\n</div>\n&nbsp;<br/>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2011-12-16', 0, 'news mobile', 'Celebrating Four Years of Destruction', '<a name="16-12-2011" id="16-12-2011"></a>\n				<div class="news mobile">\n					<div class="header">Celebrating Four Years of Destruction\n						<div>\n							16-12-2011\n						</div>\n					</div>\n					<div class="content"><div class=\'text medium\' style="height: 370px; padding: 22px 245px 0px 30px; background-image: url(\'images/iPhone1.0.0.jpg\'); background-repeat: no-repeat; background-position: top right;">\n	On December 16th, 2007 the first TankTrouble tank ventured into the mazes and was soon turned into shrapnel.\n	Today, oodles of demolished tanks and four years later, it is the 4th anniversary of TankTrouble.<br/>\n	&nbsp;<br/>\n	Here in our top secret research facility deep in the Siberian underground, the scientists are delighted to celebrate this magnificent day by unleashing mobile destruction on the App Store.<br/>\n	&nbsp;<br/>\n	<a style=\'font-weight: 900;\' href=\'http://itunes.apple.com/us/app/tanktrouble/id486789462?ls=1&mt=8\' target=\'_blank\'>Get TankTrouble for your iPhone or iPod now!</a><br/>\n	&nbsp;<br/>\n	May the destruction be with you ...wherever you go.<br/>\n	Yours sincerely,<br/>\n	The Lab\n	<div style=\'position: relative; top: 22px; left: -3px;\'>\n		<a href=\'http://itunes.apple.com/us/app/tanktrouble/id486789462?ls=1&mt=8\' target=\'_blank\'>\n			<img src=\'images/availableOnAppStore.png\'/>\n		</a>\n	</div>\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-01-04', 0, 'news mobile', 'Status on Recently Unleashed Mobile Destruction', '<a name="04-01-2012" id="04-01-2012"></a>\n				<div class="news mobile">\n					<div class="header">Status on Recently Unleashed Mobile Destruction\n						<div>\n							04-01-2012\n						</div>\n					</div>\n					<div class="content">Not too long ago the TankTrouble App was unleashed on the App Store and here in the lab we are delighted to see the app being downloaded by TankTrouble fans around the world.<br/>\nWe are well aware that the app does not have all the destructive features from the website ...yet! The website had a head start and naturally it will take the Laboratory\'s mobile division some time to catch up.<br/>\nMeanwhile, if you have some great ideas for the upcoming update or if you have found a bug we need to hear from you!<br/>\nPlease report to <a href=\'http://www.tanktrouble.com/ios/\'>www.tanktrouble.com/ios</a><br/>\n&nbsp;<br/>\nAnd if you haven\'t got the app yet you know where to get it...<br/>\n<a href=\'http://itunes.apple.com/us/app/tanktrouble/id486789462?ls=1&mt=8\' target=\'_blank\'>\n<img src=\'images/availableOnAppStore.png\'/>\n</a>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-04-09', 0, 'news standard', 'The Lab is Not Hibernating', '<a name="09-04-2012" id="09-04-2012"></a>\n				<div class="news standard">\n					<div class="header">The Lab is Not Hibernating\n						<div>\n							09-04-2012\n						</div>\n					</div>\n					<div class="content">It has been a tough winter in the Siberian underground. After the release of mobile destruction - the TankTrouble iOS App - the Russian government intensified operation &#1089;&#1086;&#1073;&#1072;&#1095;&#1100;&#1080;&#32;&#1075;&#1072;&#1083;&#1077;&#1090;&#1099;: Find and obliterate the secret TankTrouble laboratory. Thus we have kept a low profile but are in no way in hibernation. We have been cooking on something special from our own, explosive cookbook and it will soon be "well&nbsp;done". Expect more news soon...\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-04-13', 0, 'news standard', 'Old, Russian Proverb Leads Scientists to Silence', '<a name="13-04-2012" id="13-04-2012"></a>\n				<div class="news standard">\n					<div class="header">Old, Russian Proverb Leads Scientists to Silence\n						<div>\n							13-04-2012\n						</div>\n					</div>\n					<div class="content">Since our announcement this Monday many tank owners want to know what is "cooking".\nA wise, old Russian proverb goes:<br/>\nDo not sell the skin before the bear has been shot.<br/>\nOr as we say in the TankTrouble lab:<br/>\nDon\'t milk the cow before you\'ve got corn flakes in the bowl.<br/>\n...because we love metaphors and living in an underground bunker does strange things to your brain.\nThus to avoid selling a skin we do not yet have or milk the cow in vain, our lips will remain sealed. Scientists are conducting final tests on the "corn flakes" and more will be revealed on Monday.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-04-15', 0, 'news mobile', 'TankTrouble iOS Goes Wireless on Friday', '<a name="15-04-2012" id="15-04-2012"></a>\n				<div class="news mobile">\n					<div class="header">TankTrouble iOS Goes Wireless on Friday\n						<div>\n							15-04-2012\n						</div>\n					</div>\n					<div class="content">Since the release of the TankTrouble iOS App, our mailbox has been red-hot due to incoming requests for more! We read all your feedback and we realise that mobile tank owners don\'t like sharing with their enemies. That\'s why the lab has been hard at work harnessing the power of wireless technologies. The result is that your sharing days are now over: Soon you can battle wirelessly against those around you.<br/>\nSo recharge those phones, pods and pads. TankTrouble iOS 1.1 is unleashed this Friday!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-04-20', 0, 'news mobile', 'Wireless Destruction Hits the App Store', '<a name="20-04-2012" id="20-04-2012"></a>\n				<div class="news mobile">\n					<div class="header">Wireless Destruction Hits the App Store\n						<div>\n							20-04-2012\n						</div>\n					</div>\n					<div class="content">After long, sleepless nights tackling unyielding zeros and ones... having shed blood, sweat and lab rats... reaping the powers of Bluetooth technology... we, the TankTrouble lab, humbly present to you the perfect constellation of bits and bytes: TankTrouble iOS wireless!<br/><br/>\nDownload TankTrouble iOS 1.1 now and challenge your nearby friends in wireless combat.<br/>\n<a href=\'http://itunes.apple.com/us/app/tanktrouble/id486789462?ls=1&mt=8\' target=\'_blank\'>\n<img src=\'images/availableOnAppStore.png\'/>\n</a>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-08-12', 0, 'news important', 'Cleaning Up the Hangars', '<a name="12-08-2012" id="12-08-2012"></a>\n				<div class="news important">\n					<div class="header">Cleaning Up the Hangars\n						<div>\n							12-08-2012\n						</div>\n					</div>\n					<div class="content">It seems that numerous old tanks are collecting nothing much but dust and their only contribution to world destruction is database congestion. And that\'s not very efficient. Therefore while cleaning is most definitely one of our least favorite activities, this is exactly what we are going to do:<br/>\n&nbsp;<br/>\nON SEPTEMBER 1ST 2012 ALL TANKS THAT HAVE BEEN INACTIVE FOR ONE YEAR WILL BE RETIRED!<br/>\n&nbsp;<br/>\nTo make sure you don\'t lose your tank, simply log in.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-08-13', 0, 'news standard', 'Forum Improvements', '<a name="13-08-2012" id="13-08-2012"></a>\n				<div class="news standard">\n					<div class="header">Forum Improvements\n						<div>\n							13-08-2012\n						</div>\n					</div>\n					<div class="content">Excuse us if we just had a long vacation... we did. Let\'s call it research.\nSo we were exploring uncharted and exotic destinations while following our trusted guide book with essential tips and tricks for those on the road and such, when most unfortunately the index page was lost during a stampede. This was indeed inconvenient (the index page being lost, not the stampede) when we needed to look up something important. We immediately thought (well not immediately, after the stampede had past) of the TankTrouble forum and how it would be significantly improved if one could find what one was looking for when one wanted to find it. Much like what an index page does; like a search function. So that\'s what we decided to do once we returned to the Siberian underground. Anyway, that turned out to require actual brain power so instead we added pages and some pretty graphics. Enjoy.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-09-01', 0, 'news standard', '186K R.I.P.', '<a name="01-09-2012" id="01-09-2012"></a>\n				<div class="news standard">\n					<div class="header">186K R.I.P.\n						<div>\n							01-09-2012\n						</div>\n					</div>\n					<div class="content">Though procrastination is our favorite activity, between that and cleaning we bit the bullet and performed, as warned, a thorough cleaning of the hangars today. 186K of old, dust-collecting tanks were retired from the database. May they rest in peace.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-09-05', 0, 'news standard', 'Scientists Miss Major Milestone', '<a name="05-09-2012" id="05-09-2012"></a>\n				<div class="news standard">\n					<div class="header">Scientists Miss Major Milestone\n						<div>\n							05-09-2012\n						</div>\n					</div>\n					<div class="content">&nbsp;<br/>\n<div style="width: 100%; text-align: center;">\n	<img src="images/500000001.jpg"/>\n</div>\n&nbsp;<br/>\nAs the scrapyard was getting closer to the half-a-billion mark, the TankTrouble lab was working increasingly harder to finish a most awesome upgrade - an upgrade worthy of celebrating an achievement of that destructive magnitude.<br/>&nbsp;<br/>\nAfter many long nights, the upgrade was complete. The lead scientist put his finger on the red deploy-button while the rest of the team were ready to pop the champagne. Everyone were tired, exhausted and droopy-eyed yet bursting with excitement to see the Scrapyard flip to the awe-inspiring, all-glorious 500000000; only to find out the moment was long gone...<br/>&nbsp;<br/>\nIt is hard to describe the magnitude of the disappointment that hit the research facility. Imagine if a dog peed on the bonfire, covering your marshmallows in a cloud of steam just as they were reaching their maximum marshmallow potential. That\'s how it felt. Or maybe even worse.<br/>&nbsp;<br/>\nUnable to cope with this level of disappointment, the lead scientist slipped into a coma-like state, which probably has a fancy name among psychologists. And to make things worse he is also the only one with knowledge of the deployment codes (for safety reasons that is - remember the trainee episode?), so while we wait for him to snap out of it, we are unable to deploy the upgrade. Sigh.<br/>&nbsp;<br/>\nWe have sent for a shrink. Expect news soon!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-09-09', 0, 'news standard', 'Spanner Opens... About Bloody Time!', '<a name="09-09-2012" id="09-09-2012"></a>\n				<div class="news standard">\n					<div class="header">Spanner Opens... About Bloody Time!\n						<div>\n							09-09-2012\n						</div>\n					</div>\n					<div class="content"><div style="padding-left: 130px; background-image: url(\'images/spannerRevealed.jpg\'); background-repeat: no-repeat;">\nJust now, our lead scientist slipped out of his coma caused by extreme disappointment and most fortunately it seems his memory is intact. He is now, as we are writing, entering the top secret deploy codes. He\'s typing agitatedly and with determination... the codes are very long and complicated... white froth is appearing in the corner of his mouth... the entire underground research facility is holding their breath in excitement... and the codes are in!<br/> The lead scientist presses the red button and now, by the power invested in us by the gods of destruction, the spanner is revealed!<br/>&nbsp;<br/>\n<a href="?garage">Go to the Garage now and pimp your tank!</a>\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-05', 0, 'news standard', 'Need Help?', '<a name="05-10-2012" id="05-10-2012"></a>\n				<div class="news standard">\n					<div class="header">Need Help?\n						<div>\n							05-10-2012\n						</div>\n					</div>\n					<div class="content">The TankTrouble scientists know everything! They have distilled their comprehensive knowledge into an essential list of frequently asked questions. So if you need help check out the new <a href=\'\' id="faqLink">FAQ</a>.\n<script type="text/javascript">\n	<!--\n	document.getElementById(\'faqLink\').onclick = function()\n	{\n		window.open(\'faq/index.html\', \'_blank\', \'width=600,height=600,left=\'+(screen.width-600)/2+\',top=\'+(screen.height-600)/2+\',resizable=0,toolbar=0,location=0,status=0,menubar=0, scrollbars=1,directories=0\');\n	}\n	//	-->\n</script>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-07', 0, 'news mobile', 'Mobile Online Battles Begin on Friday', '<a name="07-10-2012" id="07-10-2012"></a>\n				<div class="news mobile">\n					<div class="header">Mobile Online Battles Begin on Friday\n						<div>\n							07-10-2012\n						</div>\n					</div>\n					<div class="content">Online destruction is in hot demand and since the day TankTrouble was conceived this has always been the ultimate goal. The scientists have spent many sleepless nights, overheating their copious grey cells, and lab rats have fearlessly thrown themselves into dangerous experiments for this greater cause. Today we had the first breakthrough and successfully tested online TankTrouble iOS battles. And rest assured! We are not slowing down our relentless efforts to achieve the ultimate goal of epic battles of online destruction.<br/>\n&nbsp;<br/>\nRecharge your iThings and prepare: TankTrouble&nbsp;iOS&nbsp;2.0 will be unleashed on the AppStore on Friday!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-12', 0, 'news mobile', 'TankTrouble iOS 2.0 Slightly Delayed', '<a name="12-10-2012" id="12-10-2012"></a>\n				<div class="news mobile">\n					<div class="header">TankTrouble iOS 2.0 Slightly Delayed\n						<div>\n							12-10-2012\n						</div>\n					</div>\n					<div class="content">It is taking longer for Apple to approve TankTrouble iOS 2.0 than the scientists expected. We suspect they have gotten\nso immersed in testing online destruction that they cannot put it down and get on with approving it. Stand by, it could be any minute now!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-13', 0, 'news standard', 'While Waiting for Online Destruction', '<a name="13-10-2012" id="13-10-2012"></a>\n				<div class="news standard">\n					<div class="header">While Waiting for Online Destruction\n						<div>\n							13-10-2012\n						</div>\n					</div>\n					<div class="content">It seems that Apple is taking their time to approve online destruction for the App Store. While we are still holding our breath here in the underground lab, we have created a new range of fashionable and highly desirable tank accessories. Go to <a href="?garage">the Garage</a> now and soothe your disappointment and impatience with some fresh swag for your tank!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-18', 0, 'news mobile', 'Mobile Destruction is Online', '<a name="18-10-2012" id="18-10-2012"></a>\n				<div class="news mobile">\n					<div class="header">Mobile Destruction is Online\n						<div>\n							18-10-2012\n						</div>\n					</div>\n					<div class="content">Mobile tank owners don\'t always have a friend or foe nearby. Consequently, the TankTrouble lab has been working hard to harness the powers of the Internet. TankTroublers be warned: TankTrouble iOS is now fully online!<br/>\nDownload TankTrouble iOS 2.0 now!<br/>\n<a href=\'http://itunes.apple.com/us/app/tanktrouble/id486789462?ls=1&mt=8\' target=\'_blank\'>\n<img src=\'images/availableOnAppStore.png\'/>\n</a>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-25', 0, 'news halloween', 'The Garage is Haunted!', '<a name="25-10-2012" id="25-10-2012"></a>\n				<div class="news halloween">\n					<div class="header">The Garage is Haunted!\n						<div>\n							25-10-2012\n						</div>\n					</div>\n					<div class="content"><div style="margin-left: 10px; padding-left: 180px; background-image: url(\'images/jack-o-LanternOpen.png\'); background-repeat: no-repeat;">\n	Obliviously unaware of the dangers he was about to unleash, one of our scientists has, as pastime, been doing some bedtime reading in the Necronomicon. He has also been reciting certain passages from the book and practiced necromancy for beginners during lunch breaks. This has awakened an unearthly, ancient evil and summoned a range of spine-chillingly horrifying, undead tank fitments to the Garage. If we were in the business of baby panda rehabilitation we would consider this a slight problem... but we are not! So in the name of Halloween, we welcome our paranormal brothers of destruction.<br/>\n	&nbsp;<br/>\n	Go to <a href="?garage">the Garage</a> and get ready for some serious candy soliciting!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-10-26', 0, 'news halloween', 'The Undead Will be Undone November 1st', '<a name="26-10-2012" id="26-10-2012"></a>\n				<div class="news halloween">\n					<div class="header">The Undead Will be Undone November 1st\n						<div>\n							26-10-2012\n						</div>\n					</div>\n					<div class="content">Though this paranormal activity falls completely outside our usual scientific approach to destruction, we will practice more black magic on November 1st and banish the undead. Anyone who has logged in before then get to keep their Halloween accessory collection for good!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-11-20', 0, 'news christmas', 'Christmas Advent Calendar with Unusual Half-life', '<a name="20-11-2012" id="20-11-2012"></a>\n				<div class="news christmas">\n					<div class="header">Christmas Advent Calendar with Unusual Half-life\n						<div>\n							20-11-2012\n						</div>\n					</div>\n					<div class="content"><div style="margin-left: 10px; padding-left: 180px; background-image: url(\'images/christmasPresentOpen.jpg\'); background-repeat: no-repeat;">\n	During a reconnaissance of unexplored corners of our secret, underground research facility we came across an old box of dusty Christmas decorations. The decorations have suffered the teeth of staring lab rats and the box appears to be somewhat radioactive. Anyhow, given it\'s the only Christmas decorations we have, we still think they make a perfect Christmas advent calendar:<br/>\n	Every day starting from December 1st. to Christmas morning we will put a new Christmas accessory in the Garage.<br/>\n	Each accessory will be available for one day only.<br/>\n	So log in every day to claim and unlock a special Christmas accessory for your tank!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-12-01', 0, 'news christmas', '25 Christmas Infused Tankcessories About to be Unleashed in the Garage', '<a name="01-12-2012" id="01-12-2012"></a>\n				<div class="news christmas">\n					<div class="header">25 Christmas Infused Tankcessories About to be Unleashed in the Garage\n						<div>\n							01-12-2012\n						</div>\n					</div>\n					<div class="content">Although the secret TankTrouble research facility is buried deep underground in the vast Siberian wastelands, and the Russian government has so far been unsuccessful in its relentless attempts to locate it (knock on concrete ...there is no wood in our bunker), the Christmas Spirit did find us! Jolly silliness has heated up our moist, underground corridors and the scientists are tremendously excited about the prospects of gingerbread and eggnog, not to mention the old box of grubby, radioactive Christmas decorations we found recently. Each day, until Christmas morning, we will release one new, special (and relatively safe), Christmas decoration tankcessory. And since today is December 1st, go to <a href="?garage">the Garage</a> now and unlock your first!<br/>\n&nbsp;<br/>\nHo ho ho, from the Siberian underground<br/>\n&nbsp;<br/>\n<span class=\'text red\'>Note: To unlock a tankcessory you must log in on the day it is available. Then it is yours to keep.</span>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-12-01', 1, 'news christmas', 'Santa Endorses Giving Your Sleigh a Seasonal Paint Job', '<a name="01-12-2012" id="01-12-2012"></a>\n				<div class="news christmas">\n					<div class="header">Santa Endorses Giving Your <span class=\'text quote\'>Sleigh</span> a Seasonal Paint Job\n						<div>\n							01-12-2012\n						</div>\n					</div>\n					<div class="content"><div style="position: absolute; width: 112px; height: 76px; top: -20px; right: 10px;">\n	<img id="newsSprayCansChristmas" src="images/sprayCansChristmas.png"/>\n</div>\n<div style="width: 530px;">\n	Santa himself has handpicked 10 Christmas colors and assured that they will get you and your tank safely through the wait. Here in the cold Siberian underground we really have no idea what he is talking about.<br/>\n	Anyways, go to the <a href="?garage">Garage</a> and embrace the spirit!\n</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-12-07', 0, 'news standard', 'Tankcessory Misbehavior', '<a name="07-12-2012" id="07-12-2012"></a>\n				<div class="news standard">\n					<div class="header">Tankcessory Misbehavior\n						<div>\n							07-12-2012\n						</div>\n					</div>\n					<div class="content">...or was it all by design?<br/>\nHere are some answers from the Siberian underground to help untangle the tankcessory box mystery:<br/>\n&nbsp;<br/>\n<span style=\'font-weight: bold;\'>The Christmas Advent Box</span><br/>\nEvery day from December 1st and until Christmas morning the 25th, special Christmas advent tankcessories will be released. You will keep all the tankcessories you unlock, but you must log in every day to unlock them.<br/>\n&nbsp;<br/>\n<span style=\'font-weight: bold;\'>The Halloween Box</span><br/>\nOnly tank owners who had a Halloween tankcessory equipped on All Saints\' Eve own this grim, grisly and ghastly box of gruesomeness. Now the quick-witted tank owner who did dress up might ask why the box disappeared during November. Well, that was *ahem* just a minor hiccup. And those green-eyed tank owners who forgot to dress up, fear not! Supernatural horrors will be summoned again next Halloween. <br/>\n&nbsp;<br/>\n<span style=\'font-weight: bold;\'>The Golden Box</span><br/>\nThis mysterious and highly desirable box of awesomeness contains special tankcessories that can only be unlocked by special achievements. Unfortunately, at this time, we are not at liberty to reveal what these achievements are. Why? Because they are top secret!<br/>\n&nbsp;<br/>\nWe hope that clarified things and give our sincere, subsurface tankpologies for possibly having confused the matter more with non-existing words from our tankcabulary.<br/>\nThe Lab\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-12-16', 0, 'news standard', 'TankTrouble Turns 5', '<a name="16-12-2012" id="16-12-2012"></a>\n				<div class="news standard">\n					<div class="header">TankTrouble Turns 5\n						<div>\n							16-12-2012\n						</div>\n					</div>\n					<div class="content">In the Siberian underground we are working our socks off testing the next, big, destructive thing. And even though all lamps in the test facility are flashing red and lab rats are drinking coolant from our nuclear reactor which is leaking, we have allowed ourselves a calm cake break to celebrate this special day. So whilst munching on some dry cupcakes we recovered from an old, confidential file archive from the cold war, we honor the past year with memorable quotes from you, the tank owners:<br/>\n&nbsp;<br/>\n"<span class="text quote">this game ROCKS!</span>"<br/>\nWe are humbly honored. This kind of feedback is the mental fuel that TankTrouble runs on.<br/>\n&nbsp;<br/>\n"<span class="text quote">what an absolutly auful game, how dare you suggest that i would want to spend my break playing this junk!</span>"<br/>\nWe are terribly sorry that we do not meet your coffee break entertainment standards. We will get our top-notch scientists on it right away!<br/>\n&nbsp;<br/>\n"<span class="text quote">I love this game! It\'s so addicting, I just wish i could play online v.s. other players</span>"<br/>\nOnline is a tricky dog biscuit. Our runner-up top-notch scientists are cranking on it!<br/>\n&nbsp;<br/>\n"<span class="text quote">This most popular site since the one about sliced bread!</span>"<br/>\nWe agree. The one about sliced bread was epic.<br/>\n&nbsp;<br/>\n"<span class="text quote">Iam going crazy man crazzzyyyy!!!!!!!!!!!!!!!!!!</span>"<br/>\nWe suggest you eat some sliced bread. That helps.<br/>\n&nbsp;<br/>\n"<span class="text quote">The awesome people who made the awesome game tank trouble should give single players a choice as to the difficulty of my hero Laika</span>"<br/>\nLaika is a very independent individual and does not come with a difficulty setting (read the news from 29-03-2009) but we are trying to reanimate other foes.<br/>\n&nbsp;<br/>\n"<span class="text quote">hi i say awsome i luv u guys dont eva finish dis website &lt;3 luv u zebragirl</span>"<br/>\nHaving been buried for too long, too deep in the Siberian underground we are not completely down with this modern, hip language of abbreviations but after a little research on the Internet we <span class="text quote">luv</span> this feedback!<br/>\n&nbsp;<br/>\nHappy birthday TankTrouble!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2012-12-25', 0, 'news christmas', 'Merry Christmas', '<a name="25-12-2012" id="25-12-2012"></a>\n				<div class="news christmas">\n					<div class="header">Merry Christmas\n						<div>\n							25-12-2012\n						</div>\n					</div>\n					<div class="content">Our laboratory is now decorated with the 25 Christmas tankcessories that we recovered from an old archive box. The scientists are munching ginger bread and crooning Christmas carols and jolly spirit has spread throughout the dark and unexplored corridors of the research facility.<br/>\n&nbsp;<br/>\n<img src=\'images/AdventCalendarOverview.jpg\'/><br/>\nWarm wishes from the cold, Siberian underground,<br/>\nThe Lab<br/>\n&nbsp;<br/>\n@Santa: Be advised that we do not have a chimney. We suggest you enter through rocket silo B5. This will also ease the delivery of the nuclear reactor that was on the top of our wish list. Thank you.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2013-02-10', 0, 'news standard', 'Achievements Unlocked!', '<a name="10-02-2013" id="10-02-2013"></a>\n				<div class="news standard">\n					<div class="header">Achievements Unlocked!\n						<div>\n							10-02-2013\n						</div>\n					</div>\n					<div class="content">A few weeks back, a mysterious golden box started popping up in the Garage of innocent, unknowing tanks. The confusion quickly turned to excitement as they discovered the extra tankcessories contained within. However, to many it was still unclear how or why these select few tanks had been graced with more swag than they could handle.<br/>\nWe have been working behind the scenes, and are now ready to proudly announce that achievements have finally come to everyone\'s favorite Russian tank simulator! Go to <a href="?garage">the Garage</a> to see which ones you already have and to scope out your next goal!<br/>\n&nbsp;<br/>\nAnd brace yourselves &ndash; there are more to come!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2013-02-18', 0, 'news standard', 'Bumpy Road to Online Battles', '<a name="18-02-2013" id="18-02-2013"></a>\n				<div class="news standard">\n					<div class="header">Bumpy Road to Online Battles\n						<div>\n							18-02-2013\n						</div>\n					</div>\n					<div class="content">	The biggest nut to crack; the one we\'ve been cracking at for years; the single most desired thing (since the website about sliced bread) and the heart that will fuel the future of destruction: TankTrouble online just aced a trial run in the test facility!<br/>\n	&nbsp;<br/>\n	Conducting tests in the Siberian underground rarely goes without titanic catastrophes or minor mishaps. This time we were blessed with the latter: Shaking with euphoric excitement the lead scientists was unable to hold his coffee mug steady and spilled some into the control panel causing some slightly unorthodox behaviour on the website. The website has been restored to normal and we will revise our policy on the intake of liquids during crucial tests.<br/>\n	&nbsp;<br/>\n	A test worthy alpha version of TankTrouble is getting exhilaratingly close. Stay posted!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2013-03-02', 0, 'news standard', 'New Swag in TankTrouble Essentials', '<a name="02-03-2013" id="02-03-2013"></a>\n				<div class="news standard">\n					<div class="header">New Swag in TankTrouble Essentials\n						<div>\n							02-03-2013\n						</div>\n					</div>\n					<div class="content">	Hiding in the Siberian underground during the unforgiving, freezing cold winter can be a chilly experience even for the most hard-boiled of scientists. Therefore we have created new, boiling hot winter wearables as well as other cool and fashionable TankTrouble essentials. Now you can also choose your preferred colour. Check out the shop!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-05-04', 0, 'news mobile', 'TankTrouble iOS Sold Out!', '<a name="04-05-2014" id="04-05-2014"></a>\n				<div class="news mobile">\n					<div class="header">TankTrouble iOS Sold Out!\n						<div>\n							04-05-2014\n						</div>\n					</div>\n					<div class="content">	How can an app be sold out, you ask? Well, it isn\'t actually sold out. We just decided to remove it from the App Store. We are scheming to build an app that will set a new benchmark for mobile destruction. Meanwhile, we thought it best to take down the old app. Those of you who downloaded it can proudly claim to hold a rare collector\'s piece of TankTrouble history.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-05-19', 0, 'news standard', 'The Underground Laboratory Breaks the Silence', '<a name="19-05-2014" id="19-05-2014"></a>\n				<div class="news standard">\n					<div class="header">The Underground Laboratory Breaks the Silence\n						<div>\n							19-05-2014\n						</div>\n					</div>\n					<div class="content">	It has been a very long time since any news have escaped from the Siberian underground. Did the Russian government finally succeed in their efforts to obliterate our secret laboratory? Was online battles merely an auspicious rumour or is it real? And if so what happened to it? It is time for the TankTrouble news department to break radio silence!<br/>\n	&nbsp;<br/>\n	To tell the story right we must go back to March 2013. TankTrouble scientists were closer than ever to realise the one thing they had always dreamt about: Online battles. The scientists had worked themselves grey-haired in countless attempts to achieve this. Now they knew exactly which bits and bytes needed to be swapped. The lead scientist - now sporting his new, grey mane - made the final, crucial tweaks and flipped the switch. The power generators struggled to maintain voltage as the network sockets expelled sparks and filled the laboratory with thick, black, suspenseful smoke. Holding their breath in anticipation (and mainly because of the smoke) the scientists breathlessly waited for visibility to return. And as it did, it revealed the very first online TankTrouble connection ever established. TankTrouble Online Early Alpha was born and for a moment the universe stood still in awe.<br/>\n	&nbsp;<br/>\n	But even in this great moment there was no time for celebration. We knew this was no beast from the petting zoo. It had to be unleashed slowly. And just like when playing Jenga while holding a jack hammer, one must consider one\'s next move carefully. So 1000 <span style="text-decoration: line-through">tank owners</span> guinea pigs were chosen at random and fed to the newborn beast. Online servers were deployed in strategically chosen locations around the world; in Germany, England, the United States and New Zealand. It seemed promising but...<br/>\n	&nbsp;<br/>\n	Although the scientists were continuously installing improvements and swatting bugs to make online destruction smoother, the servers were barely hanging in there. It soon became clear that there was one problem they could never resolve: Destruction delays. This was known as lag. The scientists tried to iron out the lag but ultimately they knew that when dealing with global destruction even a tiny delay is terminal. They knew they had to adopt a whole new, different technology and this meant taking destruction offline and going back to boot camp. And so, on a dreary evening in August the tough decision was made to shut down the online servers.<br/>\n	&nbsp;<br/>\n	Thereby the laboratory entered its darkest of ages; a time of fatigued scientists, devastating silence in the test facility and lab rats in despair; a very unproductive time in the history of destruction so let\'s fast-forward to present tense and get to the paramount question on your mind: <span class="text quote">WILL ONLINE DESTRUCTION NEVER BE?</span> And before you get into a frenzy and do something irreversible to something valuable in your immediate surroundings we want to ensure you that ONLINE DESTRUCTION WILL COME BACK!<br/>\n	&nbsp;<br/>\n	Thanks to you - the ever faithful tank owners - the scrapyard has kept piling up during this dark chapter of TankTrouble history and has served as a beacon on the path to recovery. Now, the TankTrouble Laboratory is back in business and online battles is our number one priority!<br/>\n	&nbsp;<br/>\n	<span class="text tiny">\n		FAQ<br/>\n		Q: When will online battle be back?<br/>\n		A: That\'s impossible to say. But we are back on the horse and working on it. Twentyfourseven!<br/>\n		&nbsp;<br/>\n		Q: DO YOU RIDE HORSES IN THE LABORATORY?<br/>\n		A: Not literally ...although we did follow the road apples straight to the mare\'s nest of lag. Metaphorically speaking that is.\n	</span>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-05-23', 0, 'news standard', 'Fresh Blood to the Moderation Team', '<a name="23-05-2014" id="23-05-2014"></a>\n				<div class="news standard">\n					<div class="header">Fresh Blood to the Moderation Team\n						<div>\n							23-05-2014\n						</div>\n					</div>\n					<div class="content">	Four avid TankTroublers have joined the team of moderators. They are committed to fight spam and make the forum a jolly nice place for all tank owners to discuss important tank topics. Please welcome Avenger97, buster321, Dalek-Buster and supervolcano.\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-05-26', 0, 'news standard', 'Old Dogs Retire', '<a name="26-05-2014" id="26-05-2014"></a>\n				<div class="news standard">\n					<div class="header">Old Dogs Retire\n						<div>\n							26-05-2014\n						</div>\n					</div>\n					<div class="content">	We have a strong team of moderators. And with new blood injected to the team just a few days ago it is now even stronger. Therefore we have relieved some of the old dogs from their duties. These moderators have done an amazing job. They have managed the forum and kept it kept nice and tidy - some of them for more than six years! We are forever grateful!<br/>\n	&nbsp;<br/>\n	We pay them homage with one minute of silence in the Siberian underground (that\'s scientists, lab rats and Laika included). May destruction be always in your favour!<br/>\n	&nbsp;<br/>\n	<span class="text tiny">If you are interested in the complete list of current moderators you should check out the statistics page. You will find it in <a href="?lab">The Lab</a>.</span>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-07-22', 0, 'news mobile', 'Recruiting Android Guinea Pigs', '<a name="22-07-2014" id="22-07-2014"></a>\n				<div class="news mobile">\n					<div class="header">Recruiting Android Guinea Pigs\n						<div>\n							22-07-2014\n						</div>\n					</div>\n					<div class="content">	For some time the TankTrouble mobile division has been cooking on mobile destruction for Android. Now, after some very promising tests with only minuscule lab rat casualties, we believe the prototype is ready for a field test. We therefore call on you to take up the mantle and serve the glorious cause by becoming a TankTrouble Android Beta Tester.<br/>\n	&nbsp;<br/>\n	All you need is an Android device and the urge to blow stuff up! The brave can enlist here:<br/>\n	<a href="http://www.subterraneansoftware.com/tanktrouble-android-beta-signup" target=\'_blank\'>www.subterraneansoftware.com/tanktrouble-android-beta-signup</a>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-07-28', 0, 'news mobile', 'Last Chance to Become a TankTrouble Android Guinea Pig', '<a name="28-07-2014" id="28-07-2014"></a>\n				<div class="news mobile">\n					<div class="header">Last Chance to Become a TankTrouble Android Guinea Pig\n						<div>\n							28-07-2014\n						</div>\n					</div>\n					<div class="content">	The TankTrouble Mobile Division has been overwhelmed by the sheer number of people willing to sign up as guinea pigs. As a result of this they now have as many as they need and more. Therefore the sign up window will close by the end of tomorrow. If you haven\'t signed up yet, hurry up and do it now! <a href="#22-07-2014">Read more here!</a>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-07-30', 0, 'news mobile', 'TankTrouble Android Beta Sign Ups are Now Closed', '<a name="30-07-2014" id="30-07-2014"></a>\n				<div class="news mobile">\n					<div class="header">TankTrouble Android Beta Sign Ups are Now Closed\n						<div>\n							30-07-2014\n						</div>\n					</div>\n					<div class="content">	The TankTrouble Android Beta Sign ups are now closed. Thank you to all of the brave guinea pigs who signed up. If you missed out don\'t worry there will be more, similar opportunities in the future.<br/>\n	&nbsp;<br/>\n	If you signed up and haven\'t heard from us yet. Don\'t worry. We\'ll be in touch shortly!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-08-18', 0, 'news standard', 'TankTrouble Safety Division ...what the heck?', '<a name="18-08-2014" id="18-08-2014"></a>\n				<div class="news standard">\n					<div class="header">TankTrouble Safety Division ...what the heck?\n						<div>\n							18-08-2014\n						</div>\n					</div>\n					<div class="content">	The TankTrouble safety division has just... <span class="text quote">wait! We have a safety division? Really? What the heck, I\'m supposed to write the news; not think about it. Hmm... so well:</span> The "safety division" has just added a bunch of new tools to the moderators\' toolbox. These tools will aid the moderators in their relentless efforts towards their never-ending task. Ultimately they will make TankTrouble an even better and more enjoyable place for everyone!\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-08-19', 0, 'news mobile', 'Something is Approaching...', '<a name="19-08-2014" id="19-08-2014"></a>\n				<div class="news mobile">\n					<div class="header">Something is Approaching...\n						<div>\n							19-08-2014\n						</div>\n					</div>\n					<div class="content">	<div style="text-align: center; font-size: 24px; line-height: 120px;">\n		Is it a bird? Is it a plane? No, it is...\n	</div>\n	<div style="position: absolute; right: 20px; bottom: -5px; width: 120px; height: 80px; background: url(\'images/androidScared.png\') no-repeat;">\n		&nbsp;\n	</div>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-08-25', 0, 'news mobile', 'TankTrouble for Android Launches August 29th.', '<a name="25-08-2014" id="25-08-2014"></a>\n				<div class="news mobile">\n					<div class="header">TankTrouble for Android Launches August 29th.\n						<div>\n							25-08-2014\n						</div>\n					</div>\n					<div class="content">	Rumors and speculations have it that mobile destruction is coming to Android. The TankTrouble Mobile Division is pleased to confirm this.<br>\n	<br>\n	The TankTrouble Mobile Devision have covertly worked on mobile destruction for Android for quite a while. In late July the development entered its final stage and a beta test program was launched. Many brave TankTroublers volunteered as guinea pigs. Now, a few weeks later the fatality rate amongst these guinea pigs, aka testers, has fallen to what the scientists deem an acceptable level and we are ready to unleash TankTrouble for Android on the world. As such the beta test is concluded, and the brave guinea pigs who survived will be retired from active service. We remember in our hearts those who sadly didn\'t make it, they served an invaluable role in perfecting mobile destruction for Android.<br>\n	<br>\n	<div class="text medium" style="text-align: center;">\n		TankTrouble is launching on Android August 29th - this Friday!\n	</div>\n	<br>\n</div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2014-08-29', 0, 'news mobile', 'TankTrouble Android Unleashed', '<a name="29-08-2014" id="29-08-2014"></a>\n					<div class="news mobile">\n						<div class="header">TankTrouble Android Unleashed\n							<div>\n								29-08-2014\n							</div>\n						</div>\n						<div class="content">\n							<div class="text normal" style="padding: 5px;">\n				The most explosive, fast-paced, action-packed tank game is now available for Android devices! Battle head-to-head and navigate your tank through tricky mazes and a mayhem of bouncing bullets to outsmart your foes before they outsmart you.<br>\n				&nbsp;<br>\n				Challenge your friends in local multiplayer on the same device or face the evil space dog Laika in Single Player destruction if you dare! So dust off your dodging skills and think fast before your tank is turned into shrapnel.<br>\n			</div>\n			<div style="text-align:center;">\n				<img src="images/androidIngame.jpg"/>\n			</div>\n			<div class="text large" style="text-align: center; padding: 10px;">\n				<a href="https://play.google.com/store/apps/details?id=com.subterraneansoftware.tanktrouble.android" target="_blank">Get TankTrouble for Android now!</a>\n			</div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-09-22', 0, 'news standard', 'Hacking Investigated', '<a name="22-09-2014" id="22-09-2014"></a>\n					<div class="news standard">\n						<div class="header">Hacking Investigated\n							<div>\n								22-09-2014\n							</div>\n						</div>\n						<div class="content">\n							Rumor has it that hackers have been hijacking TankTrouble accounts. Here in the laboratory we find it hard to believe that anyone would be cable of penetrating the impenetrable Sibirian soil and our incineratingly hot firewalls and tamper with our servers. Nonetheless, we did investigate all known incidents.<br>\n			&nbsp;<br>\n			TankTrouble scientists have found no evidence whatsoever that security has been breached. The so called "hackers" simply tries to guess tank owners\' passwords or lure and scam unsuspecting tank owners to give up their password. So to make sure that you do not get tank-jacked:<br>\n			1. Make sure your password impossible to guess (you can change it in the Garage)<br>\n			2. Never share your password; not with friends, not with moderators, not with grandma, not with anyone!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-09-29', 0, 'news mobile', 'Frag Bomb and Gatling Gun Make it to Mobile', '<a name="29-09-2014" id="29-09-2014"></a>\n					<div class="news mobile">\n						<div class="header">Frag Bomb and Gatling Gun Make it to Mobile\n							<div>\n								29-09-2014\n							</div>\n						</div>\n						<div class="content">\n							At our weekly damage assessment, err... performance review, the TankTrouble Mobile Division were excited to see that heaps of blown up tanks are already piling up in the TankTrouble Android app.<br>\n			&nbsp;<br>\n			The team, not ones to rest on their laurels, have since the launch been working on bringing their favourite, destructive evergreens to mobile. They are therefore delighted to announce that TankTrouble Android now has both the Frag Bomb and the Gatling Gun for maximum mayhem!<br>\n			&nbsp;<br>\n			If you haven\'t already, be sure to pick up <a href="https://play.google.com/store/apps/details?id=com.subterraneansoftware.tanktrouble.android" target="_blank">TankTrouble for Android here</a> and use these latest powerups to decimate your foes in a frenzy of bullets and shrapnel!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-10-20', 0, 'news halloween', 'Paranormal Activity in the Garage', '<a name="20-10-2014" id="20-10-2014"></a>\n					<div class="news halloween">\n						<div class="header">Paranormal Activity in the Garage\n							<div>\n								20-10-2014\n							</div>\n						</div>\n						<div class="content">\n							As proud, no-nonsense TankTrouble scientists we tend to only believe in things that leave a crater. However, we cannot ignore the recent, extraordinarily high readings of paranormal activity as we approach All Hallow\'s eve. Rather than performing a cumbersome exorcism of the creepy ghouls that have once again emerged from the cracks of our secret, underground laboratory, we locked them in <a href="?garage">the Garage</a>.<br>\n			&nbsp;<br>\n			Go there now to claim some supernatural tankcessories and get a head start on this year\'s trick \'r treatin\'!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-10-29', 0, 'news important', 'Getting Close to 1.000.000.000 Demolished Tanks', '<a name="29-10-2014" id="29-10-2014"></a>\n					<div class="news important">\n						<div class="header">Getting Close to 1.000.000.000 Demolished Tanks\n							<div>\n								29-10-2014\n							</div>\n						</div>\n						<div class="content">\n							The Scrapyard is counting faster than ever and just a few hours ago, we realized that there are less than ten million explosions left before we reach the staggering number of one billion scrapped tanks!<br>\n			&nbsp;<br>\n			The Scrapyard was never built to display this insane amount of destruction and the lead scientists worry what will happen when that final number flips and the Scrapyard runs out of digits. The circuits on the counter have already started to look red hot and sparks are flying everywhere from the capacitors.<br>\n			&nbsp;<br>\n			To calm our nerves and get some answers, we have put our topnotch analyst and his Turbo-Bit-Analytics thingamajig on the case. He is busy feeding all of our destructive data into the very sophisticated and complex forecast algorithms to predict the exact time of the event. We expect to hear back from him in a few days.\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-10-31', 0, 'news halloween', 'OOOoooOOOoooohhhh! Let the Candy Soliciting Begin', '<a name="31-10-2014" id="31-10-2014"></a>\n					<div class="news halloween">\n						<div class="header">OOOoooOOOoooohhhh! Let the Candy Soliciting Begin\n							<div>\n								31-10-2014\n							</div>\n						</div>\n						<div class="content">\n							<div style="position: absolute; bottom: 2px;"><img style="width: 150px;" src="../images/halloweenSwag.png" /></div>\n			<div style="margin-left: 180px;">\n				Tonight we celebrate the undead whilst devouring bucketloads of sweets. Or so we thought... Unfortunately, the lab rats located our candy stash and only left the chocolate bunnies we didn\'t finish at Easter; candy soliciting in the corridors of the laboratory will be a disillusioning experience this year. We hope you have better luck.<br>\n				&nbsp;<br>\n				And if you haven\'t already, hurry to <a href="?garage">the Garage</a> and claim some creepy swag. At midnight evil will retire leaving our secret underground laboratory as dark, creepy and untenanted as when it came. Just like a secret laboratory is supposed to be!<br>\n				&nbsp;<br>\n				Happy Halloween!\n			</div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-02', 0, 'news important', 'Fears Confirmed: Scrapyard Will Run Out!', '<a name="02-11-2014" id="02-11-2014"></a>\n					<div class="news important">\n						<div class="header">Fears Confirmed: Scrapyard Will Run Out!\n							<div>\n								02-11-2014\n							</div>\n						</div>\n						<div class="content">\n							Our topnotch Turbo-Bit-Analytics machine has now spent several days crunching on the question of when the Scrapyard will reach one billion. Just a few minutes ago, the dot matrix printer spat out the result of this extremely complex computation. First of all, the machine thinks that it is very likely that the Scrapyard will indeed flip its final digit at some point in the future. At least that\'s how we interpret the first line of its output:<br/>\n			&nbsp;<br/>\n			<div style="font-family: Courier">\n				"97% YES AND 3% MAYBE"\n			</div><br/>\n			Secondly, the next few lines seem to indicate that it will happen pretty soon:<br/>\n			&nbsp;<br/>\n			<div style="font-family: Courier">\n				"604.821.347,1 MS"<br/>\n				"604.821.351,3 MS"\n			</div><br/>\n			We think this means that the Scrapyard will run out anywhere between 604.821.347,1 milliseconds and 604.821.351,3 milliseconds from now, which our top mathematicians estimate to be sometime next Sunday!<br/>\n			&nbsp;<br/>\n			The laboratory is in a state of near-panic as the lead Scrapyard scientist has not been seen since he went to feed Laika five years ago. His office looks like it has been empty for quite some time judging by the amount of lab rats that have moved in. They have chewed on all the circuitry of his terminal and we have been unable to locate the Scrapyard source code anywhere.<br/>\n			&nbsp;<br/>\n			The situation is starting to become critical...\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-04', 0, 'news important', 'Scrapyard Source Code Nowhere to be Found', '<a name="04-11-2014" id="04-11-2014"></a>\n					<div class="news important">\n						<div class="header">Scrapyard Source Code Nowhere to be Found\n							<div>\n								04-11-2014\n							</div>\n						</div>\n						<div class="content">\n							<div style="position: absolute; right: 0px; right: 30px;top: -35px;">\n				<img src="../images/polaroidDonut.png" />\n			</div>\n			<div style="position: absolute; right: 10px; top: 60px;">\n				<img src="../images/polaroidShaft.png" />\n			</div>\n			<div style="position: absolute; left: 230px; top: 2px;">\n				<img src="../images/toDo.png" />\n			</div>\n			<div style="width: 215px; height: 395px;">\n				The Scrapyard is now only 5 millions short of reaching 1B and thereby running out of digits.<br>\n				<br>\n				This is a major concern to the scientists. We do not know where that extra digit will go when it will not fit in the Scrapyard. If not contained it could cause irreversible damage as it pootles around on the servers.<br>\n				<br>\n				To prevent this from happening it is critical that we find the original source code.<br>\n				<br>\n				Unfortunately, the scientist who made the Scrapyard has not been seen for five years. As our search team went through the stuff in his office, we found his old to-do list. It confirms the grim suspicion that we are unlikely to ever find the source code.<br>\n				<br>\n				What will happen when we reach 1.000.000.000? Will it be the end of TankTrouble?<br>\n				<br>\n				Stand by for more news soon!\n			</div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-07', 0, 'news important', 'Get Ready to Suit Up!', '<a name="07-11-2014" id="07-11-2014"></a>\n					<div class="news important">\n						<div class="header">Get Ready to Suit Up!\n							<div>\n								07-11-2014\n							</div>\n						</div>\n						<div class="content">\n							The Scrapyard ticks relentlessly onwards toward what might turn out to be the end of days...<br/>\n			<br/>\n			Or at least the end of TankTrouble... Or both!<br/>\n			<br/>\n			The search team has been desperately combing all the known sectors of our underground laboratory in order to locate a shred of the original Scrapyard source code. So far their efforts have been futile. And while time is running out, the laboratory is vast and many of the subterranean levels remain completely uncharted. The light at the end of the laboratory corridor is fading, so to speak.<br>\n			<br/>\n			<div style="height: 135px; background: url(\'images/hazmatSuit.png\') no-repeat; margin: 0 50px 0 50px; padding-left: 315px;">\n				The search team did come across a hazmat airlock with quite a few intact-looking suits. These suits might come in handy if everything goes haywire.<br/>\n				<br/>\n				We will be handing them out, starting when the Scrapyard reaches 999 million. Be sure to log in then to claim yours!<br/>\n			</div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-09', 0, 'news important', 'Evacuation Imminent - Suit Up!', '<a name="09-11-2014" id="09-11-2014"></a>\n					<div class="news important">\n						<div class="header">Evacuation Imminent - Suit Up!\n							<div>\n								09-11-2014\n							</div>\n						</div>\n						<div class="content">\n							<div style="width: 100%; text-align: center;">\n				<img src="images/999MillionAndCounting.jpg"/>\n			</div>\n			<br/>\n			The Scrapyard is now less than 1 million short of running out of digits. And yet it ticks faster than ever towards its own apocalypse. Our Turbo-Bit-Analytics machine estimates that we will impact 1B in less than 24 hours!<br/>\n			<br/>\n			At this point, the search team has abandoned all hope of ever recovering the original Scrapyard source code. Therefore, it is with grim determination that all TankTrouble scientists (and lab rats) have decided to evacuate into the maximum security bunker. Hopefully, we will be safe there when the lab rat poop hits the air duct fan (metaphorically speaking, that is).<br/>\n			<br/>\n			In your Garage you will find a hazmat suit. We strongly advise that you suit up immediately!<br/>\n			<br/>\n			Thank you for all the scraps. See you on the other side!<br/>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-10', 0, 'news glitch', '1.000.000.000 Tanks Destroyed!', '<a name="10-11-2014" id="10-11-2014"></a>\n					<div class="news glitch">\n						<div class="header">1.000.000.000 Tanks Destroyed!\n							<div>\n								10-11-2014\n							</div>\n						</div>\n						<div class="content">\n							<div id="glitchNews1">\n        		After 24 hours crammed together in the hermetically sealed, maximum security bunker staring at the scrapyard counting down towards the apocalypse through the steamed-up glasses of our boiling-hot hazmat suits, we developed a great sympathy for shrimp. But one of the scientists has seafood allergies so the cantina rarely serves shrimp anyway.<br/>\n				<br/>\n				And so, even though the impending apocalypse was only a few scraps away, the thought of it was almost relieving.<br/>\n				<br/>\n				At 0400 hours we received a cryptic message from The Bahamas on our fax: &#x2588;&#xe355;&#xe353;&#xe25c;&#x2588;&#xe224;&#xe345;&#xe343;&#xe352;&#xe233;&#xe354;&#x2588;&#xe342;&#xe234;&#xe343;&#xe34b;&#xe344;&#xe230;&#xe230;&#xe352;&#x2588;&#xe349;&#xe34e;&#x2588;&#xe255;&#xe252;&#xe26c;&#x2588;<br/>\n				<br/>\n				At 0600 hours Dimitri found a stash of canned beans.<br/>\n				<br/>\n				At 0700 hours the intern failed to restrain some natural gasses which was consequently released into the re-breather of his suit.<br/>\n				<br/>\n				But let\'s get to the point:<br/>\n				<br/>\n				At 1630 hours Siberian main time, the Scrapyard made it to &#xe239;&#xe239;&#xe239;&#xe239;&#xe239;&#xe239;&#xe239;&#xe239;&#xe239;. The scientists held their breath (the intern too, but for health reasons mostly) while awaiting the silence to be replaced by the deafening sound of doom.<br/>\n				<br/>\n				But the gods of destruction must have had a keen eye on our laboratory and postponed the apocalypse. And as we realised that our underground laboratory was still intact, we hasted back to the control room to find that something had gone terribly wrong. The extra digits that did not fit in the Scrapyard are now unleashed on the servers causing long forgotten pixels from the early days of computing to resurface. This is causing all sorts of bizarre glitches.<br/>\n				<br/>\n				The scientists are doing everything they can to contain the loose bits. Stay tuned!\n            </div>\n            <script type="text/javascript">\n                <!--\n                    function scramble( s, u ) {\n                        return s.replace(\n                            /\\b([a-z])([a-z]+)([a-z])\\b/gi,\n                                function( t, a, b, c ) {\n                                    b = b.split( /\\B/ );\n                                    for( var i = b.length, j, k; i; j = (Math.random() < u ? i : i + 1),\n                                        k = b[--i], b[i] = b[j], b[j] = (Math.random() < u ? k : \'&#x0ee\'+Math.floor(Math.random()*256.0).toString(16)+\';\') ) {}\n                                            return a + b.join( \'\' ) + c;\n                                }\n                            );\n                    };\n                    var messageGlitch1 = document.getElementById("glitchNews1").innerHTML;\n                    setInterval(function(){document.getElementById("glitchNews1").innerHTML = scramble(messageGlitch1, 0.99)}, 150);\n                // -->\n            </script>\n\n			\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-15', 0, 'news standard', '1 Billion Scraps Damage Assessment', '<a name="15-11-2014" id="15-11-2014"></a>\n					<div class="news standard">\n						<div class="header">1 Billion Scraps Damage Assessment\n							<div>\n								15-11-2014\n							</div>\n						</div>\n						<div class="content">\n							The spillover digits that did not fit the Scrapyard when we hit 1.000.000.000 destroyed tanks remain loose on the servers. This is causing things to behave most unexpectedly: The Scrapyard has gone bananas and there are reports of glitchy tankcessories in the Garage. Scientists believe this to be only moderately dangerous. They are doing everything they can to contain the extra digits and bring TankTrouble back to normal.\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-17', 0, 'news standard', 'Greeting from The Bahamas', '<a name="17-11-2014" id="17-11-2014"></a>\n					<div class="news standard">\n						<div class="header">Greeting from The Bahamas\n							<div>\n								17-11-2014\n							</div>\n						</div>\n						<div class="content">\n							<div style="position: absolute; top: 5px; left: 302px;">\n				<img src="../images/greetingsFromTheBahamas.png" />\n			</div>\n			<div style="width: 280px;">\n				The location of our underground laboratory is top secret, so we never get any mail and therefore we never empty the mailbox. However, the intern ordered some C4 on Amazon and had it shipped directly. Apparently he did not get the top-secret-location-memo... Anyways, when he emptied the mailbox, he found a postcard. It had been sitting there for years and as it turns out, it is from our very own, missing Scrapyard scientist whom we assumed to be devoured by Laika!<br/>\n				<br/>\n				The content of the postcard is classified but we can disclose the last passage:<br/>\n				<br/>\n				<span class="text quote">\n					...after feeding Laika I decided to spend some flex time and go chill on a beach. Meanwhile, I hope you find the secret backdoors I\'ve implemented to avoid the inevitable Scrapyard apocalypse. I\'m working on my tan lines and will return to the underground laboratory shortly.<br/>\n					<br/>\n					Your\'s sincerely,<br/>\n					The Scrapyard scientist<br/>\n					<br/>\n					Ps. When you cannot sleep, count some sheep. 50\'s my high, give it a try!\n				</span><br/>\n				<br/>\n				This is good news and we look forward to have him back underground.\n			</div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-24', 0, 'news standard', 'Scrapyard Duct Taped', '<a name="24-11-2014" id="24-11-2014"></a>\n					<div class="news standard">\n						<div class="header">Scrapyard Duct Taped\n							<div>\n								24-11-2014\n							</div>\n						</div>\n						<div class="content">\n							While we wait for the Scrapyard scientist to return from The Bahamas we have put the collective power of all the brainy brains in the laboratory together and come up with an elegant, temporary fix. The counting must go on!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-26', 0, 'news standard', 'Loose Scrapyard Digits Finally Contained', '<a name="26-11-2014" id="26-11-2014"></a>\n					<div class="news standard">\n						<div class="header">Loose Scrapyard Digits Finally Contained\n							<div>\n								26-11-2014\n							</div>\n						</div>\n						<div class="content">\n							The Scrapyard scientist got his tan lines and priorities straightened out and he is now back from The Bahamas. With his brilliant Scrapyard expertise, we were soon able to contain the spill over digits. We breathe a sigh of relief as we conclude: TankTrouble is back to normal.<br/>\n			<br/>\n			Tank owners who have managed to collect glitchy tankcessories will keep those. And should you want to expand your collection, we have left the secret backdoors ajar...\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-11-28', 0, 'news standard', 'Destruction Too Fast for Scrapyard', '<a name="28-11-2014" id="28-11-2014"></a>\n					<div class="news standard">\n						<div class="header">Destruction Too Fast for Scrapyard\n							<div>\n								28-11-2014\n							</div>\n						</div>\n						<div class="content">\n							During peak destruction hours more than 37 tanks are blown up per second. The old Scrapyard was never built for this swoopingly fast destruction and it simply could not keep up any more. What an awesome problem!<br>\n			<br>\n			We have greased the wheels, polished the appearance and we now challenge you to make it fall behind again!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-12-16', 0, 'news christmas', 'TankTrouble Celebrates its 7 Year Anniversary', '<a name="16-12-2014" id="16-12-2014"></a>\n					<div class="news christmas">\n						<div class="header">TankTrouble Celebrates its 7 Year Anniversary\n							<div>\n								16-12-2014\n							</div>\n						</div>\n						<div class="content">\n							Today it is exactly 7 years since TankTrouble first emerged from the Siberian underground. To celebrate this special day, we have dropped a double ration of dog treats into shaft G-4 (for Laika) and allowed the lab rats half a day off. As for the scientists and tanktroublers, we have treated ourselves with an early Christmas present: A brand new, lightning fast server.<br>\n			<br>\n			The ever growing junta of tanktroublers have pushed our server to its limits. This has caused TankTrouble to load very slowly during peak destruction hours. Now those days are over. Our brand new server is so fast it will make Darth Vader think hyperspeed is a drag. So who cares that we had to pawn our souls to the Devil to be able to afford it.<br>\n			<br>\n			On behalf of all the scientists:<br>\n			Thank YOU for making it all worthwhile!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2014-12-25', 0, 'news christmas', 'Merry Christmas to All Tanktroublers', '<a name="25-12-2014" id="25-12-2014"></a>\n					<div class="news christmas">\n						<div class="header">Merry Christmas to All Tanktroublers\n							<div>\n								25-12-2014\n							</div>\n						</div>\n						<div class="content">\n							We still have not received the nuclear reactor we ordered from Santa for Christmas in 2012. We got word from him that he was sorry to be out of stock. Then in 2013 Rudolf refused delivery due to new reindeer union regulations on overweight. So from the bottom of our warm scientist hearts we sincerely hope that Santa have sorted these issues out this Christmas.<br>\n			<br>\n			From our secret laboratory in the cold Siberian underground with eggnog in our mustaches and gingerbread between our teeth we wish you all a very merry Christmas.\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-01', 0, 'news standard', 'Happy New Year to All TankTroublers', '<a name="01-01-2015" id="01-01-2015"></a>\n					<div class="news standard">\n						<div class="header">Happy New Year to All TankTroublers\n							<div>\n								01-01-2015\n							</div>\n						</div>\n						<div class="content">\n							As 2014 is about to become history, jovial spirits and cheerfulness have filled the corridors of our otherwise cold and aloof underground laboratory. For this year\'s trivia, our database expert has extracted that this year we have destroyed 276.658.565 tanks. That is 8.7 tank per second, all year round, 24 hours a day, day and night! That makes the Big Bang sound like a Chinese firecracker!<br>\n			<br>\n			Looking ahead into 2015 we have some very serious plans! We will tell you all about them later. Because, tonight we devote our time to confetti, silly paper hats and the unexploded nuclear device we found on our latest scavenger hunt in the unexplored parts of our underground laboratory. And, of course, blowing up tanks on our brand new TankTrouble iOS app!<br>\n			<br>\n			Yes, you heard that right, we are so excited to announce that TankTrouble is back on iOS featuring Laika and four weapon powerups! And if you own an Android device, do not fear, you have not been forgotten: an update has just been rolled out bringing the RC Missile and Laser powerups to your device! So get your New Year off to a banging start and get TankTrouble for your mobile device now!<br>\n			<br>\n			<a href="https://itunes.apple.com/app/tanktrouble-mobile-mayhem/id951971414?ls=1&mt=8" target="_blank"><img src="images/availableOnTheAppStore120.jpg"/></a>&nbsp;&nbsp;<a href="https://play.google.com/store/apps/details?id=com.subterraneansoftware.tanktrouble.android" target="_blank"><img src="images/getItOnGooglePlay.png"/></a>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-07', 0, 'news important', 'Influx of New Players Brings Server to its Knees', '<a name="07-01-2015" id="07-01-2015"></a>\n					<div class="news important">\n						<div class="header">Influx of New Players Brings Server to its Knees\n							<div>\n								07-01-2015\n							</div>\n						</div>\n						<div class="content">\n							<img style="margin-right: 15px; float: left; width: 180px;" src="../images/visits20150107.png">\n\n			The past few days TankTrouble has been swamped with new players from all over the world. Never before have we seen this many players online at the same time.<br>\n			<br>\n			This has brought our brand new server to its knees. The website has been extraordinarily slow  - sometimes to the point that loading it required more patience than eating pea soup with chopsticks - a level of patience that fans of blowing up tanks rarely possess.<br>\n			<br>\n			We have tweaked, fine tuned and made sacrifices to the gods. Now it looks like our new server handles mass destruction too.<br>\n			<br>\n			We are delighted to have these kinds of problems - bring \'em!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-13', 0, 'news standard', 'Will TankTrouble Go Online in 2015?', '<a name="13-01-2015" id="13-01-2015"></a>\n					<div class="news standard">\n						<div class="header">Will TankTrouble Go Online in 2015?\n							<div>\n								13-01-2015\n							</div>\n						</div>\n						<div class="content">\n							More and more players join TankTrouble from all over the world. And here in the underground laboratory it is our biggest dream to join everyone in awesome, fun online battles.<br/>\n			<br/>\n			Those of you who have been around long enough know that we have attempted online battles before.\n			And failed. Now we are smarter and stronger (and more handsome) and we will succeed - may the gods of destruction descend upon us if we don\'t. Making TankTrouble online is going to be difficult. We will need YOUR help!<br/>\n			<br/>\n			<div style="text-align: center"><a class="text large" href="http://goo.gl/forms/vfyLvRJpO4" target="_blank">Click here if you have one minute to answer a few simple questions</a></div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-16', 0, 'text medium', 'Action-packed Wallpaper', '<a name="16-01-2015" id="16-01-2015"></a><div class="text medium" style="margin-bottom: 10px; background-image: url(\'images/busyMaze.png\'); border: 2px #000000 solid; border-radius: 4px;"><div class="text white" style="font-weight: bold; background-color: #000000; padding: 5px;">\n					Action-packed Wallpaper	\n						<div style="float: right;">\n							16-01-2015\n						</div>\n					</div><div style="padding: 10px;">\n						The intern has made a visualisation of what online battles might look like. It makes rush hour in the tubes of London underground seem like a tranquil, relaxing experience. Online battles will be intense!<br/>\n				<br/>\n				If you want an action-packed desktop you can <a href="?lab">download the wallpaper here.</a><br/>\n				<br/>\n				Speaking of online battles; have you filled in the online battles questionnaire yet? It will help us tremendously in finally bringing TankTrouble online. So if you haven\'t already, please do!<br/>\n				<br/>\n				<div style="text-align: center"><a class="text large" href="http://goo.gl/forms/vfyLvRJpO4" target="_blank">Click here if you have one minute to answer a few simple questions</a></div>\n					</div></div>'),
('2015-01-19', 0, 'news important', 'The Intern Purges Archives and Crashes Server', '<a name="19-01-2015" id="19-01-2015"></a>\n					<div class="news important">\n						<div class="header">The Intern Purges Archives and Crashes Server\n							<div>\n								19-01-2015\n							</div>\n						</div>\n						<div class="content">\n							After years of destruction our servers were cluttered with old records and logs. This has shackled the server performance in balls and chains for too long. It was time to purge the dusty archives, so we tasked the intern with this undertaking.<br/>\n             <br/>\n             While cleaning he managed to crash the servers multiple times over the last couple of hours.<br/>\n             <span class="text red">Because of this, your kills and experience may or may not have been recorded in this period!</span><br/>\n             The Intern sends his sincere apologies.<br/>\n             <br/>\n             We should have known better than to leave that featherbrain unattended with the servers. We should now be back to normal again.\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-20', 0, 'news standard', 'Last Chance to Fill in Online Battles Questionnaire', '<a name="20-01-2015" id="20-01-2015"></a>\n					<div class="news standard">\n						<div class="header">Last Chance to Fill in Online Battles Questionnaire\n							<div>\n								20-01-2015\n							</div>\n						</div>\n						<div class="content">\n							Will TankTrouble have online battles in 2015? It is up to YOU!<br/>\n			<br/>\n			Help the underground scientists by filling in the online questionnaire. Heaps of players have already submitted their answers so we will be closing the questionnaire sometime tommorrow. If you have not yet submitted your answers, do so now!<br/>\n			<br/>\n			<div style="text-align: center"><a class="text large" href="http://goo.gl/forms/vfyLvRJpO4" target="_blank">I want to help - show me the questionnaire!</a></div>\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-21', 0, 'news standard', 'Online Battles Questionnaire Closed for Submission', '<a name="21-01-2015" id="21-01-2015"></a>\n					<div class="news standard">\n						<div class="header">Online Battles Questionnaire Closed for Submission\n							<div>\n								21-01-2015\n							</div>\n						</div>\n						<div class="content">\n							The online battles questionnaire is now closed for submissions.<br/>\n			<br/>\n			We have received a lot more answers than we expected. There is much eager enthusiasm and great willingness to support the development. And that is just AWESOME! Because the future of online battles depends on YOU!<br/>\n			<br/>\n			Now we will feed all your answers into our Turbo-Bit-Analytics machine. It will compute the development route to online battles with the highest probability of success. The underground laboratory awaits this computation with great anticipitation. Stay tuned!\n						</div>\n						<div class="bottom">\n						</div>\n					</div>'),
('2015-01-23', 0, 'news3 standard', 'Turbo-Bit-Analytics Machine Still Computing', '<a name="23-01-2015" id="23-01-2015"></a><div class="news3 standard"><div>\n						Turbo-Bit-Analytics Machine Still Computing\n						<div>\n							23-01-2015\n						</div>\n					</div><div>The Turbo-Bit-Analytics machine is still chewing on the answers from the questionnaire. Admittedly, it is not as top-notch as we first assumed (we found it scavenging unexplored parts of our underground laboratory).	With tense excitement we await for it to forecast the future of online battles.<br/>\n				<br/>\n				Meanwhile, check out this cool animation: The Story of Laika.<br/>Created by a dedicated fan!<br/>\n				<br/>\n				<iframe width="668" height="400" src="//www.youtube.com/embed/VEsCL-5sRAM" frameborder="0" allowfullscreen></iframe></div></div>'),
('2015-01-28', 0, 'news3 standard', 'Questionnaires Shredded!', '<a name="28-01-2015" id="28-01-2015"></a><div class="news3 standard"><div>\n						Questionnaires Shredded!\n						<div>\n							28-01-2015\n						</div>\n					</div><div>After a week of intense computing the Turbo-Bit-Analytics machine was ready to reveal its answer this morning - are online battles feasible or not?	Too excited to learn the answer to this paramount question, the scientists gulped down breakfast faster than a T-Rex can say hotdog and then hurried to the analytics room.<br/>\n				<br/>\n				They were most disheartened to find out that the intern, who was responsible for inputting the questionnaire answers, had mistaken the Turbo-Bit-Analytics machine for the office shredder (with all those answers we got, no wonder it took a week).<br/>\n				<br/>\n				But all is not lost!<br/>\n				We have provided the intern with tape and expect to be ready to feed the actual Turbo-Bit-Analytics machine the questionnaires tomorrow. Unfortunately, this means We will have to wait another day or two for this most important answer.</div></div>'),
('2015-01-30', 0, 'news3 standard', 'Questionnaire Results Favour Online Battles!', '<a name="30-01-2015" id="30-01-2015"></a><div class="news3 standard"><div>\n						Questionnaire Results Favour Online Battles!\n						<div>\n							30-01-2015\n						</div>\n					</div><div>We are pleased to announce that after 47 hours and roughly 347.2 meters of tape, the intern finished mending the last questionnaire two hours ago. We immediately fed them to the Turbo-Bit-Analytics machine (aka. TBA).<br/>TBA made its computations unexpectedly speedy:<br/>\n				<br/>\n				<span style="font-family: Courier">"CHANCE OF SUCCESSFUL KICKSTARTER: 92% YES AND 3% YOGHURT"</span><br/>\n				<br/>\n				The support and willingness to help the development of online battles is beyond what any scientist could have hoped for. We are wholeheartedly honored! Therefore it is with great excitement that we hereby announce that...<br/>\n				<br/>\n				<div class="text large" style="text-align: center;">\n					WE WILL DO A KICKSTARTER TO DEVELOP ONLINE BATTLES<br/>\n					The Kickstarter campaign will start soon.<br/>\n					Stay posted!\n				</div>\n				<br/>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					What is a Kickstarter?<br/>\n					A Kickstarter is a way to crowd-fund a project.	We will surrender all our time to develop online battles but we are going to need financial support, too. By supporting our Kickstarter campaign you can help. And you will get awesome rewards too!<br/>\n					Check out <a href="http://www.kickstarter.com">www.kickstarter.com</a>\n				</div></div></div>'),
('2015-02-06', 0, 'news3 kickstarter', 'Kickstarter Rewards Sneak Peek', '<a name="06-02-2015" id="06-02-2015"></a><div class="news3 kickstarter"><div>\n						Kickstarter Rewards Sneak Peek\n						<div>\n							06-02-2015\n						</div>\n					</div><div><div style="height: 240px; position:relative; width: 440px;">\n					Thanks for all the great suggestions for Kickstarter rewards. We have been following the discussions on the forum closely and we think you will just love the stuff we have built. Here\'s a little sneak peek...\n					<img style="position: absolute; top: -50px; left: 90px;" src="images/kickstarterCrates554x227.png" />\n				</div>\n				...and this is just for starters! Launch is imminent! Stand by!<br/>\n				<br/>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					What is a Kickstarter?<br/>\n					A Kickstarter is a way to crowd-fund a project.	We will surrender all our time to develop online battles but we are going to need financial support, too. By supporting our Kickstarter campaign you can help. And you will get awesome rewards too!<br/>\n					Check out <a href="http://www.kickstarter.com">www.kickstarter.com</a>\n				</div></div></div>'),
('2015-02-09', 0, 'news standard', 'TANK POLL', '<a name="09-02-2015" id="09-02-2015"></a>\n				<div class="news standard">\n					<div class="header">TANK POLL\n						<div>\n							09-02-2015\n						</div>\n					</div>\n					<div class="content"><div id="poll-6-content" class="middle text small">The Kickstarter reward sneak peek has revealed some sweet-looking tankcessory crates. <br/>&nbsp;<br/><div id="poll-6-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-6-closedSign" src="images/thisPollIsClosed.png"/></div>Which crate do YOU think contains the best swag?<br/><br/></div></div><table id="poll-6-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollKickstarterCrates.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Kickstarter Crate <span class="text tiny">(1924 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 150.64876957494px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Rainbow Crate <span class="text tiny">(2596 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 203.26621923937px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The Onyx Crate <span class="text tiny">(4470 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2015-02-16', 0, 'news4 kickstarter', 'Kickstarter Countdown Has Started', '<a name="16-02-2015" id="16-02-2015"></a><div class="news4 kickstarter" style="margin-top: 117px; position:relative;"><div>\n						Kickstarter Countdown Has Started\n						<div>\n							16-02-2015\n						</div>\n					</div><div><img style="position: absolute; top: -151px; left: 0px;"  src="images/kickstarterRewards.png" />\n	            We have followed YOUR suggestions for rewards intensely and now we believe we are ready to Kickstart! Stay posted for a more detailed description of the awesome rewards we have planned!<br/>\n                <br/>\n                The countdown has already begun and we are getting all our dogs in a row for the grand launch this Friday. We really need YOUR support to make TankTrouble Online Battles happen!<br/>\n				<br/>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					What is a Kickstarter?<br/>\n					A Kickstarter is a way to crowd-fund a project.	We will surrender all our time to develop online battles but we are going to need financial support, too. By supporting our Kickstarter campaign you can help. And you will get awesome rewards too!<br/>\n					Check out <a href="http://www.kickstarter.com">www.kickstarter.com</a>\n				</div></div></div>'),
('2015-02-20', 0, 'news4 kickstarter', 'Kickstarter Postponed Temporarily', '<a name="20-02-2015" id="20-02-2015"></a><div class="news4 kickstarter" style=""><div>\n						Kickstarter Postponed Temporarily\n						<div>\n							20-02-2015\n						</div>\n					</div><div>We are very sorry to announce that the Kickstarter for online battles has been postponed for a little bit. This means that we have stopped the countdown temporarily.<br/>\n                <br/>\n                The reason for all this trouble is simply that we have underestimated the time it would take for Kickstarter to approve our project. We are doing everything we can to get that countdown ticking again! As soon as we know more, we will let you know.<br/>\n                <br/>\n                Thanks for your patience!</div></div>'),
('2015-02-21', 0, 'news4 kickstarter', 'TankTrouble Kickstarter Approved - Countdown Resumes', '<a name="21-02-2015" id="21-02-2015"></a><div class="news4 kickstarter" style=""><div>\n						TankTrouble Kickstarter Approved - Countdown Resumes\n						<div>\n							21-02-2015\n						</div>\n					</div><div>Unfortunately, our original countdown turned out to be faster than Kickstarter\'s approval time. Hence, we had to put the countdown on hold. We regret this little hiccup and eat humble pie. But now...<br/>\n				<br/>\n				<div style="text-align: center;">\n					<span class="text large">KICKSTARTER HAS APPROVED OUR PROJECT</span><br/>\n					and has given the laboratory full control to launch at will!<br/>\n				</div>\n				<br/>\n				Although we underground scientists have self-discipline like a T-Rex in a hotdog stand, we shall contain ourselves. So we have set back the countdown to give everyone a chance to be there when we launch.<br/>\n				<br/>\n				<div class="text large" style="text-align: center;">\n					We launch on Monday at 1200 hours UTC!\n				</div>\n				<br/>\n				Please help bring TankTrouble online and prepare yourself for some awesome rewards!</div></div>'),
('2015-02-23', 0, 'news4 kickstarter', 'TankTrouble Kickstarter Launched', '<a name="23-02-2015" id="23-02-2015"></a><div class="news4 kickstarter" style=""><div>\n						TankTrouble Kickstarter Launched\n						<div>\n							23-02-2015\n						</div>\n					</div><div>The time has finally come to launch our Kickstarter for bringing TankTrouble online! We are very grateful for the support shown by you. Together, we will certainly be able to let TankTrouble players from all over the world battle it out online. Once again, we thank you for making TankTrouble friendly and welcoming, and for keeping the game alive! Now, go get those amazing rewards!<br/>\n				<br/>\n				<div style="text-align: center;">\n					<span class="text large"><a href="https://www.kickstarter.com/projects/1976320862/tanktrouble-online-battles" target="_blank">TankTrouble Online Battles Kickstarter</a></span>\n				</div>\n				<br/></div></div>'),
('2015-03-05', 0, 'news4 kickstarter', 'By Popular Demand: New Kickstarter Rewards', '<a name="05-03-2015" id="05-03-2015"></a><div class="news4 kickstarter" style="position: relative;"><div>\n						By Popular Demand: New Kickstarter Rewards\n						<div>\n							05-03-2015\n						</div>\n					</div><div><img src="images/newStamp.png" style="left: 50px; position: absolute; top: 20px; width: 120px;">\n				<div style="text-align: center;">\n					<img src="images/hoodies.png">\n				</div>\n				After multiple inquries from backers desiring the black hoodie worn by Purup in the Kickstarter video, we decided to make it a reward. Claim one of these awesome hoodies today!\n				<div style="text-align: center;">\n					<span class="text large"><a href="https://www.kickstarter.com/projects/1976320862/tanktrouble-online-battles" target="_blank">Go to Kickstarter</a></span>\n				</div></div></div>'),
('2015-03-18', 0, 'news4 kickstarter', 'Anonymous Backer Pushes Kickstarter to 96%', '<a name="18-03-2015" id="18-03-2015"></a><div class="news4 kickstarter" style=""><div>\n						Anonymous Backer Pushes Kickstarter to 96%\n						<div>\n							18-03-2015\n						</div>\n					</div><div>This morning the lead scientist of online battles opened a can of musk ox milk and drenched his cornflakes. While chowing down breakfast he routinely checked Kickstarter for new backers but was then suddenly paralysed in shock.<br>\n				<br>\n				At first we thought he was overly surprised to see that the Kickstarter had mysteriously been 96% funded overnight, but later we found out that the canned musk ox milk had expired in 1957.<br>\n				<br>\n				Fortunately, the scientist soon recovered and everybody in the secret, underground laboratory marvelled at the new mystery backer:<br>\n				<br>\n				An anonymous backer has pledged an astounding $3500! Whoever you are, we are eternally thankful!<br>\n				<br>\n				The future of online battles instantly looks much brighter! With 6 days left and only about $350 short, we are so close! Help us go all the way!<br>\n				<br>\n				<div style="text-align: center;">\n					<span class="text large"><a href="https://www.kickstarter.com/projects/1976320862/tanktrouble-online-battles" target="_blank">Go to Kickstarter and help now</a></span>\n				</div>\n				<br>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					What is a Kickstarter?<br/>\n					A Kickstarter is a way to crowd-fund a project.	We will surrender all our time to develop online battles but we are going to need financial support, too. By supporting our Kickstarter campaign you can help. And you will get awesome rewards too!<br/>\n					Check out <a href="http://www.kickstarter.com">www.kickstarter.com</a>\n				</div></div></div>'),
('2015-03-19', 0, 'news4 mobile', 'TankTrouble Mobile App Updated', '<a name="19-03-2015" id="19-03-2015"></a><div class="news4 mobile" style=""><div>\n						TankTrouble Mobile App Updated\n						<div>\n							19-03-2015\n						</div>\n					</div><div>This latest update adds a news menu so that you can keep up to date with all the latest from our secret, underground laboratory. It also incorporates a completely new rendering engine and some minor bug fixes, to allow for uninterrupted chaos and destruction.<br>\n				<br>\n				<a href="https://itunes.apple.com/app/tanktrouble-mobile-mayhem/id951971414?ls=1&mt=8" target="_blank"><img src="images/availableOnTheAppStore120.jpg"/></a>&nbsp;&nbsp;<a href="https://play.google.com/store/apps/details?id=com.subterraneansoftware.tanktrouble.android" target="_blank"><img src="images/getItOnGooglePlay.png"/></a></div></div>'),
('2015-03-23', 0, 'news4 kickstarter', 'Kickstarter Reaches 100% Funding', '<a name="23-03-2015" id="23-03-2015"></a><div class="news4 kickstarter" style=""><div>\n						Kickstarter Reaches 100% Funding\n						<div>\n							23-03-2015\n						</div>\n					</div><div>Saturday night the Kickstarter reached 100% funding. The entire underground laboratory is in the clouds, rapturous with joy. Now all the scientists are itching to commence the work.<br>\n				<br>\n		 		A big thank-you goes out to all of you dedicated TankTroublers who have helped us get this far! And if YOU haven\'t got the exclusive Kickstarter accessories yet yourself, fear not! There\'s still time:<br>\n				<div style="text-align: center;">\n					<span class="text large"><a href="https://www.kickstarter.com/projects/1976320862/tanktrouble-online-battles" target="_blank">Hurry up to Kickstarter</a></span>\n				</div></div></div>'),
('2015-03-25', 0, 'news4 kickstarter', 'Kickstarter Funded', '<a name="25-03-2015" id="25-03-2015"></a><div class="news4 kickstarter" style=""><div>\n						Kickstarter Funded\n						<div>\n							25-03-2015\n						</div>\n					</div><div>Although we underground scientists are usually too busy to celebrate, this special day called for an exception. All scientists gathered in the stolovaya where the laboratory master chef had prepared some nasty musk ox snacks. Also, the intern had found a box of party hats. At 1200 hours, the Kickstarter was officially funded and the scientists could no longer contain themselves. They burst into spontaneous polka dancing and singing:<br>\n				<br>\n				<div style="text-align: center; font-style: italic;">\n					&#9835; - O\' Lab rats fear not gettin\' sacked &#9834;<br>\n					The online battles Kickstarter just got backed!<br>\n					&#9834; There\'s lots of explosions, work and mishaps ahead<br>\n					Online battles will be the best thing after sliced bread &#9835; &#9834;<br>\n					<br>\n					&#9834; - We are forever grateful to our amazing fans<br>\n					And will now live of expired musk ox milk from cans &#9834; &#9835;<br>\n					&#9834; Until we bring online destruction to the globe<br>\n					&#9834; &#9835; And fulfill all of our shared dreams and hope &#9834; &#9834; &#9835; &#9834;<br>\n				</div>\n				<br>\n				From the bottom of our warm fuzzy hearts we are deeply thankful for your unwavering support. We can\'t wait to get started!</div></div>'),
('2015-04-10', 0, 'news4 standard', 'Online Development Status Report', '<a name="10-04-2015" id="10-04-2015"></a><div class="news4 standard" style=""><div>\n						Online Development Status Report\n						<div>\n							10-04-2015\n						</div>\n					</div><div>It\'s been 10 days since we commenced the full-time development of TankTrouble online battles. And we have made progress and lots of it: We are now conducting smooth test battles on a far-away, remote server. We have ironed out almost all lag and we will continue to make it even smoother. Next up we will build the new user interface. We are on schedule!<br>\n				<br>\n				<div class="text large" style="text-align: center;">\n					BETA ACCESS: End of April &nbsp;&bull;&nbsp; ONLINE UNLEASH: June\n				</div></div></div>'),
('2015-04-13', 0, 'news4 kickstarter', 'Kickstarter Rewards Shipping', '<a name="13-04-2015" id="13-04-2015"></a><div class="news4 kickstarter" style=""><div>\n						Kickstarter Rewards Shipping\n						<div>\n							13-04-2015\n						</div>\n					</div><div>We have recieved test samples of all the Kickstarter rewards and they just look awesome! So we started shipping the mugs, T-shirts and hoodies today. If you pledged for any of those you can start watching out for the mail man - sweet swag is coming your way!<br>\n				<img src="images/KickstarterPhysicalRewards.png" style="position: relative; bottom: -10px; left: 30px;"></div></div>'),
('2015-05-07', 0, 'news4 standard', 'Online Development Status Report', '<a name="07-05-2015" id="07-05-2015"></a><div class="news4 standard" style=""><div>\n						Online Development Status Report\n						<div>\n							07-05-2015\n						</div>\n					</div><div>It comes as no surprise that the online beast is a hard one to rein. Combined with our, TankTrouble Laboratories\', never failing optimism when it comes to posing deadlines it has put us slightly behind schedule. We still struggle to weed out a few hard to catch bugs but we are getting excitingly close to unleash BETA.<br>\n				<br>\n				<div class="text large" style="text-align: center;">\n					BETA ACCESS: Just around the corner &nbsp;&bull;&nbsp; ONLINE UNLEASH: June\n				</div>\n				<br>\n				We get daily requests from players that missed the Kickstarter campaign for another way to get hold of those great rewards. Fear not! We are setting up a soon-to-be-announced shop for latecomers.</div></div>'),
('2015-05-15', 0, 'news4 kickstarter', 'Kickstarter Latecomers\' Shop Opening Soon', '<a name="15-05-2015" id="15-05-2015"></a><div class="news4 kickstarter" style=""><div>\n						Kickstarter Latecomers\' Shop Opening Soon\n						<div>\n							15-05-2015\n						</div>\n					</div><div>Latecomers to the TankTrouble Kickstarter have been pleading with us to make the rewards available again. Therefore, as promised, we are launching a latecomers\' shop. All support for the development of online battles is highly appreciated and we are only happy to satisfy merchandise craving tank owners. The shop will be opening soon!<br>\n        		<br>\n				If you don\'t know what the TankTrouble Kickstarter is all about you can find out <a href="https://www.kickstarter.com/projects/1976320862/tanktrouble-online-battles" target="_blank">here</a>. Remember, the Kickstarter has ended! If you want to get your hands on any of the sweet rewards you must wait for the shop to open.</div></div>'),
('2015-05-22', 0, 'news4 standard', 'Online Development Status Report', '<a name="22-05-2015" id="22-05-2015"></a><div class="news4 standard" style=""><div>\n						Online Development Status Report\n						<div>\n							22-05-2015\n						</div>\n					</div><div>Since the last status update we have been exterminating server bugs. Now the server is ready and eager to be swarmed by a horde of brave beta testers. However, we are still working on a few incomplete and essential features for the game lobby. Like e.g. letting tanks join battles and create new battles.<br>\n				<br>\n				As we missed our optimistic deadline once already, we won\'t venture to proclaim a new unleash date. Instead we ask you only to arm yourself with a little patience (although we\'ll be the first to admit how hard that is!).<br>\n				<br>\n				<div class="text large" style="text-align: center;">\n					BETA is imminent - keep a weather eye on the news!\n				</div></div></div>'),
('2015-07-08', 0, 'news4 standard', 'Online BETA Launches Friday at 1100 hours UTC', '<a name="08-07-2015" id="08-07-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Launches Friday at 1100 hours UTC\n						<div>\n							08-07-2015\n						</div>\n					</div><div>Ever since we blew our optimistic deadline for Online BETA in the end of April we have been swatting enough bugs to make the 8th plague of Egypt look like a picnic. While we regret this delay, we are excited to announce that we finally got the better of them.<br>\n				<br>\n				<div class="text large" style="text-align: center;">\n					Online BETA will launch this Friday at 1100 hours UTC!\n				</div>\n				<br>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					Important note: We need to carefully gauge the number of online players while the servers are young in order to not crash them. Therefore, only players who pledged for beta access during the TankTrouble Kickstarter campaign will have access at this time.\n				</div></div></div>'),
('2015-07-09', 0, 'news4 standard', 'Everything You Need to Know About Online BETA', '<a name="09-07-2015" id="09-07-2015"></a><div class="news4 standard" style=""><div>\n						Everything You Need to Know About Online BETA\n						<div>\n							09-07-2015\n						</div>\n					</div><div>Online BETA is "just" the first, early test of TankTrouble Online. Many features are still in development and brave beta testers are expected to encounter oddities as they daringly venture into online mazes to help locate bugs and suggest improvements. Therefore, we need to carefully gauge the number of beta players to avoid crashing the servers while we are still developing. Consequently, only players who pledged for beta access during the Kickstarter campaign will have access ...for now!<br>\n				<br>\n				Players who missed the Kickstarter but simply must have beta access, fear not! You will be able to purchase access in the soon-to-open Kickstarter Latecomers\' Shop.<br>\n				<br>\n				When we are ready to release TankTrouble Online, everyone will have access.<br>\n				<br>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					<div class="text large" style="text-align: center;">\n						Online BETA features\n					</div>\n					<br>\n					Tomorrow:\n					<ul>\n						<li>Online Battles - sweet bananas!</li>\n						<li>Servers in USA, Europe and East Asia</li>\n						<li>In-game chat system - shoot first, chat later</li>\n						<li>New improved tank design prepped for accessories extravaganza</li>\n						<li>A groovy TankTrouble tune straight from the depths of the Siberian underground</li>\n					</ul>\n					In development:\n					<ul>\n						<li>Developers\' forum for beta players</li>\n						<li>Tankcessories (including the exclusive Beta accessory box)</li>\n						<li>Mobile and tablet support</li>\n						<li>Multiplayer on the same computer</li>\n						<li>New score and experience system</li>\n					</ul>\n					Not forgotten but postponed for now:\n					<ul>\n						<li>Weapons (all weapons need to be rebuilt from scratch and we will do that in time - for now smooth online battles is our highest priority)</li>\n						<li>Laika - the beloved and infamous space dog</li>\n					</ul>\n				</div></div></div>'),
('2015-07-10', 0, 'news4 standard', 'Online BETA Opened', '<a name="10-07-2015" id="10-07-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Opened\n						<div>\n							10-07-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Today is an important milestone in the development of TankTrouble Online (and in the history of destruction in general) as we open Online BETA to the brave beta testers. We would never have made it this far without your encouraging support and unwavering enthusiasm. The Laboratory pays you homage.<br>\n				<br>\n				As the unsullied, untested servers have never seen real combat and are oblivious to the unrivalled destruction about to descend on them, we must vigilantly ease them into battle. That is why only a small party of beta testers can access ...for now!<br>\n				<br>\n				Non-believers, infidels and impatient tank owners, rest assured! There are no flying pigs in the Laboratory and though it is cold in the Siberian underground it has not yet frozen! Nonetheless, Online BETA is open!<br>\n				<br>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					Important note: Only players who pledged for beta access during the TankTrouble Kickstarter campaign can access g. Players who missed the Kickstarter will be able to purchase access in the soon-to-open Kickstarter Latecomers\' Shop.\n				</div></div></div>'),
('2015-07-17', 0, 'news4 standard', 'First Week of Online BETA Recapped', '<a name="17-07-2015" id="17-07-2015"></a><div class="news4 standard" style=""><div>\n						First Week of Online BETA Recapped\n						<div>\n							17-07-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">The Online BETA servers have survived their first week in actual combat. Brave beta testers from around the world and scientists from the Siberian underground have butted barrels in online mazes for the first time. Battles have run largely untroubled with only spasmodic lag. Though there\'s still lots of room for improvements it has already proven to be good, solid fun!<br>\n				<br>\n				The scrupulous party of beta testers have searched nooks and crannies for bugs, and while they have added some oddities to the list, they have not been able to crash the servers. Not even once! In fact, it has been a very smooth BETA release (TankTrouble history considering) and we will soon be ready to onboard more beta testers. If you are interested, keep a weather eye on the Kickstarter Latecomers\' Shop.<br>\n				<br>\n				In the coming week the Laboratory will mainly work on performance improvements.</div></div>'),
('2015-07-18', 0, 'news4 kickstarter', 'Kickstarter Latecomers\' Shop Opens', '<a name="18-07-2015" id="18-07-2015"></a><div class="news4 kickstarter" style="position: relative; margin-top: 105px;"><div>\n						Kickstarter Latecomers\' Shop Opens\n						<div>\n							18-07-2015\n						</div>\n					</div><div><img src="images/shopOpens.png" style="position: absolute; left: 250px; top: -135px;"/>Players who were late to the TankTrouble Kickstarter campaign, who crave the great rewards that were offered, and who want to support the development of TankTrouble Online, behold! In the Laboratory\'s new shop you can get BETA access, tank swag, cool wearables and more! And, the selection will grow concurrently with the continuous development of TankTrouble Online. <a href="?shop">Browse now!</a></div></div>'),
('2015-07-21', 0, 'news4 standard', 'TankTrouble Online Delayed', '<a name="21-07-2015" id="21-07-2015"></a><div class="news4 standard" style=""><div>\n						TankTrouble Online Delayed\n						<div>\n							21-07-2015\n						</div>\n					</div><div>It should come as no surprise that we will not be ready to unleash TankTrouble Online in June as originally announced...umm, eh, especially since we are now in July. Whichever scientist said June must have had his turret on backwards.<br>\n				<br>\n				Although Online BETA is looking good and many improvements have already been deployed there is still a great deal of work to be done. Scientists are therefore hesitant to announce a final release date just yet.<br>\n				<br>\n				Although tank owners have very little patience in regards to destruction we thank you for whatever little you may have.</div></div>'),
('2015-07-28', 0, 'news4 standard', 'Online BETA Development Report', '<a name="28-07-2015" id="28-07-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Development Report\n						<div>\n							28-07-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Resting on laurels is not on the Laboratory\'s to-do list so last week we soldiered on with performance improvements. This morning we deployed some serious ones along with a bunch of new features.<br>\n				<br>\n				Performance improvements:\n				<ul>\n					<li>Major graphics rendering optimisation</li>\n					<li>Major memory usage optimisation</li>\n				</ul>\n				New features:\n				<ul>\n					<li>Tank names appear at battle start so you know who\'s who</li>\n					<li>Chat bubble appear in game when tanks chat</li>\n					<li>Improved username outline (now bright usernames are readable too)</li>\n					<li>Tweaked chat colours</li>\n					<li>Press Enter from the lobby to start chatting</li>\n					<li>Wall of Fame</li>\n				</ul></div></div>'),
('2015-09-14', 0, 'news standard', 'Tag Line Competition Goes Official', '<a name="14-09-2015" id="14-09-2015"></a>\n				<div class="news standard">\n					<div class="header">Tag Line Competition Goes Official\n						<div>\n							14-09-2015\n						</div>\n					</div>\n					<div class="content"><div id="poll-7-content" class="middle text small">An unofficial tag line competition has taken place on the forum and 3 finalists were picked. In the underground laboratory we think they hit the TankTrouble spirit bullseye. Now we want to make the best one official.<br/>&nbsp;<br/><div id="poll-7-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-7-closedSign" src="images/thisPollIsClosed.png"/></div>Which tag line do YOU like best?<br/><br/></div></div><table id="poll-7-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer150.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Home to tanks of weapons \'n\' wits, watch out - you\'ll be blown to bits!<br>(by Xuequinox) <span class="text tiny">(367 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The one kind of trouble you want to get into...<br>(by supervolcano) <span class="text tiny">(253 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 241.28065395095px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Head To head; in a world of wars; one can win \'n\' one can rule!<br>(by BallisticBlaster) <span class="text tiny">(113 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 107.76566757493px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2015-09-28', 0, 'news4 standard', 'TankTroublers Have Spoken - You\'ll Be Blown to Bits!', '<a name="28-09-2015" id="28-09-2015"></a><div class="news4 standard" style=""><div>\n						TankTroublers Have Spoken - You\'ll Be Blown to Bits!\n						<div>\n							28-09-2015\n						</div>\n					</div><div><div style="text-align: center;">\n					And the winner is...<br>\n					<br>\n					<span class="text large" style="font-style: italic;">Home to tanks of weapons \'n\' wits, watch out - you\'ll be blown to bits!</span>\n				</div>\n				<br>\n				Poetry of destruction and ear candy to TankTrouble scientists! We have added this rhyming tag line to the front page where it will randomly pop up.</div></div>'),
('2015-10-12', 0, 'news4 standard', 'What\'s Cooking in the Laboratory?', '<a name="12-10-2015" id="12-10-2015"></a><div class="news4 standard" style=""><div>\n						What\'s Cooking in the Laboratory?\n						<div>\n							12-10-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">The Laboratory has submerged deep into core components of the Online BETA servers. We have been doing lots of cleaning up of code and optimising, and the servers are now running as smooth as Dimitri\'s bald spot - almost (nothing\'s really that smooth). Besides loads of under-the-hood server optimisations, we did implement some groovy, new features. We especially like:\n				<ul>\n					<li>The Garage featuring - for starters - the BETA accessories!</li>\n					<li>Explosive scores that explode!</li>\n					<li>Groovy Terminator and Dominator badges that will command respect!</li>\n					<li>The good ol\' Scrapyard is back - now continuing the counting on Online BETA.</li>\n				</ul>\n				And we swatted bugs left and right. The most notorious were:\n				<ul>\n					<li>A nasty bug that caused your tank to sometimes appear twice.</li>\n					<li>The occasional appearance of mysterious black boxes.</li>\n				</ul></div></div>'),
('2015-10-22', 0, 'news4 standard', 'Online BETA Opens for All Players Next Weekend', '<a name="22-10-2015" id="22-10-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Opens for All Players Next Weekend\n						<div>\n							22-10-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Up until now, the Online BETA servers have only been exposed to a limited and exclusive group of BETA testers,\n				while TankTrouble scientists have been deploying improvements, fixing bugs and tweaking tweakable stuff.\n				Now it is time to see if the nuts and bolt have been tightened enough.<br>\n				<br>\n				<div style="text-align: center;" class="text large">\n					Next weekend<br>\n					- Friday Oct 30th to Sunday Nov 1st -<br>\n					we temporarily open Online BETA for all players!<br>\n					<br>\n				</div></div></div>'),
('2015-10-29', 0, 'news4 standard', 'Online BETA Weekend - What to Expect?', '<a name="29-10-2015" id="29-10-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Weekend - What to Expect?\n						<div>\n							29-10-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Before TankTrouble Online BETA opens temporarily this weekend, there are a few things to keep in mind.\n				<ul>\n					<li>\n						This BETA weekend is first and foremost a test. The online servers have only ever been exposed to a few BETA testers. Now we need to see how they perform under pressure. Most likely they will crash.\n					</li>\n					<li>\n						TankTrouble Online is in BETA; it is work in progress, not everything is implemented yet and bugs do occur!\n					</li>\n					<li>\n						To avoid a complete meltdown we have capped the number of simultaneously running battles on each server at 5, for starters. There will not be room for everyone.\n					</li>\n				</ul>\n				Scientists keep their fingers crossed, lab rats fear the worst, and the Intern says he will not touch anything. See you online!</div></div>'),
('2015-10-30', 0, 'news4 standard', 'Online BETA Weekend - Pressing the Big Red Button!', '<a name="30-10-2015" id="30-10-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Weekend - Pressing the Big Red Button!\n						<div>\n							30-10-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">The scientists have now temporarily opened Online BETA for all players! But beware: TankTrouble Online BETA is work in progress. Venturing into the glitchy bits and bytes of the Online BETA servers puts your tank at great risk. That\'s why we\'re handing out hazmat suits to everyone the entire weekend - log in now to claim yours! Keep your head down and expect things to blow up left and right!</div></div>'),
('2015-11-29', 0, 'news4 standard', 'Online BETA Development Report', '<a name="29-11-2015" id="29-11-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Development Report\n						<div>\n							29-11-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">The Online BETA Weekend panned out successfully. Brave testers from all over the planet battled fiercely while TankTrouble scientists monitored the server load intensely. The servers pulled through without breaking a sweat. However, the test did reveal a few ungreased gears and thus we remain submerged deep into the core of the online servers greasing up for the next big test. We expect to surface with more news soon!</div></div>'),
('2015-12-01', 0, 'news4 christmas', '25 Jolly Pieces of Swag to Keep You Warm', '<a name="01-12-2015" id="01-12-2015"></a><div class="news4 christmas" style=""><div>\n						25 Jolly Pieces of Swag to Keep You Warm\n						<div>\n							01-12-2015\n						</div>\n					</div><div>The Countdown has Begun! Now a hard month of chowing down frosted cookies and roller-coasting blood sugar levels lies ahead. To ease the process the TankTrouble Swag Research Team has prepared an Advent calendar with jolly Christmas accessories. Log in every day to collect them all or the ones you are missing!<br>\n				<br>\n				<span class="text tiny">Note to Santa: We are still waiting on that nuclear reactor!</span></div></div>'),
('2015-12-10', 0, 'news4 christmas', 'Christmas Swag Refitted for Online BETA', '<a name="10-12-2015" id="10-12-2015"></a><div class="news4 christmas" style=""><div>\n						Christmas Swag Refitted for Online BETA\n						<div>\n							10-12-2015\n						</div>\n					</div><div>Jolly Christmas spirit has found its way to Online BETA; The Swag Research Team has refitted all the Christmas accessories for the new tank design. That, and the Kickstarter accessories too!</div></div>'),
('2015-12-16', 0, 'news4 standard', 'TankTrouble Turns 8', '<a name="16-12-2015" id="16-12-2015"></a><div class="news4 standard" style=""><div>\n						TankTrouble Turns 8\n						<div>\n							16-12-2015\n						</div>\n					</div><div>A long time ago, in Siberia far, far away... a secret laboratory hidden deep underground awakened an old, top secret USSR cold war project codenamed TankTrouble (Read the unofficial true story of how it all started <a href="#16-12-2007">here</a>).<br>\n				<br>\n				Since then the USSR government has launched countless attempts to locate and obliterate the laboratory; we have had enough scientific disasters to level the laboratory ourselves on numerous occasions; and we have survived the master chef\'s musk ox snacks. Yet, we persevered with development and today, exactly 8 years later, we celebrate TankTrouble\'s 8th anniversary.<br>\n				<br>\n				So to everyone who have joined us on our journey (so far); we couldn\'t have done it without you and we are humbled by your loyalty. THANK YOU!</div></div>'),
('2015-12-18', 0, 'news4 standard', 'Online BETA Development Report', '<a name="18-12-2015" id="18-12-2015"></a><div class="news4 standard" style=""><div>\n						Online BETA Development Report\n						<div>\n							18-12-2015\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">The laboratory have been eavesdropping on the battling BETA testers and this week we have completed some much-coveted improvements. The servers were just restarted and the improvements are operative. Most noteworthy:<br>\n				<ul>\n					<li>Kicking of inactive players: Hang around in the chat, on the forum or at your granny\'s - the mazes are for battles. Players that have been inactive for more than 1 minute will now automatically get the boot.</li>\n					<li>Minimum spawn distance: No more cheap, backstabbing turbo kills! Tanks now spawn at a minimum driving distance of four tiles.</li>\n					<li>Top-notch maze generation: Take advantage of the full maze with a new, state-of-the-art maze generation process that makes sure there are no unreachable areas.</li>\n					<li>Teleport bug exterminated: We located and whacked the bug that caused tanks to occasionally teleport.</li>\n				</ul>\n				If you experience problems try emptying your browser\'s cache before calling in the cavalry. See you on Online BETA!</div></div>'),
('2015-12-25', 0, 'news4 christmas', 'Christmas Greetings from Siberia', '<a name="25-12-2015" id="25-12-2015"></a><div class="news4 christmas" style=""><div>\n						Christmas Greetings from Siberia\n						<div>\n							25-12-2015\n						</div>\n					</div><div>We hope your Christmas tree is oozing merriness and teeming with explosive gifts. As we ourselves are short on trees here in the Siberian badlands we decorated an old, left-over Cold War missile instead; wrapped it in glittery garlands and mounted a star on the tip of the warhead. All things considered, it looks good and provides a jolly Christmas atmosphere. Also, the stage one rocket booster will be perfect for preparing the turkey.<br>\n				<br>\n				We wish you all a merry Christmas.<br>\n				<br>\n				<span class="text tiny">Note to Santa: We suggest you have a word with your subcontracting courier service as it seems they have neglected Siberia once again this year. Most disappointing!</span></div></div>'),
('2016-01-01', 0, 'news4 standard', 'Christmas Tree Lights Up Siberian Sky', '<a name="01-01-2016" id="01-01-2016"></a><div class="news4 standard" style=""><div>\n						Christmas Tree Lights Up Siberian Sky\n						<div>\n							01-01-2016\n						</div>\n					</div><div>At 2400 hours we launched the old, left-over Cold-War missile that we used for our Christmas tree. For a little while the gloomy Siberian sky was lit up by fragments of glittering baubles and sparkling tinsels during which we took a moment to recap the bygone year.<br>\n				<br>\n				In April 2015 we kicked off the development of TankTrouble Online. On July 10th, after months of hard work, we were ready to launch a test version: Online BETA. Then TankTrouble scientists were joined by the team of BETA testers. They bravely ventured into unknown mazes of online destruction and commenced relentless testing and bug reporting, while the scientists installed improvements and continued the development. However, bringing destruction online turned out to be a much bigger endeavour than we anticipated and launch has been postponed for now.<br>\n				<br>\n				So when will TankTrouble Online launch? The short answer is, we do not dare to guess but there is only one thing on the plate for 2016 and we will work our socks off to get there: Unleash TankTrouble Online!<br>\n				<br>\n				From the underground in Siberia we wish you all a very happy New Year!</div></div>'),
('2016-01-07', 0, 'news4 standard', 'TankTrouble Online and Online BETA Explained', '<a name="07-01-2016" id="07-01-2016"></a><div class="news4 standard" style=""><div>\n						TankTrouble Online and Online BETA Explained\n						<div>\n							07-01-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">In <span style="font-weight: bold">TankTrouble Online</span> players from all over the world will be able to meet in epic, online battles. It is currently in development so you cannot play online just yet. The laboratory is working their socks off but no release date has been set. TankTrouble Online will be FREE!<br>\n				<br>\n				<span style="font-weight: bold">Online BETA</span> is a test version of TankTrouble Online. We have allowed a few players to access this test version. They are called BETA Testers. As we develop new stuff, like weapons and such, we take it for a test-drive on <a href="//beta.tanktrouble.com" target="_blank">beta.tanktrouble.com</a>. Here BETA Testers help the developers test the new stuff and find bugs before it is released to everyone. If you wish to join the BETA Club, you can purchase membership in the <a href="?shop">shop</a>.</div></div>'),
('2016-01-29', 0, 'news4 standard', 'Win a BETA Membership', '<a name="29-01-2016" id="29-01-2016"></a><div class="news4 standard" style=""><div>\n						Win a BETA Membership\n						<div>\n							29-01-2016\n						</div>\n					</div><div>The development of Online BETA is progressing as planned and now we need more testers. On Friday (February 5th) we draw 10 lucky winners of a TankTrouble BETA Membership.<br>\n				<br>\n				See how you enter the competition on <a href="https://www.facebook.com/TankTrouble/posts/1129917583697685">Facebook</a>.</div></div>'),
('2016-02-04', 0, 'news4 attention', 'Scientists Re-invent Laser for Online BETA', '<a name="04-02-2016" id="04-02-2016"></a><div class="news4 attention" style=""><div>\n						Scientists Re-invent Laser for Online BETA\n						<div>\n							04-02-2016\n						</div>\n					</div><div>The weapons division has been working on a laser for Online BETA. For test purposes a specially designed mirror dome was built and the Intern was tasked with polishing the hundreds of mirrors. Now, this morning, after months of development and polishing, lead weapons scientist Dimitri discharged the laser and observed, from behind his safety goggles, the beam bounce to perfection.<br>\n				<br>\n				Unfortunately, this left the dome smudged in soot and with the prospect of waiting months for the Intern to polish the mirrors again, we have decided to skip further testing and release the laser without further ado and fingers crossed.<br>\n				<br>\n				Go to Online BETA now and discharge a laser today!</div></div>'),
('2016-02-05', 0, 'news4 standard', 'Mirror Dome Mishap Ensures Fair Competition', '<a name="05-02-2016" id="05-02-2016"></a><div class="news4 standard" style=""><div>\n						Mirror Dome Mishap Ensures Fair Competition\n						<div>\n							05-02-2016\n						</div>\n					</div><div>Moments before the test of the laser yesterday, the Intern had returned to the mirror dome to retrieve his transistor radio that had kept him company during the long, lonely and tedious months of polishing. Unaware of the presence of living tissue in the test dome, lead weapons scientist Dimitri discharged the laser just as the Intern was folding up the antenna - a most unfortunate timing.<br>\n				<br>\n				The condition of the transistor radio is critical but stable. The antenna looks like marshmallow struck by lightning and the circuit board resembles a post-apocalyptic pizza. It is doubtful that it will ever be able to pick up another FM frequency. On the bright side the batteries won\'t need recharging this millennium.<br>\n				<br>\n				The Intern is okay. Mostly. He has temporarily lost his eyesight.<br>\n				<br>\n				However, we will make the most of the unfortunate situation and have him draw the winners of the BETA Membership competition thereby avoiding any speculation that they were not drawn completely randomly.<br>\n				<br>\n				<span class="text large">We draw the winners of the BETA Membership this evening. They will be contacted on Facebook and once we have their TankTrouble usernames the lucky winners will be officially announced.</span><br>\n				<br>\n				If you haven\'t joined the competition yet, hurry up to <a href="https://www.facebook.com/TankTrouble/posts/1129917583697685">Facebook</a> now! You can still make it! Good luck everyone.</div></div>'),
('2016-02-08', 0, 'news4 standard', 'BETA Membership Winners Announced', '<a name="08-02-2016" id="08-02-2016"></a><div class="news4 standard" style=""><div>\n						BETA Membership Winners Announced\n						<div>\n							08-02-2016\n						</div>\n					</div><div>Scientists are thrilled to see so many players show interest for Online BETA and decided to increase the prizes and give away 25 BETA Memberships. The Intern randomly picked the lucky winners. Congratulations:<br>\n				<br>\n				<div style="text-align: center;" class="text large">\n					TechnoRazor, sefu9090, mikeel, KD7, MixuQ, royalty37, Pokololoa, deadshoter, bloonblaster, 123aco, PinoyKami, 7777lSamVTA, sheroz12, BrannocZombie, snowmanhill1, KG_Steve, RoadOfFury, domo12, horsehead123, bl4ckf4lc0n62, mainmanj, Killraa, MISSAEL21, Texanoo and wwm0nkey\n				</div></div></div>'),
('2016-03-11', 0, 'news4 important', 'Important Message to Tank Owners', '<a name="11-03-2016" id="11-03-2016"></a><div class="news4 important" style=""><div>\n						Important Message to Tank Owners\n						<div>\n							11-03-2016\n						</div>\n					</div><div>Do you have 2 tanks or more? If yes, then you must read this:<br>\n				<br>\n				From May 1st TankTrouble will allow only 1 tank per email address. If you have 2 or more tanks using the same email address, you must change the duplicate addresses now! Here\'s how:<br>\n				<div style="text-align: center;">\n					<img src="images/changeEmailInstructions.png">\n				</div>\n				<br>\n				The details: On May 1st all duplicate email addresses will be deleted. That is, if you have 2 or more tanks that are using the same email address, only the tank that most recently logged in will keep its email address; the other tanks\' email addresses will be deleted. No accounts will be deleted. You will still be able to log in with all your accounts even if their email was deleted, but if you forget their passwords there will be no way to retrieve them.</div></div>'),
('2016-03-21', 0, 'news standard', 'Officially Unofficial TankTrouble Tag Poll', '<a name="21-03-2016" id="21-03-2016"></a>\n				<div class="news standard">\n					<div class="header">Officially Unofficial TankTrouble Tag Poll\n						<div>\n							21-03-2016\n						</div>\n					</div>\n					<div class="content"><div id="poll-8-content" class="middle text small">Again this year, another, unofficial tag competition was held in the forum. Maybe it is becoming a tradition? We don\'t know, but we scientists just love that kind of initiative so we have decided to honour the best one this year too!<br/>&nbsp;<br/><div id="poll-8-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-8-closedSign" src="images/thisPollIsClosed.png"/></div>What should be the next, official TankTrouble tag?<br/><br/></div></div><table id="poll-8-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer250.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Chalk up some kills, improve your skills<br>(by Firestorm16) <span class="text tiny">(978 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Fire your rounds, watch bullets fly; demolition nears, and the time draws nigh!<br>(by Xuequinox) <span class="text tiny">(284 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 101.63599182004px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											A tank game more addictive than coffee in the morning<br>(by peopleoftheworld) <span class="text tiny">(256 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 91.61554192229px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Shoot around bends and battle your friends in this fight to the death;<br>don\'t lose your breath! (by superbattlefury) <span class="text tiny">(191 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 68.353783231084px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											There\'s one thing that never changes in TankTrouble and that\'s awesomeness!<br>(by shockwave44) <span class="text tiny">(222 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 79.447852760736px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2016-03-29', 0, 'news4 standard', 'TankTroublers Have Spoken - Kills Rhymes with Skills!', '<a name="29-03-2016" id="29-03-2016"></a><div class="news4 standard" style=""><div>\n						TankTroublers Have Spoken - Kills Rhymes with Skills!\n						<div>\n							29-03-2016\n						</div>\n					</div><div><div style="text-align: center;">\n					And the winner is Firestorm16 with...<br>\n					<br>\n					<span class="text large" style="font-style: italic;">Chalk up some kills, improve your skills</span>\n				</div>\n				<br>\n                The underground laboratory is proud to have been the source of inspiration for these poetic words. We have added the tag to the front page where it will randomly pop up.</div></div>'),
('2016-04-15', 0, 'news4 standard', 'Help Redecorate the Cantina - TankTrouble Poster Competition', '<a name="15-04-2016" id="15-04-2016"></a><div class="news4 standard" style=""><div>\n						Help Redecorate the Cantina - TankTrouble Poster Competition\n						<div>\n							15-04-2016\n						</div>\n					</div><div><span class="text small">After a scavenge team returned from remote sections of the vast, unexplored underground complex with a fancy, French cookbook, the laboratory\'s master chef decided to branch off his field of expertise - cabbage and borscht - to explore the delights of French cuisine. Inexperienced in the exquisite art of flamb&eacute;ing pancakes, he borrowed Dimitri\'s latest prototype; the Fahrenheit 666 rocket fuelled flamethrower, which had never been tested for small-cantina-use. After an impressive display of fiery mayhem that would have made even the most hardened pyrotechnician wet his bed, the cantina and everything in it was left pretty crispy. It will probably be a while before the master chef ventures away from Soviet evergreens again. Especially considering how hard it is to flip pancakes in a full body cast. But let\'s get to the point:</span><br>\n                <br>\n                <div style="text-align: center;">\n				    <span class="text large">We need your help to redecorate the walls in the cantina with awesome TankTrouble propoganda posters!</span>\n                </div>\n                <br>\n                Draw, create and make the coolest TankTrouble poster you can imagine.<br>\n                It can picture anything you like about TankTrouble!<br>\n                It can be any size you prefer.<br>\n                <br>\n                Email your TankTrouble poster to <a style="vertical-align: top;" href="mailto:laboratory@tanktrouble.com?subject=TankTrouble%20Poster%20Competition">laboratory@tanktrouble.com</a> or send it to:&nbsp;\n                <div style="display:inline-block; position: absolute;">\n                TankTrouble<br>\n                Mejlgade 43A<br>\n                8000 Aarhus<br>\n                Denmark<br>\n                </div>\n                <br><br>\n				<div style="text-align: center;">\n                    <img src="images/posterCompetitionPrizes.png"/>\n                </div>\n                We must have your submission by <span style="font-weight: bold">Thursday the 12th of May</span> where the Scientists will pick the 3 most awesome posters. Great prizes are at stake!</div></div>'),
('2016-04-25', 0, 'news4 standard', 'Poster Competition Follow-up', '<a name="25-04-2016" id="25-04-2016"></a><div class="news4 standard" style=""><div>\n						Poster Competition Follow-up\n						<div>\n							25-04-2016\n						</div>\n					</div><div>Submissions for the poster competition are already starting to tick into the laboratory\'s mailbox, and the Intern is preoccupied printing them and hanging them up. The cantina is starting to look great! We want to cover the whole cantina with posters, so if you haven\'t submitted one yet, here\'s some ideas to get you started:<br>\n				<br>\n				A poster with your tank battling in the mazes... scientists working... Dimitri inventing a new weapon... the Scrapyard Scientist on vacation... dangers in the unexplored, secret corridors of the underground laboratory... Laika in action... the Intern in an accident about to happen... cunning lab rats in the test facility...<br>\n				<br>\n				You can draw your poster by hand, design it on a computer, or both, and you may mix in graphics from TankTrouble.com if you like. And if you have already submitted one poster, don\'t let that stop you - you can submit as many posters as you like!<br>\n				<br>\n				There\'s still plenty of time, but remember: We must have your poster by the <span style="font-weight: bold">12th of May</span> at the latest! Read all the details and check out the great prizes in the news below.</div></div>'),
('2016-04-29', 0, 'news4 important', 'Last Call for Changing Duplicate Emails', '<a name="29-04-2016" id="29-04-2016"></a><div class="news4 important" style=""><div>\n						Last Call for Changing Duplicate Emails\n						<div>\n							29-04-2016\n						</div>\n					</div><div><br>\n				<div class="text large" style="text-align: center;">Important message for tanks owners with more than one tank:</div><br>\n				On May 1st we will unregister all duplicate email addresses. If you have two or more tanks using the same email, you should log in with all your tanks now, and make sure they use different emails - <a href="#11-03-2016">here\'s how</a>.<br>\n				<br>\n				Q: What happens if I do nothing?<br>\n				<span class="text gray">A: If you have more tanks using the same email, we will unregister all emails except on the tank that was most recently logged in.</span><br>\n				<br>\n				Q: Will you delete tanks?<br>\n				<span class="text gray">A: No. And you will still be able log in even if the email was unregistered.</span><br>\n				<br>\n				Q: So why bother changing the email?<br>\n				<span class="text gray">A: Because if you forget your password and don\'t have an email registered, the tank is lost forever - not even the scientists can help you!</span><br>\n				<br>\n				Q: How fast can a T-Rex say hotdog?<br>\n				<span class="text gray">A: Good question but that\'s off-topic.</span></div></div>'),
('2016-05-11', 0, 'news4 standard', 'Poster Competition Deadline Approaching', '<a name="11-05-2016" id="11-05-2016"></a><div class="news4 standard" style=""><div>\n						Poster Competition Deadline Approaching\n						<div>\n							11-05-2016\n						</div>\n					</div><div>On Friday the scientists will have a rare break, which we will spend in the cantina studying the submissions for the poster competition and voting for the best ones. If you haven\'t sent us your poster yet, hurry up - you can still make it! <b>Tomorrow, Thursday the 12th of May</b>, is the last chance!<br>\n				<br>\n				Read all about the competition and the great prizes <a href="#15-04-2016">here</a>.</div></div>'),
('2016-05-13', 0, 'news4 standard', 'Poster Competition Winners Found', '<a name="13-05-2016" id="13-05-2016"></a><div class="news4 standard" style=""><div>\n						Poster Competition Winners Found\n						<div>\n							13-05-2016\n						</div>\n					</div><div>\n\n		At noon all scientists were summoned in the cantina to find the winners of the poster competition. With many great posters to choose from it was a difficult task, but after hours of voting the scientists came to a decision. The winners are:<br>\n		<br>\n		<div style="text-align: center">\n			<img src="images/posterCompetition1st.png"><br>\n			- O\' Siberia, home of the secret underground laboratory,<br>\n			1st prize goes to Texanoo<br>\n			<br>\n\n			<img src="images/posterCompetition2nd.png">\n			- Laika looks like she needs major service,<br>\n			2nd prize goes to dragonstorm3000<br>\n			<br>\n\n			<img src="images/posterCompetition3rd.png"><br>\n			- Laika gives you the evil stare,<br>\n			3rd prize goes to rattlesniper<br>\n		</div>\n		<br>\n		Congratulations to the winners and a big thanks to everyone who sent us their posters. The underground cantina looks much better now.</div></div>'),
('2016-05-25', 0, 'news4 standard', 'Online BETA Development Report', '<a name="25-05-2016" id="25-05-2016"></a><div class="news4 standard" style=""><div>\n						Online BETA Development Report\n						<div>\n							25-05-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Scientists have deployed extensive updates to Online BETA - from the frontier of the mazes to the core systems in the engine room - to accommodate fundamental changes to the player connection system. The new key features are:<br>\n				<br>\n				<b>Up to 3 players on the same computer</b> - just like on the regular site, but now in online battles!<br>\n				<br>\n				<b>Guest players</b> - if your friends do not have BETA access they can join you anyway on the same computer.<br>\n				<br>\n				Numerous other updates have been installed too; like in-game garage access with instant tank updating, a weapons stack display, a custom TankTrouble font, and a completely redesigned sign-up process. That, and many more goodies are now ready for testing on <a href="https://beta.tanktrouble.com">TankTrouble Online BETA</a>.</div></div>'),
('2016-06-03', 0, 'news4 standard', 'Online BETA Update', '<a name="03-06-2016" id="03-06-2016"></a><div class="news4 standard" style=""><div>\n						Online BETA Update\n						<div>\n							03-06-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Scientists have swatted the notorious control bug, that consumed Qs in the chat and caused controls to switch from arrow keys to WASD.<br>\n				<br>\n				Tanks have also been rearranged so that all player names are visible in even the most crowded mazes.</div></div>'),
('2016-06-10', 0, 'news4 standard', 'Scavenger Team Recovers Fabled Machine', '<a name="10-06-2016" id="10-06-2016"></a><div class="news4 standard" style=""><div>\n						Scavenger Team Recovers Fabled Machine\n						<div>\n							10-06-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;"><img style="float: right; margin: 18px;" src="images/timeMagazine1963.png">\n				In the early 60s, in the midst of the Space Race, confidential intel reported that the Soviets had built a computer that would change the world order: the Randomizer-3000. A single photo was leaked but it was never confirmed that it was in fact the fabled machine, and hence the story faded into history and became no more than a myth. Until now... <br>\n				<br>\n				On a two-day mission to the outer sections of the vast, unexplored, underground laboratory, the scavenger team came across a rusty blast door. Using Dimitri\'s Fahrenheit 666 rocket fuelled flamethrower (recently tested in the Cantina) they quickly gained access. The dim light from the glowing remains of the door revealed an empty room except for one dusty object placed in the centre. The team hit the lightswitch and in the flickering light from a single fluorescent tube, they realised what they had found: The Randomizer-3000. The legend was real!<br>\n				<br>\n				Back in the main quarters, scientists powered up the machine. It turns out that all it does is random calculations. No wonder the Soviets scrapped it. Anyway, we hooked it up to Online BETA and new users can now enjoy its unsurpassed wits when in need of a tank name.</div></div>'),
('2016-07-26', 0, 'news4 standard', 'Open BETA is Imminent', '<a name="26-07-2016" id="26-07-2016"></a><div class="news4 standard" style=""><div>\n						Open BETA is Imminent\n						<div>\n							26-07-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Scientists claim to have glimpsed the bottom of the never-ending to-do list for Open BETA. They speculate the end is near, and reckon Open BETA is imminent. Sales of BETA Memberships have been suspended. Stay posted!<br>\n				<br>\n				If you are lucky enough to have a BETA Membership you will keep it - it\'s yours for life. When TankTrouble Online is released the BETA site will close again, only open for BETA Members to test the scientists\' newest inventions as development goes on.<br>\n  			  	<br>\n				<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n					<b>What is Open BETA?</b><br>\n					TankTrouble Online is being developed and tested on a special BETA site. The BETA site is normally for BETA Members only. Now the development is reaching its final stage, and scientists believe it is safe to open BETA up for everyone - that is OPEN BETA.\n				</div></div></div>'),
('2016-09-15', 0, 'news4 standard', '2 Billion Scraps But No Party Hats', '<a name="15-09-2016" id="15-09-2016"></a><div class="news4 standard" style=""><div>\n						2 Billion Scraps But No Party Hats\n						<div>\n							15-09-2016\n						</div>\n					</div><div>While lunching the cantina\'s indistinguishably, grey grub of the day, the Scrapyard Scientist appeared on the intercom. He cleared his throat and solemnly announced that the Scrapyard had passed 2 billion scraps.<br>\n							<br>\n							Normally this would call for celebration, perhaps even party hats, but all scientists are preoccupied with the imminent release of OPEN BETA. Instead scientists gave each other awkward scientist-hugs and assumed the grub shoving.<br>\n							<br>\n							OPEN BETA is right around the corner - we will celebrate then!</div></div>'),
('2016-10-03', 0, 'news4 standard', 'OPEN BETA Launch Thursday', '<a name="03-10-2016" id="03-10-2016"></a><div class="news4 standard" style=""><div>\n						OPEN BETA Launch Thursday\n						<div>\n							03-10-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">Scientists have been swatting bugs like an albino in the Amazonas, and performed round-the-clock testing to the extent, that the lab rat union is threatening to run a blockage (yes, lab rats are organised these days). And it has paid off! The never-ending OPEN BETA to-do list has been depleted, and the lead scientist will punch in the secret launch codes on Thursday at noon. The countdown is on!<br>\n						<br>\n						Ps. the intern got the launch codes for OPEN BETA and the self-destruct codes for the laboratry\'s nuclear core mixed up, so we\'ll start handing out hazmat suits tomorrow. Be sure to come back and claim yours!</div></div>'),
('2016-10-03', 1, 'news4 halloween', 'Something Lurks in the Shadows..', '<a name="03-10-2016" id="03-10-2016"></a><div class="news4 halloween" style=""><div>\n						Something Lurks in the Shadows..\n						<div>\n							03-10-2016\n						</div>\n					</div><div>All Hallows\' Eve is coming up. While you strategise on how to most efficiently loot your neighbourhood down to the last tic-tac, we suggest you suit up your tank for the job at hand. Scoot off to the garage and equip a ghastly tankcessory.<br>\n						<br>\n						As for the scientists, the natural occurrence of supernatural odds and sods in the gloomy corridors of the underground laboratory will have to make do. We are too busy with OPEN&nbsp;BETA. Speaking of which, check back later today - we have more news...</div></div>'),
('2016-10-06', 0, 'news4 standard', 'BETA is Open', '<a name="06-10-2016" id="06-10-2016"></a><div class="news4 standard" style=""><div>\n						BETA is Open\n						<div>\n							06-10-2016\n						</div>\n					</div><div style="background: url(\'images/betaAccessNewsBackground.png\') no-repeat;">What\'s there to say besides:<br>\n			<br>\n			<div style="text-align: center;">\n				<a class="text large" href="https://beta.tanktrouble.com">Go test your mad tank-driving, bullet-dodging skills in BETA</a>\n			</div>\n			<br>\n			Don\'t forget this is a test version of TankTrouble ONLINE.\n			It is still in development.	Therefore you might experience laggy combat, strange things or run into the odd bug. But rest assured, the scientists are working on it!<br>\n			<br>\n			<span class="text small">Note:<br>\n			If you made it to the end of the previous news, you are probably pleased that the underground laboratory is still operational. Luckily, the lead scientist punched in the correct launch codes and obviated a nuclear core meltdown. Hence, we will stop handing out hazmat suits today as they are no longer necessary and don\'t come cheap. Besides, a hazmat suit wouldn\'t have done much good anyhow if a nuclear core meltdown blew up the underground laboratory. We just handed them out to provide a false sense of security.</span></div></div>'),
('2016-12-16', 0, 'news4 standard', 'A Long Time Ago in the Siberian Underground Far, Far Away...', '<a name="16-12-2016" id="16-12-2016"></a><div class="news4 standard" style=""><div>\n						A Long Time Ago in the Siberian Underground Far, Far Away...\n						<div>\n							16-12-2016\n						</div>\n					</div><div>...a team of scientists located a mythical, cold-war research laboratory, believed to have been obliterated by the Soviet government. In the depths of the dusty, abandoned complex they resurrected the remains of the diabolic experiment once conceived here, codenamed TankTrouble. That is nine years ago today, exactly.<br>\n			<br>\n			Now you might think that nine years in the Siberian underground, with no natural light, living of mostly canned food from the Cold War has reduced us to a bunch of fruitcakes. But you couldn\'t be more wrong. Humans are made of 70% H2O and a fruitcake is mostly flour, so it is simply not scientifically possible.<br>\n			<br>\n			This anniversary the master chef has prepared a delicious - he claims - French dish called D&#233;licieux Rat Frit. Last time the chef ventured of the beaten cabbage path, he burned down the cantina when flamb&#233;ing pancakes so scientists look forward to supper with some anxiety.<br>\n			<br>\n			In case we don\'t make it, you should know that it has been nine fantastic years - we couldn\'t have made it without you.<br>\n			<br>\n			From Siberia with Love, over and out.</div></div>'),
('2016-12-25', 0, 'news4 christmas', 'Santa Finally Made it to Siberia', '<a name="25-12-2016" id="25-12-2016"></a><div class="news4 christmas" style=""><div>\n						Santa Finally Made it to Siberia\n						<div>\n							25-12-2016\n						</div>\n					</div><div>We hope that your Christmas morning raid was gratifyingly lucrative. Ours was. On the surface, at the entrance to our underground laboratory, we found a giant Christmas present with a huge red ribbon (very pretty indeed) and a small note.\n			The note read:<br>\n			<br>\n			<span style="font-style: italic">"Dear Scientists,<br>\n			<br>\n			I\'ve been trying to deliver your Christmas present for a couple of years, but your top-secret, underground laboratory is super hard to find. Anyways, Rudolph finally tracked you down, and I hope you like what I\'ve dropped off for you: The nuclear reactor I used at my <span style="text-decoration: line-through">sweat</span>workshop. My supply chain does not support production of nuclear reactors, so I give you a retired one of mine instead - I\'ve decided to switch to sustainable energy anyways. It seems to be the trend these days. Also, after a minor leak from a reactor in one of my <span style="text-decoration: line-through">sweat</span>workshops back in \'86, the elves now have 4 arms and work twice a fast, which will make up for the added cost of going green.<br>\n			<br>\n			Merry Christmas boys,<br>\n			Santa"</span><br>\n			<br>\n			The underground laboratory is ecstatic with joy; Scientists foresee no end to the list of destructive inventions with an in-house nuclear reactor at their disposal.<br>\n			<br>\n			With that said, all the underground scientists in Siberia, wish you a merry Christmas.</div></div>'),
('2017-01-01', 0, 'news4 standard', 'New Year\'s Fallout and Glow-in-the-dark Pepperoni', '<a name="01-01-2017" id="01-01-2017"></a><div class="news4 standard" style=""><div>\n						New Year\'s Fallout and Glow-in-the-dark Pepperoni\n						<div>\n							01-01-2017\n						</div>\n					</div><div>We have spent the Christmas Holidays munching cookies and making room for our brand new (slightly used) nuclear reactor. Santa had to leave it outside as it wouldn\'t fit in the rocket silo, and it\'s been standing there since.<br>\n			<br>\n			At 2000 hours we sent the intern to the surface to pick up our take-away New Years pizzas (the delivery was ridiculously expensive) and when he came back, he had an odd glow about him. Turns out that Santa forgot to put new cooling rods in the reactor before making the delivery and even the blistering cold Siberian winter couldn\'t stop the thing from melting down. What a bummer.<br>\n			<br>\n			On the upside, the nuclear fallout made for the most beautiful, neon-green vista when the scientists emerged in their hazmat suits for the traditional midnight rocket extravaganza. Surrounded by fluorescent deer and squirrels and uncontrollably exploding fireworks, they thought back on the year gone by.<br>\n			<br>\n			2016 was the year we finally passed 2 billion scraps and TankTrouble Online was released for open testing among all you wonderful guinea pigs. We promise to keep working hard on it - if we can get any sleep from this pesky glowing-in-the-dark thing we all seem to have developed. Maybe we shouldn\'t have eaten those pizzas.<br>\n			<br>\n			Let\'s all wish each other a scrappy New Year!</div></div>'),
('2017-02-15', 0, 'news4 standard', 'The Scrapyard has gone Bonkers!', '<a name="15-02-2017" id="15-02-2017"></a><div class="news4 standard" style=""><div>\n						The Scrapyard has gone Bonkers!\n						<div>\n							15-02-2017\n						</div>\n					</div><div>At 0900 hours, the scrapyard ran out of bits. This has resulted in some wonky behaviour to put it mildly.<br>\n            <br>\n            Do not panic! It is quite harmless. Those of you who remember the incidents in late 2014 when <a href="#10-11-2014">scrapyard digits were on the loose and the entire laboratory evacuated</a> know that we speak from experience.<br>\n            <br>\n            We\'ve got the lead scrapyard scientist on the case, but he seems to have developed a taste for Mai Tais since his <a href="#17-11-2014">trip to the Bahamas</a>, so we have no idea how long it will take.<br>\n            <br>\n            If you\'re dying to know the exact amount of scraps, head over to the BETA site where the scrapyard is counting onwards with the precision of Swiss clockwork.<br>\n            <br>\n            And don\'t worry: Your scraps are still registered correctly!</div></div>'),
('2017-04-10', 0, 'news4 special', 'Dimitri\'s Emporium Opens', '<a name="10-04-2017" id="10-04-2017"></a><div class="news4 special" style=""><div>\n						Dimitri\'s Emporium Opens\n						<div>\n							10-04-2017\n						</div>\n					</div><div><div style="text-align: center"><img src="../images/dimitrisEmporium.png"></div>As the Intern was cleaning the underground corridors the vacuum cleaner lost suction. After thorough inspection the scientists\' verdict was unambiguously clear: The laboratory\'s 1952 vacuum cleaner was finally full. Unaware that the dust bag could simply be replaced, Dimitri decided to solve the problem by upgrading the vacuum cleaner with an onboard trash compactor - a powerful one as it turned out. And when the Intern proceeded with his duties, the radioactive smut in the corridors got compacted into rock-like stuff. We have dubbed it Dimitrium.<br><br>\nDimitri believes Dimitrium is the key to unlimited unsustainable energy that he has been searching for since he invented the Death Ray. Therefore he has opened a shop hoping to lure you to exchange the Dimitrium you find in the mazes for some cool tank swag salvaged by the scavenger team<br><br>Visit Dimitri\'s shop on <a href="https://beta.tanktrouble.com">beta.tanktrouble.com</a></div></div>'),
('2017-04-28', 0, 'news standard', 'Tag Line Competition 2017 - Final Judgement', '<a name="28-04-2017" id="28-04-2017"></a>\n				<div class="news standard">\n					<div class="header">Tag Line Competition 2017 - Final Judgement\n						<div>\n							28-04-2017\n						</div>\n					</div>\n					<div class="content"><div id="poll-9-content" class="middle text small">The forum has spoken. Five cleverly thought up tag lines have been nominated for the final round of judgement. One will make it to the front page.<br/>&nbsp;<br/><div id="poll-9-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-9-closedSign" src="images/thisPollIsClosed.png"/></div>Cast your vote for the next TankTrouble tag line<br/><br/></div></div><table id="poll-9-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer250.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Tanks \'N\' Trouble, Watch Out, Before you turn to Rubble<br>(by QuickNinja64) <span class="text tiny">(434 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											It\'s life or death, go ahead and take your final breath<br>(by SerpentsVenom) <span class="text tiny">(151 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 121.77419354839px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Go out with a boing!<br>(by supervolcano) <span class="text tiny">(89 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 71.774193548387px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											A game so simple, a dog can play it!<br>(by george8888) <span class="text tiny">(89 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 71.774193548387px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Be fast or join the past<br>(by Firestorm16) <span class="text tiny">(111 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 89.516129032258px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2017-05-18', 0, 'news4 standard', 'Another Tag Line Sees the Light of Day', '<a name="18-05-2017" id="18-05-2017"></a><div class="news4 standard" style=""><div>\n						Another Tag Line Sees the Light of Day\n						<div>\n							18-05-2017\n						</div>\n					</div><div><div style="text-align: center;">\n					The winner of the 2017 TankTrouble Tag Line Competition is QuickNinja64 with:<br>\n					<br>\n					<span class="text large" style="font-style: italic;">Tanks \'n\' Trouble - Watch out, before you turn to rubble</span>\n				</div>\n				<br>\n				The scientists are quite delighted by the implied destruction of this little rhyming composition. It has been added to the growing list of tag lines on the front page.</div></div>'),
('2017-06-22', 0, 'news4 standard', 'Hacking Rumour Mill', '<a name="22-06-2017" id="22-06-2017"></a><div class="news4 standard" style=""><div>\n						Hacking Rumour Mill\n						<div>\n							22-06-2017\n						</div>\n					</div><div>Lately, the forums have been abuzz with rumours of hacking and stolen tanks. Please rest assured that your TankTrouble account is safe as long as you make sure your password is impossible to guess and you don\'t share your password with anyone. Not even your mom, your best friend, your dog, or your pet T-Rex.<br>\n			&nbsp;<br>\n			If you follow these guidelines, your password will never leave the fortified server bunker of the Siberian underground. Not even the scientists can see your password as it is stored as completely encrypted mumbo jumbo.</div></div>'),
('2017-07-01', 0, 'news4 standard', 'TTOC About to Kick Off!', '<a name="01-07-2017" id="01-07-2017"></a><div class="news4 standard" style=""><div>\n						TTOC About to Kick Off!\n						<div>\n							01-07-2017\n						</div>\n					</div><div>The laboratory would like to host tournaments but we do not have the technical capabilities yet. Now it seems enthusiastic players have taken matters into their own hands as they are about to kick off TTOC - TankTrouble Online Competition! TTOC takes place on BETA where contestants will compete in various game modes. Awesome!<br>\n			<br>\n			Although the TTOC is officially absolutely unofficial the laboratory officially supports it, and Dimitri\'s Emporium has sponsored great prizes.<br>\n			<br>\n			To secure your seat in TTOC and for more information keep an eye on the forum. Good luck everyone!</div></div>'),
('2017-10-01', 0, 'news4 halloween', 'The Lab Gears up for Another Spooktacular October', '<a name="01-10-2017" id="01-10-2017"></a><div class="news4 halloween" style=""><div>\n						The Lab Gears up for Another Spooktacular October\n						<div>\n							01-10-2017\n						</div>\n					</div><div>Once again, winter is coming and the darkness is returning. It\'s the scientists\' favourite time of the year and the laboratory has been working around the clock to prepare for the upcoming celebration of all things spooky and chewy: Halloween!<br>\n<br>\nIn addition to the regular, ghoulish accessories, the scientists have been conducting new supernatural experiments. <a href="https://beta.tanktrouble.com">See the other-worldly outcome on BETA!</a></div></div>'),
('2017-10-27', 0, 'news4 standard', 'Contributions from Devoted TankTroublers Get Featured in the Lab', '<a name="27-10-2017" id="27-10-2017"></a><div class="news4 standard" style=""><div>\n						Contributions from Devoted TankTroublers Get Featured in the Lab\n						<div>\n							27-10-2017\n						</div>\n					</div><div>\nRecently the scientists discovered <a href="" id="theLabReport">The Lab Report</a>, an independent newspaper created by devoted players reporting all things TankTrouble! When isolated in a secret research facility deep in the Siberian underground, spending all day developing tanks, the appetite for news from the surface is insatiable. Especially news about tanks! So while shoving down grub in the cantina the scientists like to read up on the latest The Lab Report.<br>\n<br>\nAnd that\'s just one in many contributions created by players.The scientists love to spend the scarce breaks trawling the oodles of Youtube channels, illustrations, groups and whatnots out there, and they stand in awe.<br>\n<br>\nWe have featured a few player-made contributions in the lab: <a href="?lab">Get the latest Lab Report or download the TankTrouble Trading Cards.</a>\n<script type="text/javascript">\n	<!--\n	document.getElementById("theLabReport").onclick = function()\n	{\n		window.open("theLabReport", "_blank", "width=460,height=535,left="+(screen.width-460)/2+",top="+(screen.height-535)/2+",resizable=0,toolbar=0,location=0,status=0,menubar=0, scrollbars=1,directories=0");\n		return false;\n	}\n	//	-->\n</script></div></div>'),
('2017-11-30', 0, 'news4 kickstarter', 'Kickstarter Comes to a Close', '<a name="30-11-2017" id="30-11-2017"></a><div class="news4 kickstarter" style=""><div>\n						Kickstarter Comes to a Close\n						<div>\n							30-11-2017\n						</div>\n					</div><div>\nThe scientists have been slaving away on bringing TankTrouble online for almost three years. Some of them have grown so pale from never leaving the underground laboratory that we have started using them as night lights - great for saving on our already astronomical electricity consumption!<br>\n<br>\nAnyway, the Beta opened (slightly delayed) in July of 2015, but that was only the beginning as the work on creating new features never ends. In fact, even though we accomplished all the goals and handed out all the rewards of the campaign quite a while ago, we\'ve been so busy that we forgot to announce that the Kickstarter campaign is now officially over. Well it is!<br>\n<br>\nThe game is still in Beta but we are fast approaching a proper release. Up next on the scientists\' plate is new battle modes, which will spice up the destruction more than the laboratory master chef\'s infamous chilli con carne (consuming it has been classified as torture by several human rights organisations).<br>\n<br>\nIt\'s been a bumpy ride but a great adventure, and we want to extend a big heartfelt thank-you to all who backed us. You have been a great help and we are eternally grateful for the opportunity. <a href="https://beta.tanktrouble.com">Now go play what you\'ve helped put into the world</a>!\n</div></div>'),
('2017-12-01', 0, 'news4 christmas', 'Let it Snow, Let it Snow, Let it Snow', '<a name="01-12-2017" id="01-12-2017"></a><div class="news4 christmas" style=""><div>\n						Let it Snow, Let it Snow, Let it Snow\n						<div>\n							01-12-2017\n						</div>\n					</div><div>\nHere in the Siberian underground we are slowly gearing up for the yearly ginger bread munching and Christmas carolling fiesta. To get in the right spirit, the Accessory Team took on the immense task of decorating the dreary BETA wing of the laboratory. They spent several days reaching just the right balance of nice, cozy and jolly.<br>\n<br>\nUnfortunately, the intern left the surface hatch open as the master chef sent him to collect ingredients for snow cones. He hadn\'t been gone for more than five minutes when a huge blizzard swept the freezing planes surrounding the laboratory and pushed a few metric tonnes of snow down the hatch.<br>\n<br>\nBefore a hungry T-Rex could even begin to think about hotdogs, all the decorations and goodies were ripped off the walls and scattered on the floor and the tunnels were filled with snow. Bummer! On the bright side, the intern hasn\'t been seen since and now we can make our own snow cones rather than eat the chef\'s suspicious yellow variant.<br>\n<br>\nThe Accessory Team have not been knocked out by this minor setback and will be doling out Christmas accessories throughout December. New tanks (or those of you who missed out last year) are reminded to log in every day until Christmas Day to collect all the jolly swag you can handle.\n</div></div>'),
('2017-12-16', 0, 'news4 special', 'TankTrouble Celebrates a Decade of Destruction', '<a name="16-12-2017" id="16-12-2017"></a><div class="news4 special" style=""><div>\n						TankTrouble Celebrates a Decade of Destruction\n						<div>\n							16-12-2017\n						</div>\n					</div><div>\nOn this day, 10 years ago, in an abandoned, research facility hidden deep in the Siberian wastelands a small team of scientists resurrected a long forgotten, cold war experiment codenamed TankTrouble. This was the beginning of an era of an inexhaustible supply of destruction. And it doesn\'t end here!<br>\n<br>\n<div style="position: relative; padding-right: 240px;">\n	<img src="../images/anniversaryCake.png" style="position: absolute; top: -75px; right: 10px;">\n	Fuelled by canned food from the Cold War and the occasional musk ox snack our appetite for destruction has not diminished. To kick off the next decade the scientists have unleashed:<br>\n	<br>\n	<div style="text-align: center;">\n		<span class="text large" style="font-weight: bold;">Deathmatch</span><br>\n		Join us on BETA now and help us celebrate!<br>\n	</div>\n	<br>\n	In addition, the master chef has started a mass production of festive birthdays cakes utilising the nuclear core for maximum baking capacity to meet the expected high demand. Get your slice now from Dimitri\'s Emporium while supplies last!<br>\n</div></div></div>'),
('2017-12-24', 0, 'news4 christmas', 'All we Want for Christmas is...', '<a name="24-12-2017" id="24-12-2017"></a><div class="news4 christmas" style=""><div>\n						All we Want for Christmas is...\n						<div>\n							24-12-2017\n						</div>\n					</div><div>\nA battery of ballistic missiles!<br>\n<br>\nEver since the cataclysmic nuclear reactor meltdown of last Christmas season, the lab has decided to dial down the expectations and wish for something a little more safe and less explosive. Apparently, Santa can not be trusted to safely handle something as trivial as a nuclear fission process. Who would have known?<br>\n<br>\nIn the lab, the scientists are getting ready for the Christmas present festivities of tomorrow morning while they are sipping eggnog and melting the snow in the corridors with flamethrowers. All in all, it seems that the seasonal peace and quiet has found its way to the Siberian underground.<br>\n<br>\nOh, the intern is back. We found him outside munching acorns stolen from a nearby squirrel and hugging a rocket silo exhaust vent for warmth. This means the whole team is back together and we all wish you a merry Christmas!\n</div></div>'),
('2018-03-05', 0, 'news standard', 'Tag Line Competition 2018', '<a name="05-03-2018" id="05-03-2018"></a>\n				<div class="news standard">\n					<div class="header">Tag Line Competition 2018\n						<div>\n							05-03-2018\n						</div>\n					</div>\n					<div class="content"><div id="poll-10-content" class="middle text small">Once again the unofficial, annual TankTrouble tag line battle in poetic destruction went down on the forum. The scientists have picked three nominees for the most TankTroublish tag line. The winner will be immortalised on the front page.<br/>&nbsp;<br/><div id="poll-10-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-10-closedSign" src="images/thisPollIsClosed.png"/></div>The nominees are:<br/><br/></div></div><table id="poll-10-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer250.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											The race of destruction needs no instruction<br>(by isaigirraffe31) <span class="text tiny">(636 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											You start with a pounding heart and shoot to take tanks apart!<br>(by -Rage-) <span class="text tiny">(247 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 135.92767295597px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											You have met your doom, I shoot one bullet and you go kaboom!<br>(by YoHypeBroYT) <span class="text tiny">(160 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 88.050314465409px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2019-03-28', 0, 'news standard', 'Tag Line Competition 2019', '<a name="28-03-2019" id="28-03-2019"></a>\n				<div class="news standard">\n					<div class="header">Tag Line Competition 2019\n						<div>\n							28-03-2019\n						</div>\n					</div>\n					<div class="content"><div id="poll-11-content" class="middle text small">The annual TankTrouble tag line dogfight on the forum has once again left three contenders standing on the battlefield. It is now up to you to pick the final winner, which will be proudly displayed on the front page.<br/>&nbsp;<br/><div id="poll-11-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-11-closedSign" src="images/thisPollIsClosed.png"/></div>The contenders are:<br/><br/></div></div><table id="poll-11-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer250.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Shoot, dodge, win. Let the games begin.<br>(by isaigirraffe31) <span class="text tiny">(913 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 331.48340248963px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											When in doubt, just blast \'em out!<br>(by TripleStryke) <span class="text tiny">(964 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Surrender or lose, which one will you choose?<br>(by Platygamer) <span class="text tiny">(129 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 46.836099585062px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2019-05-10', 0, 'news4 standard', 'Trading Cards Series III Deployed', '<a name="10-05-2019" id="10-05-2019"></a><div class="news4 standard" style=""><div>\n						Trading Cards Series III Deployed\n						<div>\n							10-05-2019\n						</div>\n					</div><div>\n<div style="position: relative; padding-right: 160px;">\n	<img src="../images/tradingCard.png" style="position: absolute; right: 15px;"/>\n	Series III adds 7 new cards to this scientist pasttime favourite. It includes an urban legend and a sugar coated torus. The rules for playing the latter is unclear to the scientists. We hope the next issue of The Lab Report will shed some light on the matter.<br>\n	<br>\n	TankTrouble trading cards are made by a team of diehard tanktroublers with kudos from the underground laboratory.<br>\n	<br>\n	You can download series III <a href="/?lab">here</a>\n</div></div></div>'),
('2019-06-17', 0, 'news standard', 'To Rank or not to Rank', '<a name="17-06-2019" id="17-06-2019"></a>\n				<div class="news standard">\n					<div class="header">To Rank or not to Rank\n						<div>\n							17-06-2019\n						</div>\n					</div>\n					<div class="content"><div id="poll-12-content" class="middle text small">The laboratory has received many reports from concerned tankers regarding ranks and their effect on battles. While some tankers enjoy ranks, others find that they have made TankTrouble too competitive. The scientists are at a loss.<br/>&nbsp;<br/><div id="poll-12-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-12-closedSign" src="images/thisPollIsClosed.png"/></div>What\'s your say on ranks?<br/><br/></div></div><table id="poll-12-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer150.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											"Ranks are too competitive! Get rid of \'em" <span class="text tiny">(187 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 145.76837416481px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											"Ranks are cool! Keep \'em as they are" <span class="text tiny">(131 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 102.11581291759px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											"Just make ranked battles optional. The best of both worlds" <span class="text tiny">(449 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>'),
('2019-07-09', 0, 'news4 standard', 'Ranks Have Been Ranked', '<a name="09-07-2019" id="09-07-2019"></a><div class="news4 standard" style=""><div>\n						Ranks Have Been Ranked\n						<div>\n							09-07-2019\n						</div>\n					</div><div>\nThe tankers have spoken up about ranks and they want to have it both ways - of course!\nThis means that the scientists will have to abandon their straightforward plan of simply unplugging the Rank-Meister 2048 server, but they are pleased that ranks will still be able to separate the wheat from the chaff - or the 1337 from the n00bs as the intern puts it (nobody here understands what he\'s saying).<br>\n<br>\nNow begins the hard work of figuring out where all those many miles of cable running from the Rank-Meister 2048 actually go and what they do. This complex task will take all the spaghetti-untangling skills of the entire lab and the lead scientist has prepared a small roadmap for you to peruse while you wait.<br>\n<br>\n<div style="background-color: #dddddd; border-radius: 6px; padding: 10px;">\n    <div class="text large" style="text-align: center;">\n        Planned rank implementation\n    </div>\n    <ul>\n        <li>Battles will be unranked by default - boo!</li>\n        <li>Ranks can be enabled when creating a new battle</li>\n        <li>Ranked battles will deploy tanks more fairly - no more cheap spawn kills</li>\n        <li>Mazes for ranked battles will be more symmetric</li>\n        <li>Tanks can choose not to show their rank to others - except in ranked battles of course</li>\n    </ul>\n</div></div></div>'),
('2020-04-17', 0, 'news standard', 'Tag Line Competition 2020', '<a name="17-04-2020" id="17-04-2020"></a>\n				<div class="news standard">\n					<div class="header">Tag Line Competition 2020\n						<div>\n							17-04-2020\n						</div>\n					</div>\n					<div class="content"><div id="poll-13-content" class="middle text small">The annual TankTrouble tag line competition is back and the field has been shaved down to four rivals. We leave it up to you to pick the champion that will have his tag line put on the front page.<br/>&nbsp;<br/><div id="poll-13-question" class="text medium" style="width: 100%; text-align: center; position: relative;"><div style="position: absolute; top: -10px; left: 480px;"><img id="poll-13-closedSign" src="images/thisPollIsClosed.png"/></div>The prospects are:<br/><br/></div></div><table id="poll-13-results" style="height: 1px; margin: auto;"><tr><td><img src="images/pollSpacer250.png"/></td><td><table style="height: 100%;"><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											A scrapyard of debris and rubble, welcome to tanks, traps, and trouble.<br>(by YD109) <span class="text tiny">(1999 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarGreenLeft.jpg"/><img src="images/pollBarGreenMiddle.jpg" style="width: 350px; height: 21px;"/><img src="images/pollBarGreenRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											Very simple, Very fun! And it\'s free for everyone!<br>(by Mirror) <span class="text tiny">(89 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarRedLeft.jpg"/><img src="images/pollBarRedMiddle.jpg" style="width: 15.582791395698px; height: 21px;"/><img src="images/pollBarRedRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											This game is only for the brave-hearted.<br>(by Dad) <span class="text tiny">(1261 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 220.78539269635px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr><tr>\n								<td style="height: 21px;">\n									<div style="position: absolute;">\n										<div style="position: relative; top: 4px; left: 0px;">&nbsp;\n											In this world I cause trouble, try and compete with me and you\'ll be rubble!<br>(by YoHypeBroYT) <span class="text tiny">(248 votes)</span>\n										</div>\n									</div>\n									<img src="images/pollBarYellowLeft.jpg"/><img src="images/pollBarYellowMiddle.jpg" style="width: 43.421710855428px; height: 21px;"/><img src="images/pollBarYellowRight.jpg"/>\n								</td>\n							</tr></table></td></tr></table></div>\n					<div class="bottom">\n					</div>\n				</div>');
